(window.GIM_TS=window.GIM_TS||{})["Gittin.2"]={"from":48,"a":[["ואם \u0003לא רצה האב\u0004 — \u0003אינה מקודשת.\u0004 משמע שבמקום שתולה בדעת אחרים סבור ר' שמעון שיש ברירה, שהרי לפי רצון האב מתברר אם היו אלה קידושין, או לא!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב משרשיא: \u0003בין ל\u0004שיטת \u0003ר' יהודה בין ל\u0004שיטת \u0003ר' שמעון, לא שנא\u0004 \u0005[אינו שונה]\u0006 אם היה \u0003תולה בדעת עצמו, ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם היה \u0003תולה בדעת אחרים\u0004 — בכל מקרה \u0003אית להו\u0004 \u0005[יש להם,\u0006 הריהם מקבלים\u0005]\u0006 את העיקרון של \u0003ברירה,\u0004","\u0003והתם\u0004 \u0005[ושם]\u0006 במקרה של קונה יין מן הכותי אין הם אוסרים מחמת שהם סבורים שאין ברירה, אלא \u0003כדקתני טעמא\u0004 \u0005[כפי ששנה\u0006 שם את \u0005הטעם]\u0006 במפורש: \u0003אמרו לו\u0004 אותם חכמים \u0003לר' מאיר:\u0004 וכי \u0003אי\u0004 (אין) \u0003אתה מודה,\u0004 שיש לחשוש \u0003שמא יבקע הנוד\u0004 לאחר שישתה חלק מן היין, ויישפך כל מה שנשאר בתוכו בלא שהפריש דבר, \u0003ונמצא זה שותה טבלים למפרע?\u0004 ולכן גזרו מחשש שלא יגיע הדבר כלל לידי ברירה, ולא משום שאין הם מקבלים באופן כללי את העיקרון של ברירה. \u0003אמר להם\u0004 ר' מאיר: אין אני חושש לאפשרות כזו, אלא \u0003לכשיבקע\u0004 אכן תיווצר פה בעיה. ומכל מקום, לכל הדעות כאשר יפריש תהא הפרשתו מועילה מטעם ברירה.","סופר \u0003הכותב טופסי גיטין,\u0004 שהוא כותב את הנוסח הכללי הקבוע של הגט ומכין אותו מראש, כדי שאם יבוא אדם אליו ויבקשו לכתוב עבורו גט יצטרך להוסיף רק את הפרטים המיוחדים, \u0003צריך שיניח\u0004 פנוי את ה\u0003מקום\u0004 בגט בו ייכתב שם \u0003האיש,\u0004 וכן את ה\u0003מקום\u0004 בו ייכתב שם \u0003האשה, ו\u0004כן את \u0003מקום הזמן\u0004 בו נכתב הגט.","ואם הסופר כותב טפסים של \u0003שטרי מלוה\u0004 — \u0003צריך שיניח מקום\u0004 שם \u0003המלוה, מקום\u0004 שם \u0003הלוה, מקום המעות\u0004 (סכום הכסף של ההלוואה), ו\u0003מקום הזמן\u0004 בו נעשה \u0003ההלוואה.\u0004","ואם כותב הסופר טפסים של \u0003שטרי מקח,\u0004 שטרי מכירה של קרקע — \u0003צריך שיניח מקום\u0004 בשטר בו ייכתב אחר כך שם \u0003הלוקח, ומקום\u0004 שם \u0003המוכר, מקום\u0004 סכום \u0003המעות, מקום השדה\u0004 שאותו קונה, \u0003ומקום הזמן\u0004 בו נקנה השדה, וכל זה עשו \u0003מפני התקנה\u0004 כאשר יבואר בגמרא.","\u0003ר' יהודה פוסל בכולן,\u0004 בכל השטרות הללו אם נכתבו מראש טפסיהם בלבד. ואילו \u0003ר' אלעזר מכשיר בכולן, חוץ מגיטי נשים,\u0004 \u0003ש\u0004הרי בהם \u0003נאמר: \"וכתב לה\"\u0004 (דברים כד, א) — \u0003לשמה,\u0004 ואינו יכול לכתוב מראש אף חלק מן הגט בלי שיידע לשם מי נכתב הגט, שהרי אין זו כתיבה לשמה.","\u0003אמר רב יהודה אמר שמואל: צריך\u0004 הסופר \u0003שיניח\u0004 בטופס הגט \u0003אף מקום\u0004 לכתיבת הנוסח: \u0003\"הרי את מותרת\u0004 \u0003לכל אדם\",\u0004 שהוא עיקרו של הגט, \u0003ו\u0004סתם משנתנו שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 הם העושים את הכריתות שבגט, את גמר הגט, \u0003ובעינן\u0004 \u0005[וצריכים אנו]\u0006 שתהיה \u0003כתיבה\u0004 של עיקר הגט \u0003לשמה.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו דברי שמואל שמשנתנו כשיטת ר' אלעזר, גם כאן לענין כתיבת טופסי גיטין וגם במשניות שבפרק הקודם לענין כתיבה במחובר לקרקע, ובענין כתיבת גט על ידי חרש שוטה וקטן.","\u0003דאי אשמעינן הך קמייתא\u0004 \u0005[שאם היה משמיע לנו\u0006 רק את \u0005זו,\u0006 את המשנה \u0005הראשונה]\u0006 שאין כותבים על המחובר, הייתי אומר שדווקא \u0003בההיא\u0004 \u0005[באותה]\u0006 המשנה \u0003הוא דאיכא לאוקמה\u0004 \u0005[שיש להעמידה,\u0006 להסבירה\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אלעזר,\u0004 כיון \u0003דקתני\u0004 \u0005[ששנה]\u0006 שם בלשון \u0003\"אין כותבין\" וקתני\u0004 \u0005[ושנה]\u0006 בה \u0003\"כתבו\",\u0004 שעיקרו של הגט בכתיבה,","\u0003אבל סיפא\u0004 \u0005[\u0006ב\u0005סוף\u0006 המשנה האחרת\u0005]\u0006 בענין כתיבת הגט על ידי פסולים, שהתיר שיכתבו, \u0003דקתני\u0004 \u0005[ששנה]\u0006 ואמר טעמו \u0003\"שאין קיום הגט אלא בחותמיו\", אימא\u0004 \u0005[אמור]\u0006 ששיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: עדי חתימה כרתי\u0004 \u0005[כורתים],\u0006 הם הגומרים את הכריתות שבגט, ולכן היה צריך לומר שאלו דברי ר' אלעזר.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 כך \u0003בההיא\u0004 \u0005[באותה]\u0006 משנה, אפשר לומר: \u0003ההיא נמי איכא לאוקמה\u0004 \u0005[אותה גם כן אפשר להעמיד]\u0006 \u0003כר' אלעזר\u0004 כפי שהסברנו שמדובר בכתיבה של הטופס, והכוונה ב\"חותמיו\" היא לעדי מסירה, \u0003אבל הא\u0004 \u0005[\u0006משנה \u0005זו]\u0006 שלנו \u0003אימא\u0004 \u0005[אמור]:\u0006 \u0003מדסיפא\u0004 \u0005[מכיון שסופה]\u0006 שיטת \u0003ר' אלעזר הוי\u0004 \u0005[הוא]\u0006 ועליה נזכר שמו — \u0003רישא לאו\u0004 \u0005[תחילתה אינה]\u0006 כשיטת \u0003ר' אלעזר,\u0004 על כן \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמר הדבר לגבי שלוש המשניות.","שנינו במשנה: \u0003מפני התקנה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003תקנה\u0004 זו? \u0003אמר ר' יונתן: מפני תקנת סופר,\u0004 שיוכל להכין לעצמו מראש טפסים כאלה, כדי שאם יבוא אליו לקוח, לא יצטרך לכתוב את הגט במהירות. \u0003ו\u0004שיטת \u0003ר' אלעזר היא,\u0004 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 \u0003ו\u0004לפי שיטה זו \u0003בדין הוא\u0004 ש\u0003אפילו טופס נמי\u0004 \u0005[גם כן]\u0006 \u0003לא לכתוב\u0004 \u0005[יכתוב],\u0006 משום שלכתחילה ראוי שייכתב גם הוא לשמה, \u0003ומשום תקנת סופרים שרו רבנן\u0004 \u0005[התירו חכמים].\u0006","עוד שנינו במשנתנו: \u0003ר' יהודה פוסל בכולן,\u0004 אף בשאר שטרות, אם לא נכתב השטר כולו לצורך אותו ענין. ומסבירים שר' יהודה \u0003גזר\u0004 פסול על כתיבת \u0003טופס אטו\u0004 \u0005[משום]\u0006 החשש שמא יבואו מתוך כך גם לכתוב מראש גם \u0003תורף\u0004 שהוא עיקרו של השטר. וכן \u0003גזר\u0004 בשאר \u0003שטרות\u0004 שאין בהם ענין של \"לשמה\" \u0003אטו\u0004 \u0005[משום]\u0006 \u0003גיטין.\u0004","עוד שנינו במשנתנו: \u0003ור' אלעזר מכשיר בכולן חוץ מגיטי נשים.\u0004 ומסבירים את טעמו: \u0003טופס אטו\u0004 \u0005[משום]\u0006 \u0003תורף גזר,\u0004 ולכן אמר שאין כותבים טופס של גט, אבל \u0003שטרות אטו\u0004 \u0005[משום]\u0006 \u0003גיטין לא גזר,\u0004 וסבור ששאר שטרות, מכיון שאינם צריכים כתיבה לשמה, יכול לכותבם מראש.","על מה ששנינו בסוף המשנה שר' אלעזר פוסל משום \u0003שנאמר \"וכתב לה\"\u0004 — לשמה, מקשים: \u0003והא כי כתיב\u0004 \u0005[והרי כאשר נאמר]\u0006 \u0003\"\u0004וכתב \u0003לה\"\u0004 שמשם נלמד דין לשמה בגט — \u0003אתורף\u0004 \u0005[על\u0006 ענין ה\u0005תורף]\u0006 \u0003הוא דכתיב\u0004 \u0005[שנאמר]\u0006 הדבר, ולא על הטופס של הגט, ומה שייך דבר זה לענייננו?","\u0003אלא אימא\u0004 \u0005[אמור]:\u0006 ר' אלעזר פוסל בטופס \u0003משום שנאמר\u0004 בתורף \u0003\"וכתב לה\"\u0004 — \u0003לשמה,\u0004 שכיון שכתיבת תורף לשמה היא מן התורה — גזר ר' אלעזר אף על כתיבת הטופס."],["ושואלים: \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי \u0003ר' אלעזר אדר'\u0004 \u0005[על דברי ר']\u0006 \u0003אלעזר!\u0004 שהרי אמרנו שראשית המשנה אף היא כדעת ר' אלעזר ושם נאמר שכותבים טופסי גיטין, ובסופה הוא אומר שאין כותבים! ומשיבים: מחלוקת \u0003תרי תנאי\u0004 \u0005[שני תנאים]\u0006 היא \u0003ו\u0004שניהם \u0003אליבא\u0004 \u0005[על פי שיטת]\u0006 \u0003ר' אלעזר.\u0004","\u0003ר' שבתי אמר\u0004 בשם \u0003חזקיה:\u0004 תקנה זו שהוזכרה במשנה אינה מפני מה התירו לסופר לכתוב מראש טופסי גיטין, אלא להיפך — מדוע תיקנו שלא יכתוב גם את התורף באותם טפסים ובו שמות של אנשים ונשים. והטעם הוא \u0003משום קטטה,\u0004 \u0003ו\u0004שיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר: עדי חתימה כרתי\u0004 \u0005[כורתים],\u0006 וכתיבת הגט אינה צריכה להיות דווקא לשמה,","\u0003ו\u0004לכן \u0003בדין הוא\u0004 ש\u0003אפילו תורף נמי\u0004 \u0005[גם כן]\u0006 יכול היה הסופר \u0003לכתוב\u0004 מראש, \u0003ו\u0004אולם \u0003זמנין דשמעה ליה לסופר דקא כתיב\u0004 \u0005[פעמים ש\u0006האשה \u0005שומעת את הסופר שכותב]\u0006 גט, וכתוב בו במקרה שמה, שהסופר מכין אותו מראש כשיזדמן גט לאשה בשם זה, \u0003וסברה איהו קאמר ליה\u0004 \u0005[ו\u0006היא \u0005סבורה\u0006 ש\u0005הוא,\u0006 בעלה \u0005אמר לו]\u0006 לכתוב עבורו גט, \u0003והוה\u0004 \u0005[ויש]\u0006 \u0003לה קטטה בהדיה\u0004 \u0005[איתו]\u0006 ולכן עשו תקנה שלא יכתבו מראש את תורף הגט שבו שם האיש והאשה.","ואילו \u0003רב חסדא אמר\u0004 בשם \u0003אבימי:\u0004 יש לפרש את משנתנו \u0003משום תקנת עגונות,\u0004 שלא תבוא האשה למצב שבו תישאר נעזבת, עגונה. כיצד? \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שפירש את משנתנו כשיטת \u0003ר' מאיר, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שפירשה כשיטת \u0003ר' אלעזר.\u0004","ומפרטים: \u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהוא כשיטת \u0003ר' מאיר,\u0004 ש\u0003אמר:\u0004 \u0003עדי חתימה כרתי\u0004 \u0005[כורתים],\u0006 גומרים את הגט, \u0003ובדין הוא\u0004 ש\u0003אפילו תורף נמי\u0004 \u0005[גם כן]\u0006 היה יכול \u0003לכתוב, ו\u0004מדוע אסרו? \u0003זמנין דהוה ליה\u0004 \u0005[פעמים שיש לו]\u0006 \u0003קטטה בהדה\u0004 \u0005[איתה],\u0006 עם אשתו, \u0003ורתח עלה\u0004 \u0005[ו\u0006הוא \u0005כועס עליה]\u0006 \u0003וזריק ליה ניהלה\u0004 \u0005[וזורק לה\u0006 את הגט\u0005]\u0006 \u0003ומעגן ומותיב לה\u0004 \u0005[ומושיב\u0006 ומשאיר \u0005אותה\u0006 כך\u0005]\u0006 גרושה רק מפני שהיה בידו כבר גט מוכן, ולכן תיקנו שלא יכינו גיטין שלמים מראש — כדי שיקח הדבר זמן בין שעת הקטטה ועד שהגט יהיה מוכן, ומתוך כך עשוי הבעל להירגע מכעסו, ולא יגרש את אשתו.","\u0003אמרי לה\u0004 \u0005[יש אומרים]\u0006 שהיא כשיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר: עידי מסירה כרתי\u0004 \u0005[כורתים],\u0006 גומרים את הגט, \u0003ובדין הוא\u0004 ש\u0003אפילו טופס נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 היה צריך \u0003לכתוב\u0004 משום גזירה שלא יבוא לכתוב את התורף, ומדוע התירו לכתוב? \u0003זמנין דבעי למיזל\u0004 \u0005[פעמים שרוצה\u0006 הבעל \u0005ללכת]\u0006 \u0003למדינת הים ולא אשכח ספרא\u0004 \u0005[ואינו מוצא סופר]\u0006 שיכתוב לו גט, \u0003ושביק לה ואזיל\u0004 \u0005[ומניח אותה והולך]\u0006 \u0003ומעגן ומותיב לה\u0004 \u0005[ומושיב,\u0006 משאיר \u0005אותה\u0006 כך\u0005],\u0006 ולכן תיקנו שאפשר יהיה לכתוב גט במהירות על ידי הוספת התורף בלבד.","שנינו שאחד הדברים שהם בכלל תורף הגט, הוא \u0003מקום הזמן.\u0004 ומעירים: \u0003קפסיק ותני\u0004 \u0005[פסק ושנה]\u0006 הלכה זו, \u0003לא שנא\u0004 \u0005[שונה]\u0006 אם היה זה גט \u0003מן הנישואין, ולא שנא\u0004 \u0005[שונה]\u0006 אם היה זה גט \u0003מן האירוסין.\u0004","ומעתה, \u0003בשלמא\u0004 \u0005[נניח]\u0006 בגט \u0003מן הנישואין, בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שיש צורך לכתוב זמן בגט \u0003משום בת אחותו,\u0004 שלא יחפה עליה אם זנתה תחתיו על ידי מתן גט בלי תאריך — \u0003איכא\u0004 \u0005[יש\u0006 בזה טעם\u0005],\u0006 \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום פירי\u0004 \u0005[פירות]\u0006 שלא תפסיד את פירות נכסיה המגיעים לה על פי דין, אם לא תוכל להוכיח מתי נתגרשה — \u0003איכא\u0004 \u0005[יש]\u0006 מקום לחשוש, ולכן צריך לכתוב זמן בגט.","\u0003אלא\u0004 בגט \u0003מן האירוסין, בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 שתיקנו זמן בגיטין \u0003משום בת אחותו\u0004 — \u0003איכא\u0004 \u0005[יש]\u0006 גם פה מקום לחשש זה, שיכול להיות שתיזנה גם מן האירוסין, \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003משום פירי\u0004 \u0005[פירות],\u0006 \u0003ארוסה מי אית לה פירי\u0004 \u0005[האם יש לה פירות]?\u0006 כי זכות הבעל בפירות נכסי אשתו ממילא אינה אלא משעת נישואין ולא קודם לכן. ואם כן, מה חשש יש בדבר ואין צורך לכתוב כלל זמן בגט זה!","\u0003אמר רב עמרם: הא מילתא שמעית מיניה דעולא\u0004 \u0005[דבר זה שמעתי ממנו, מעולא\u0006\u0005]\u0006 ש\u0003אמר\u0004 שזמן בגיטין נעשה \u0003משום תקנת ולד, ולא ידענא מאי ניהו\u0004 \u0005[ידעתי מה הוא]\u0006 דבר זה. \u0003כיון דשמעיתא להא דתניא\u0004 \u0005[ששמעתי את זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003האומר: \"כתבו גט לארוסתי,\u0004 \u0003לכשאכנסנה\u0004 (אשאנה) \u0003אגרשנה\u0004 בו \u0003\"\u0004— \u0003אינו גט, ואמר עולא: מה טעם\u0004 אינו גט? \u0003גזירה שמא יאמרו\u0004 האנשים: \u0003גיטה קודם לבנה,\u0004 שהרי ייתכן שכשישאנה יבוא עליה ויוולד לה בן, ויחשבו האנשים שלא נולד בכשרות, שהרי תאריך כתיבת הגט קודם ללידת הבן. אם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 הטעם שעל הסופר להניח את מקום הזמן בגט ארוסה, הוא \u0003גזירה שמא\u0004 יכנסנה ויגרשנה, ו\u0003יאמרו: גיטה קודם לבנה.\u0004","\u0003אמר ר' זירא אמר ר' אבא בר שילא אמר רב המנונא סבא אמר רב אדא בר אהבה אמר רב: הלכה\u0004 בענין טופסי גיטין \u0003כר' אלעזר\u0004 שהם פסולים. \u0003קרי\u0004 \u0005[קרא]\u0006 \u0003רב עליה\u0004 \u0005[עליו],\u0006 על \u0003ר' אלעזר: טובינא דחכימי\u0004 \u0005[המאושר שבחכמים],\u0006 שהלכה כמותו.","ושואלים: \u0003ואפילו בשאר שטרות נמי\u0004 \u0005[גם כן]\u0006 הלכה כר' אלעזר, שניתן להכין מראש טופסי שטרות? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב פפי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא: האי\u0004 \u0005[\u0006מסמך \u0005זה]\u0006 של \u0003אשרתא דדייני\u0004 \u0005[קיום הדיינים]\u0006 שנועד לקיים שטר חוב, \u0003דמיכתבה\u0004 \u0005[שנכתבת]\u0006 מראש \u0003מקמי דליסהדי סהדי אחתימת ידייהו\u0004 \u0005[לפני שמעידים העדים על חתימת ידם]\u0006 — \u0003פסולה. אלמא\u0004 \u0005[מכאן]\u0006 שאף שלבסוף התברר שהיה זה דבר נכון, מכל מקום אסור לעשות כן משום ש\u0003מיחזי כשיקרא\u0004 \u0005[נראה כשקר],\u0006 שכתבו את האישור לפני שביררו את הדבר. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 גם בשאר השטרות אם כותבים אותם לפני שהעיסקה נגמרת \u0003מיחזי כשיקרא\u0004 \u0005[נראה\u0006 הדבר \u0005כשקר]!\u0006","ואומרים: \u0003ו\u0004דבר זה שאמר רב פפי לפסול כתיבת שאר שטרות מראש בגלל שנראה כשקר \u0003ליתא\u0004 \u0005[אינו],\u0006 כלומר, אין לו קיום בהלכה, \u0003מ\u0004שום דברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן, אומר היה ר' מאיר: אפילו מצאו\u0004 לגט \u0003באשפה\u0004 כשהוא בלתי חתום, ו\u0003חתמו ונתנו לה\u0004 — \u0003כשר,\u0004 שכתיבת הגט אינה מעכבת. \u0003ואפילו רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא פליגי עליה\u0004 \u0005[נחלקו עליו],\u0006 על \u0003ר' מאיר\u0004 — \u0003אלא בגיטי נשים,\u0004 וטעמם: \u0003דבעינן\u0004 \u0005[שצריכים אנו]\u0006 שתהא \u0003כתיבה לשמה, אבל בשאר שטרות\u0004 — \u0003לא.\u0004","וראיה לדבר: ש\u0003אמר ר' אסי אמר ר' יוחנן: שטר שלוה בו\u0004 פעם אחת \u0003ופרעו\u0004 — \u0003אינו חוזר ולוה בו,\u0004 ומדוע? \u0003שכבר נמחל שעבודו,\u0004 שעם ההלוואה בשטר חל שעבוד על נכסי הלווה, ושעבוד זה פוקע עם פריעת החוב, ומאז פקע תוקפו של השטר הזה כשטר, ואינו עוד אלא כהלוואה בעל פה. ונדייק: \u0003טעמא\u0004 \u0005[הטעם,\u0006 דווקא\u0005]\u0006 משום ש\u0003נמחל שעבודו, אבל משום\u0004 החשש שנראה הדבר כ\u0003שיקרא\u0004 \u0005[שקר]\u0006 שנכתב השטר קודם ההלוואה השנית — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים].\u0006"],["שליח \u0003המביא גט ואבד הימנו,\u0004 אם \u0003מצאו לאלתר\u0004 (מייד) לאחר שאבד לו — \u0003כשר, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול,\u0004 שמא הגט שמצא אינו זה שאיבד אלא של אדם אחר ששמו ושם אשתו כשם הבעל והאשה שבגט שהביא. \u0003מצאו בחפיסה או בדלוסקמא\u0004 (קופסה), אם יש בו סימן — יכול לסמוך על כך שהוא שלו. \u0003אם\u0004 היה זה גט ש\u0003מכירו\u0004 — \u0003כשר\u0004 בכל מקום.","שנינו במשנתנו שגט שאבד הריהו פסול ולא ניתן לגרש בו, אלא אם כן נמצא לאלתר. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 לכך ממה ששנינו: \u0003מצא גיטי נשים,\u0004 או שטרי \u0003שחרורי עבדים, דייתיקי\u0004 (צוואות), \u0003מתנות, ושוברין\u0004 (קבלות על סכומי כסף) — \u0003הרי זה לא יחזיר\u0004 למי שהיו מיועדים עבורם, ומדוע? \u0003שאני אומר:\u0004 אמנם \u0003כתובין היו ו\u0004אולם \u0003נמלך עליהן\u0004 אחר כך \u0003שלא ליתנן.\u0004 ומכאן נסיק: \u0003הא\u0004 \u0005[הרי\u0006 אם\u0005]\u0006 \u0003אמר\u0004 הכותב: \u0003\"תנו\"\u0004 — \u0003נותנין, ואפילו\u0004 עבר מאז שאבדו ועד שנמצאו \u0003זמן מרובה!\u0004","\u0003אמר רבה: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003כאן\u0004 במשנתנו מדובר \u0003במקום ש\u0004בו \u0003השיירות מצויות,\u0004 ואז יש לחשוש שיש זוג במקום אחר בעל אותם שמות, וגט זה אינו שלו. \u0003כאן\u0004 במשנה האחרת, מדובר \u0003במקום שאין השיירות מצויות\u0004 ומשום כך יכול להחזיר (אם ידוע לנו שלא נמלך).","ומעירים: \u0003ואפילו במקום שהשיירות מצויות\u0004 שחוששים שמא אין זה הגט שלו, \u0003והוא\u0004 רק כ\u0003שהוחזקו,\u0004 שיש לנו זה מכבר חזקה וידיעה שהיו \u0003שני יוסף בן שמעון בעיר אחת,\u0004 ואז יש באמת מקום לחשוש שמא איש אחר מאותה עיר הוא, וגט אחר הוא.","\u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא תימא הכי\u0004 \u0005[תאמר כך]\u0006 שדווקא כשהוחזקו שניים בעלי שם זהה אנו חוששים, אם כן \u0003קשיא דרבה אדרבה\u0004 \u0005[קשה\u0006 מדבריו \u0005של רבה\u0006 במקום אחר \u0005על\u0006 דברי \u0005רבה\u0006 כאן\u0005].\u0006 שמסופר: \u0003דההוא גיטא דאישתכח בי דינא\u0004 \u0005[שגט אחד שנמצא בבית הדין]\u0006 של \u0003רב הונא, והוה כתיב ביה\u0004 \u0005[והיה כתוב בו]\u0006 שם המקום \u0003\"בשוירי מתא\u0004 \u0005[העיר]\u0006 ש\u0003על רכיס נהרא\u0004 \u0005[הנהר]\u0006 \u0003\", ואמר רב הונא: חוששין\u0004 אנו \u0003לשני שוירי,\u0004 שמא יש עוד מקום ששמו כך, ועל כן שמא אינו של זה שמבקש לגרש בו את אשתו.","\u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003רב חסדא לרבה\u0004 שהיה אז צעיר: \u0003פוק\u0004 \u0005[צא]\u0006 \u0003ועיין בה,\u0004 בהלכה זו, \u0003דלאורתא בעי לה מינך\u0004 \u0005[שבערב ישאל אותך על כך]\u0006 \u0003רב הונא. נפק, דק ואשכח\u0004 \u0005[יצא\u0006 רבה, \u0005דקדק ומצא],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן שנינו במשנה\u0005]:\u0006 \u0003כל\u0004 המוצא \u0003מעשה בית דין\u0004 (שטרות ומסמכים שנעשים על ידי בית הדין) — \u0003הרי זה יחזיר\u0004 את מה שמצא לבעליו, ואינו צריך לחשוש לשתי ערים בעלות שם זהה.","\u0003והא בי דינא\u0004 \u0005[והרי בית הדין]\u0006 של \u0003רב הונא\u0004 ש\u0003כמקום שהשיירות מצויות דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 שאנשים רבים עוברים ושבים שם, \u0003וקא פשיט\u0004 \u0005[ופתר]\u0006 רבה שהדין הוא ש\u0003יחזיר, אלמא\u0004 \u0005[מכאן יוצא]\u0006 שלדעתו, רק \u0003אי\u0004 \u0005[אם]\u0006 היה זה מקרה ש\u0003הוחזקו שני\u0004 אנשים בשם \u0003יוסף בן שמעון בעיר אחת\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אז חוששים, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 — \u0003לא.\u0004","ומספרים: \u0003עבד\u0004 \u0005[עשה]\u0006 \u0003רבה עובדא בההוא גיטא דאישתכח בי כיתנא\u0004 \u0005[מעשה בגט אחד שנמצא בבית הכותנה]\u0006 \u0003ב\u0004עיר \u0003פומבדיתא כשמעתיה\u0004 \u0005[כשיטתו].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 שהיה זה \u0003בדוכתא היכא דתרו כיתנא\u0004 \u0005[במקום היכן ששורים פשתן],\u0006 \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003הוחזקו\u0004 שני אנשים באותו שם באותה עיר הכתובה בגט, ומדוע? — כיון ש\u0003לא שכיחן שיירתא\u0004 \u0005[מצויות שיירות]\u0006 העוברות במקום זה. \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 שהיה הדבר \u0003בדוכתא דמזבני כיתנא\u0004 \u0005[במקום שמוכרים\u0006 בו \u0005פשתן],\u0006 \u0003והוא שלא הוחזקו\u0004 שני אנשים בעלי אותו שם בעיר הכתובה בגט, \u0003ו\u0004אולם \u0003שכיחן\u0004 \u0005[מצויות]\u0006 \u0003שיירות,\u0004 שהרי זה מקום שאנשים רבים עוברים בו.","באותו ענין אומרים: \u0003ר' זירא רמי מתניתין אברייתא ומשני\u0004 \u0005[היה משליך,\u0006 מראה סתירה, \u0005ממשנתנו על הברייתא, ומתרץ].\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003המביא גט ואבד הימנו, אם מצאו לאלתר\u0004 — \u0003כשר,\u0004 \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול.\u0004 \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מביאים סתירה לכך\u0005]\u0006 ממה ששנינו בברייתא: \u0003מצא גט אשה בשוק, בזמן שהבעל מודה\u0004 שכתבו ונתנו — \u0003יחזיר לאשה, אין הבעל מודה\u0004 — \u0003לא יחזיר לא לזה ולא לזה.\u0004 ונדייק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006"],["\u0003בזמן שהבעל מודה מיהת\u0004 \u0005[על כל פנים]\u0006 \u0003יחזיר לאשה, ואפילו\u0004 אבד הגט \u0003לזמן מרובה! ומשני\u0004 \u0005[ומתרץ]:\u0006 \u0003כאן במקום שהשיירות מצויות\u0004 — לא יחזיר, \u0003כאן במקום שאין השיירות מצויות\u0004 — יחזיר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בדברי ר' זירא שבמקום שהשיירות מצויות לא יחזיר: \u0003והוא,\u0004 דווקא \u0003שהוחזקו\u0004 שני אנשים בשמות שווים באותה עיר \u0003הוא\u0004 ש\u0003לא ליהדר\u0004 \u0005[יחזיר],\u0006 \u0003והיינו\u0004 \u0005[וזהו]\u0006 כשיטתו של \u0003רבה; ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא הוחזקו\u0004 בשמות שווים \u0003לא ליהדר\u0004 \u0005[יחזיר]\u0006 במקום ששיירות מצויות, \u0003ופליגא\u0004 \u0005[וחלוקה]\u0006 שיטתו של ר' זירא על זו של \u0003רבה.\u0004","ומבררים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003רבה לא אמר כר' זירא\u0004 ולא הקשה כמוהו מן הברייתא, אלא מן המשנה בבבא מציעא, כי \u0003מתניתין אלימא ליה לאקשויי\u0004 \u0005[משנתנו,\u0006 משנת רבי, \u0005חזקה לו יותר להקשות\u0006 ממנה\u0005],\u0006 שנוסחתה מדוייקת וברורה מאשר זו של הברייתא. \u0003אלא ר' זירא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כרבה\u0004 ומדוע לא הקשה מן המשנה?","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ר' זירא, \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 במשנה במפורש: \u0003אם אמר \"תנו\"\u0004 — \u0003נותנין ואפילו לזמן מרובה?\u0004 הרי לא למדנו זאת אלא מדיוק, ואם כן \u0003דלמא\u0004 \u0005[שמא]\u0006 אתה צריך לדייק באופן אחר: \u0003אם אמר \"תנו\"\u0004 — \u0003נותנין,\u0004 אבל רק \u0003כדקיימא לן\u0004 \u0005[כפי שמוחזק לנו\u0006 במשנתנו\u0005]\u0006 — \u0003לאלתר\u0004 \u0005[מייד],\u0006 ולא לאחר זמן.","\u0003ר' ירמיה אמר:\u0004 אפשר לתרץ את הקשיים הללו באופן אחר, ולהעמיד את המשנה בבבא מציעא ואת הברייתא, המתירות להחזיר גט שנפל \u0003כגון דקאמרי\u0004 \u0005[שאומרים]\u0006 ה\u0003עדים\u0004 שחתומים על שטר זה: \u0003מעולם לא חתמנו אלא על גט אחד של יוסף בן שמעון,\u0004 וממילא אין לחשוש שמא של אחר הוא.","ושואלים: \u0003אי הכי, מאי למימרא\u0004 \u0005[אם כך, מה\u0006 צורך \u0005לומר\u0006 זאת\u0005],\u0006 הרי פשוט שיחזיר, שהרי ברור שהוא של זה! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003ליחוש דלמא איתרמי\u0004 \u0005[נחשוש שמא הזדמן]\u0006 גט אחר שבו \u0003שמא\u0004 \u0005[שם]\u0006 של המגרש והמגורשת \u0003כשמא\u0004 \u0005[כשם]\u0006 של המגרש והמגורשת, \u0003ו\u0004שמות \u0003עדים כ\u0004שמות \u0003עדים\u0004 של גט זה, ובעצם עדים אחרים הם, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלכך אין חוששים.","\u0003רב אשי אמר:\u0004 מתי יחזיר — \u0003כגון דקאמר\u0004 \u0005[שאומר]\u0006 המאבד: \u0003נקב יש בו בצד אות פלונית, דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003סימן מובהק,\u0004 ועל סימן כזה ודאי יש לסמוך. ומעירים: \u0003ודוקא\u0004 כשאמר שהנקב \u0003בצד אות פלונית, דהוה ליה\u0004 \u0005[שהריהו]\u0006 \u0003סימן מובהק\u0004 מתיר רב אשי להחזיר את הגט, \u0003אבל\u0004 אם אמר: \u0003נקב בעלמא\u0004 \u0005[סתם]\u0006 היה שם, ולא אמר היכן בדיוק היה — \u0003לא\u0004 יחזירו את הגט, לפי שאין זה סימן מובהק.","ומסבירים: \u0003מספקא ליה\u0004 \u0005[מסופק\u0006 היה \u0005לו]\u0006 בענין ההסתמכות על \u0003סימנין אי דאורייתא אי דרבנן\u0004 \u0005[אם\u0006 הם \u0005מן התורה אם\u0006 הם \u0005מדברי סופרים]\u0006 להחזיר אבידה על פיהם. ומשום כך לא רצה לסמוך על סימנים סתם, אלא רק על סימן מובהק שלכל הדעות אפילו מן התורה הוא מועיל.","מסופר: \u0003רבה בר בר חנה אירכס ליה גיטא בי מדרשא\u0004 \u0005[אבד לו גט\u0006 שהביא, \u0005בבית המדרש],\u0006 \u0003אמר: אי סימנא\u0004 \u0005[אם סימן]\u0006 יבקשו ממני — \u0003אית לי בגויה\u0004 \u0005[יש לי בו],\u0006 \u0003אי טביעות עינא\u0004 \u0005[אם\u0006 משום \u0005טביעת עין]\u0006 שאני מכיר אותו — \u0003אית לי בגויה\u0004 \u0005[יש לי בו].\u0006 \u0003אהדרוה ניהליה\u0004 \u0005[החזירוהו\u0006 את הגט \u0005לו].\u0006 \u0003אמר\u0004 בסוף: \u0003לא ידענא\u0004 \u0005[אין אני יודע]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום סימנא אהדרוה\u0004 \u0005[הסימן החזירו\u0006 לי\u0005],\u0006 \u0003וקסברי\u0004 \u0005[וסבורים\u0006 הם\u0005]\u0006 ש\u0003סימנים\u0004 הם \u0003דאורייתא\u0004 \u0005[מן התורה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום טביעות עינא\u0004 \u0005[טביעת עין],\u0006 \u0003ו\u0004מצד זה \u0003דוקא צורבא מדרבנן\u0004 \u0005[תלמיד חכם]\u0006 סומכים על מה שאומר שהוא מכירו בטביעת עין, \u0003אבל אינש בעלמא\u0004 \u0005[אדם סתם]\u0006 \u0003לא\u0004 יחזירו לו על סמך זה.","שנינו במשנה שאם מצאו לאלתר — כשר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003פסול. תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003איזהו,\u0004 מה נחשב \u0003שלא לאלתר?\u0004 — \u0003ר' נתן אומר: ששהה\u0004 זמן \u0003כדי שתעבור שיירא\u0004 באותו מקום \u0003ותשרה\u0004 (תחנה) בו. \u0003ר' שמעון בן אלעזר אומר: כדי שיהא אדם עומד ורואה שלא עבר שם אדם\u0004 אחר. \u0003ויש אומרים: שלא שהה אדם שם. רבי אומר:\u0004 זמן מספיק \u0003כדי לכתוב את הגט. ר' יצחק אומר:\u0004 זמן \u0003כדי לקרותו. אחרים אומרים: כדי לכותבו ולקרותו.\u0004","ומוסיפים: \u0003ואפילו שהה\u0004 זמן רב \u0003ויש בו סימנין,\u0004 בגט — \u0003מעידים עליו\u0004 וכשר הגט, ובאלו סימנים מדובר — כגון \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 \u0003נקב יש בו בצד אות פלונית. ואין מעידין על סימני הגוף\u0004 של הגט — סימנים כלליים, כגון \u0003דאמרי\u0004 \u0005[שאומרים]:\u0006 הגט הוא \u0003ארוך, ו\u0004כן \u0003גוץ\u0004 \u0005[קצר],\u0006 משום שאין אלה נחשבים כסימנים מובהקים.","\u0003מצאו\u0004 את הגט \u0003קשור בכיס,\u0004 או \u0003בארנקי,\u0004 או \u0003בטבעת\u0004 המוכרים לו,"],["\u0003או שמצאו בין כליו\u0004 בביתו, \u0003אפילו\u0004 היה זה \u0003לזמן מרובה\u0004 — \u0003כשר.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים ביחס לפסק הלכה במחלוקת מהו \"לאלתר\" שבמשנה: \u0003רב יהודה אמר\u0004 בשם \u0003שמואל, הלכה: שלא שהה אדם שם. רבה בר בר חנה אמר\u0004 בשם \u0003רב יצחק בר שמואל, הלכה: שלא עבר אדם שם.\u0004","ושואלים: \u0003לימא מר\u0004 \u0005[שיאמר חכם זה,\u0006 רב יהודה בשם שמואל\u0005]\u0006 \u0003הלכה כמר\u0004 \u0005[כחכם זה],\u0006 כדעת יש אומרים, \u0003ומר\u0004 \u0005[וחכם זה,\u0006 רבה בר בר חנה בשם רב יצחק בר שמואל\u0005]\u0006 שיאמר \u0003הלכה כמר\u0004 \u0005[כחכם זה,\u0006 כר' שמעון בן אלעזר\u0005]!\u0006 ומפני מה הוצרכו לפרש את השיטות? ומשיבים: \u0003משום דאפכי להו\u0004 \u0005[שהיו הופכים אותם]\u0006 את שמות האומרים, ר' שמעון בן אלעזר ויש אומרים. ומשום כך רצו לברר את דבריהם שלא תהא בהם טעות להלכה.","שנינו במשנה: \u0003מצאו בחפיסה או בדלוסקמא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חפיסה\"? אמר רבה בר בר חנה: חמת\u0004 (נאד) \u0003קטנה. מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"דלוסקמא\"?\u0004 — \u0003טליקא דסבי\u0004 \u0005[ארנק של\u0006 אנשים \u0005זקנים].\u0006","שליח \u0003המביא גט\u0004 לאשה, \u0003והניחו\u0004 את המגרש כשהוא איש \u0003זקן או חולה\u0004 — \u0003נותן לה\u0004 השליח את הגט \u0003בחזקת שהוא קיים\u0004 (חי) עדיין, ואין חוששים שמא מת הבעל בינתיים ובטל הגט.","וכיוצא בזה, \u0003בת ישראל הנשואה לכהן\u0004 ורשאית לאכול תרומה מכוח נישואיה אלה, \u0003והלך בעלה למדינת הים\u0004 — ממשיכה להיות \u0003אוכלת בתרומה בחזקת שהוא קיים.\u0004 וכן \u0003השולח\u0004 קרבן \u0003חטאתו ממדינת הים\u0004 — \u0003מקריבין אותה בחזקת שהוא קיים\u0004 ואין חוששים שמא מת בינתיים ונפסלה החטאת.","\u0003אמר רבא: לא שנו\u0004 במשנה שאומרים שחזקת אדם שנשאר בחיים \u0003אלא\u0004 ב\u0003זקן שלא הגיע לגבורות\u0004 (לשנת השמונים לחייו), \u0003וחולה\u0004 סתם, מאחר \u0003שרוב\u0004 \u0003חולים לחיים\u0004 קמים מחוליים, \u0003אבל\u0004 אם היה זה \u0003זקן שהגיע לגבורות,\u0004 או \u0003גוסס, ש\u0004הרי ידוע כי \u0003רוב גוססין למיתה\u0004 — \u0003לא\u0004 סומכים על חזקה זו.","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו בברייתא: \u0003המביא גט והניחו\u0004 את המגרש כשהוא \u0003זקן, אפילו בן מאה שנה\u0004 — \u0003נותן לה בחזקת שהוא קיים!\u0004 ומסכמים: \u0003תיובתא\u0004 \u0005[קושיה חמורה\u0006 היא\u0005]\u0006 ונדחו דבריו של רבא.","ומעירים: \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שאין זו קושיה, ודווקא במי שהוא בן מאה שנה נאמרה ברייתא זו, \u0003כיון דאיפליג\u0004 \u0005[שהפליג]\u0006 בשנים יותר משנות כל אדם — \u0003איפליג\u0004 \u0005[הפליג],\u0006 ואין חוששים שמא מת עכשיו, אבל סתם זקן לאחר גיל הגבורות לחייו יש לחשוש שמא מת.","\u0003רמי ליה\u0004 \u0005[השליך לו,\u0006 הראה לו סתירה\u0005]\u0006 \u0003אביי לרבה, תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המביא גט, והניחו זקן או חולה\u0004 — \u0003נותן לה\u0004 את הגט \u0003בחזקת שהוא קיים\u0004 ואין אנו חוששים שמא מת. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: האומר לאשתו \u0003\"הרי זה גיטך שעה אחת קודם למיתתו\u0004 (מיתתי) \u0003\",\u0004 שהגט יחול שעה אחת לפני שימות, אם היתה זו אשת כהן — \u0003אסורה לאכול בתרומה מיד,\u0004 שאנו חוששים שמא בעוד שעה ימות!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: מדין \u0003תרומה\u0004 על דין \u0003גיטין קא רמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005]?\u0006 הלא \u0003תרומה אפשר\u0004 לה לאשה שלא תאכל, אלא תסתפק בחולין, ולכן אפשר להחמיר בה מפני החשש, אבל \u0003גט לא אפשר,\u0004 שאין לכך תקנה, ולכן סומכים על החזקה.","\u0003ורמי\u0004 \u0005[והשלך,\u0006 הראה סתירה\u0005]\u0006 מדין \u0003תרומה אתרומה\u0004 \u0005[על דין תרומה],\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003בת ישראל הנשואה לכהן, והלך בעלה למדינת הים\u0004 — \u0003אוכלת בתרומה בחזקת שהוא קיים.\u0004","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003\"הרי זה גיטך שעה אחת קודם מיתתו\"\u0004 — \u0003אסורה לאכול בתרומה מיד.\u0004 והרי זו סתירה מאותו דין עצמו!","\u0003אמר רב אדא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יצחק: שאני התם\u0004 \u0005[שונה שם],\u0006 \u0003שהרי אסרה עליו שעה אחת קודם מיתתו,\u0004 ואם כן, בוודאי חל עליה איסור עוד בחייו, אלא שאין אנו יודעים בדיוק מתי הוא מתחיל, ולכן חוששים לכך מיד. \u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב פפא: ממאי דאיהו מיית ברישא\u0004 \u0005[ממה,\u0006 מניין אתה יודע \u0005שהוא ימות בתחילה]\u0006 ואז יחול האיסור? \u0003דלמא איהי מייתא ברישא\u0004 \u0005[שמא היא תמות בתחילה],\u0006 ואם כן, לא היה כאן איסור כלל!","\u0003אלא אמר אביי, לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]:\u0006 \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה לאשה לאכול תרומה — שיטת \u0003ר' מאיר\u0004 ש\u0003לא חייש\u0004 \u0005[חושש]\u0006 \u0003למיתה, הא\u0004 \u0005[זו]\u0006 האוסרת על האשה לאכול תרומה — שיטת \u0003ר' יהודה דחייש\u0004 \u0005[שחושש]\u0006 \u0003למיתה.\u0004","\u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הלוקח\u0004 (קונה) \u0003יין\u0004 בלתי מעושר \u0003מבין הכותים\u0004 (שומרונים) ורוצה לשתות ממנו, \u0003אומר: שני לוגין שאני עתיד להפריש\u0004 בעוד זמן — \u0003הרי הן\u0004 (ייעשו) \u0003תרומה, עשרה\u0004 לוגין יהיו \u0003מעשר ראשון, תשעה\u0004 — \u0003מעשר שני, ומיחל\u0004 (ומחלל) את המעשר השני בכסף \u0003ושותה מיד,\u0004 אלו \u0003דברי ר' מאיר.\u0004","\u0003ר' יהודה ור' אסי ור' שמעון אוסרים.\u0004 ובהמשך הדברים מסבירים חכמים את דבריהם שהם חוששים שמא ייבקע הנאד, ור' מאיר אינו חושש לכך. וכיוצא בזה נאמר שר' מאיר אינו חושש לאסון כגון מיתה, ור' יהודה חושש לכך.","\u0003רבא אמר:\u0004"],["יש לחלק בצורה אחרת: \u0003שמא מת\u0004 כבר \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 אבל במתנה \"שעה אחת קודם מיתתו\" ובמקרה זה שהחשש הוא \u0003שמא ימות\u0004 בעתיד \u0003חיישינן\u0004 \u0005[חוששים אנו]\u0006 כבר מעכשיו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אדא בר מתנה לרבא: והא\u0004 \u0005[והרי]\u0006 החשש שמא ייבקע ה\u0003נוד\u0004 שכמו \u0003שמא ימות הוא,\u0004 שהרי זה חשש לעתיד, \u0003ופליגי\u0004 \u0005[וחלוקים]\u0006 חכמים בדבר, ור' מאיר אינו חושש! \u0003אמר רב יהודה מדסקרתא:\u0004 אפשר לתרץ, \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003נוד\u0004 ש\u0003אפשר דמסר ליה\u0004 \u0005[שמוסר אותו]\u0006 \u0003לשומר\u0004 והוא ישמרנו שלא יתבקע, ומשום כך ר' מאיר אינו חושש לדבר. מה שאי אפשר לעשות כן לענין מיתה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב משרשיא: ערביך\u0004 \u0005[הערב שלך]\u0006 הוא עצמו \u0003ערבא\u0004 \u0005[ערב]\u0006 \u0003צריך,\u0004 שהרי מי יאמר לנו שהשומר לא יפשע בדבר, וייבקע הנאד! \u0003אלא אמר רבא,\u0004 כך צריך לומר: \u0003שמא מת\u0004 — \u0003לא חיישינן\u0004 \u0005[אין אנו חוששים]\u0006 לכל הדעות, וכמשנתנו, \u0003שמא ימות\u0004 — \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא.\u0004","שנינו במשנה: \u0003השולח חטאתו ממדינת הים\u0004 — מקריבים אותה בחזקת שהוא קיים. ושואלים מצד אחר: \u0003והא בעינא\u0004 \u0005[והרי צריכים]\u0006 שתהיה \u0003סמיכה\u0004 של המקריב על הקרבן, ובעל הקרבן נמצא הלא במקום אחר ואינו יכול לסמוך! \u0003אמר רב יוסף:\u0004 מדובר כאן \u0003בקרבן נשים,\u0004 שאינן צריכות לסמוך על קרבנן. \u0003רב פפא אמר:\u0004 מדובר \u0003בחטאת העוף\u0004 שאינה צריכה סמיכה.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 שייאמרו במשנתנו שלושת המקרים הללו שאין חוששים בהם שאדם מת, ומדוע? \u0003דאי אשמועינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק ב\u0003גט,\u0004 היינו אומרים: \u0003משום\u0004 ש\u0003לא אפשר\u0004 בדרך אחרת, ונמצא שאין אדם יכול לגרש את אשתו שבמקום רחוק, \u0003אבל תרומה\u0004 ש\u0003אפשר\u0004 שתאכל חולין — \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003לא,\u0004 ונחשוש שמא מת.","\u0003ואי אשמועינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 גם \u0003תרומה,\u0004 יכולים היינו להבין שאין חוששים לדבר משום \u0003דזמנין\u0004 \u0005[שפעמים]\u0006 ש\u0003לא אפשר\u0004 משום שאולי אין לה מספיק חולין, \u0003אבל חטאת העוף\u0004 — יש מקום לומר ש\u0003מספיקא\u0004 \u0005[מן הספק]\u0006 \u0003לא ליעול\u0004 \u0005[נכניס]\u0006 \u0003חולין לעזרה,\u0004 שמא חטאת זו אינה מקודשת, שהרי בעליה אולי אינו בחיים, על כן, \u0003צריכא\u0004 \u0005[צריך]\u0006 שייאמרו כל המקרים הללו.","\u0003שלשה דברים אמר ר' אלעזר בן פרטא לפני חכמים\u0004 בתורת עדות מפי הראשונים, \u0003וקיימו את דבריו: על\u0004 אנשי \u0003עיר שהקיפה כרקום\u0004 (מצור), \u0003ועל\u0004 אנשי \u0003הספינה\u0004 \u0003המוטרפת\u0004 (מטולטלת בסערה) \u0003בים, ועל היוצא לידון\u0004 אפילו בדיני נפשות — \u0003שהן בחזקת קיימין\u0004 ואין חוששים שמא מתו.","\u0003אבל\u0004 בני \u0003עיר שכבשה כרקום\u0004 הצר על העיר, \u0003ו\u0004אנשי \u0003ספינה שאבדה בים, והיוצא ליהרג\u0004 לאחר שנגמר דינו — \u0003נותנין עליהן חומרי חיים וחומרי מתים,\u0004 שכיון שאין אנו יודעים מה קרה להם — מחמירים בהם גם כאילו היו חיים וגם כאילו היו מתים. כיצד? אם היתה \u0003בת ישראל\u0004 נשואה \u0003לכהן\u0004 ובעלה היה באחד מהמצבים הללו — לא תאכל עוד בתרומה, שמא מת הוא ואבדה זכותה לאכול בתרומה, \u0003ו\u0004אם היתה \u0003בת כהן\u0004 נשואה \u0003לישראל\u0004 ואיבדה על ידי נישואיה את הזכות לאכול תרומה — גם היא \u0003לא תאכל בתרומה,\u0004 שמא בעלה חי ועדיין אסורה בתרומה.","\u0003אמר רב יוסף: לא שנו\u0004 שהיוצא ליהרג נותנים עליו גם חומרי חיים \u0003אלא בבית דין של ישראל,\u0004 שאף לאחר שמוציאים אותו ליהרג, אם מצאו לו זכות פוטרים אותו. \u0003אבל בבית דין של עובדי כוכבים, כיון דגמיר ליה דינא לקטלא\u0004 \u0005[שנגמר לו דינו למוות]\u0006 — \u0003מיקטל קטלי ליה\u0004 \u0005[הורגים\u0006 הם \u0005אותו]\u0006 בכל מקרה, ולכן אנו צריכים לדון אותו כמת לכל דבר.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בית דין של עובדי כוכבים נמי\u0004 \u0005[גם כן]\u0006 יש לומר שאולי לא ימיתוהו, שהרי הם \u0003מקבלי שוחדא\u0004 \u0005[מקבלים שוחד]\u0006 ושמא יינצל בסופו של דבר על ידי מתן שוחד! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003כי שקלי\u0004 — \u0005[כאשר\u0006 הם \u0005לוקחים\u0006 שוחד\u0005]\u0006 — הרי זה רק \u0003מקמי דלחתום פורסי שנמג\u0004 \u0005[לפני שייחתם גזר הדין],\u0006 אבל \u0003לבתר דמיחתם פורסי שנמג\u0004 \u0005[אחרי שנחתם גזר הדין]\u0006 \u0003לא שקלי\u0004 \u0005[אינם לוקחים],\u0006 ובמשנתנו מדובר לאחר שנחתם כבר גזר הדין.","לפי זה אף לאחר שנגמר דינו של אדם ליהרג בבית דין של ישראל, הריהו בחזקת חי, ועל כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו: \u0003כל מקום שיעמדו שנים ויאמרו: מעידין אנו את איש פלוני שנגמר דינו בבית דינו של פלוני, ופלוני ופלוני\u0004 היו \u0003עדיו\u0004 — \u0003הרי זה יהרג,\u0004 ואין אנו חוששים שמא מצאו לו אחרי כן טעם כדי לפוטרו! ומשיבים: \u0003דלמא\u0004 \u0005[שמא]\u0006 ב\u0003בורח שאני\u0004 \u0005[שונה],\u0006 שבוודאי לא חזרו ודנו בו, ונשאר הדין כפי שהיה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו: \u0003שמע מבית דין של ישראל שהיו אומרים \"איש פלוני מת\",\u0004 או \u0003\"איש פלוני נהרג\"\u0004 — \u0003ישיאו את אשתו.\u0004 אם שמע \u0003מקומנטריסין\u0004 (סופר בית המשפט) \u0003של גוים \"איש פלוני מת\", \"איש פלוני נהרג\"\u0004 — \u0003אל ישיאו את אשתו.\u0004","ומבררים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מת\"\u0004 שאומרים כאן, \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"נהרג\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003\"מת\"\u0004 כוונתו ש\u0003מת ממש, ו\"נהרג\"\u0004 — \u0003נהרג ממש, דכוותיה\u0004 \u0005[שכיוצא בו]\u0006 \u0003גבי גוים אמאי\u0004 \u0005[מדוע]\u0006 \u0003אל ישיאו את אשתו? הא קיימא לן\u0004 \u0005[הרי מוחזק בידינו]\u0006 ש\u0003כל\u0004 גוי ש\u0003מסיח לפי תומו הימוני מהימני ליה\u0004 \u0005[מאמינים אנו לו]\u0006 ואם כן, צריך לסמוך גם על הגויים שאמרו שאיש פלוני נהרג!","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 צריכים לפרש כך: כשאומרים \u0003\"מת\"\u0004 — הכוונה היא \u0003יוצא למות,\u0004 וכשאומרים \u0003\"נהרג\"\u0004 — הכוונה היא \u0003יוצא ליהרג, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003בבית דין\u0004 של \u0003ישראל ישיאו את אשתו,\u0004 שאנו מניחים שוודאי כבר נהרג, ולהיפך ממה שאמרנו!","ודוחים: \u0003לעולם\u0004 תפרש \u0003מת ממש, ונהרג ממש, ודקאמרת\u0004 \u0005[ומה שאמרת]:\u0006 \u0003דכוותיה\u0004 \u0005[שכיוצא בו]\u0006 \u0003גבי גוים אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא\u0004 סומכים עליהם? \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003כל מסיח לפי תומו הימוני מהימני\u0004 \u0005[נאמנים הם]!\u0006 יש להבדיל; \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003במילתא\u0004 \u0005[בדבר]\u0006 ש\u0003לא שייכי\u0004 \u0005[שייכים]\u0006 \u0003בה\u0004 אלא הוא מספר על מעשה שאירע לאחרים, \u0003אבל במילתא דשייכי בה\u0004 \u0005[בדבר ש\u0006הם \u0005שייכים בו]\u0006 \u0003עבדי לאחזוקי שיקרייהו\u0004 \u0005[עשויים\u0006 הם \u0005לחזק את שיקרם]\u0006 וכיון שפסקו פסק דין, הרי הם מספרים שהאיש נהרג, ואין לסמוך בוודאות על דבריהם.","עד כאן גירסה אחת של סוגיה זו, אבל קיימת גם גירסה אחרת: \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003אמר רב יוסף: לא שנו\u0004 שיוצא ליהרג נותנים עליו חומרי חיים ומתים \u0003אלא בבית דין של עובדי כוכבים,\u0004"],["\u0003אבל בבית דין של ישראל, כיון דנפק ליה דינא לקטלא\u0004 \u0005[שיצא לו דינו למיתה]\u0006 — \u0003קטלי ליה\u0004 \u0005[ממיתים אותו].\u0006","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: בית דין של ישראל נמי\u0004 \u0005[גם כן]\u0006 \u0003אפשר דחזו ליה זכותא\u0004 \u0005[שיראו לו זכות\u0006 אחרי כן\u0005]\u0006 ויפטרוהו! אמר לו רב יוסף: \u0003כי חזו ליה זכותא\u0004 \u0005[כאשר רואים לו זכות]\u0006 — הרי זה \u0003מקמי דליגמר דינא\u0004 \u0005[לפני שנגמר הדין],\u0006 ואולם \u0003בתר גמר דינא\u0004 \u0005[אחרי גמר הדין]\u0006 — \u0003תו לא חזו ליה זכותא\u0004 \u0005[שוב אין רואים לו זכות],\u0006 שאין זה מצוי שיראו לו זכות לאחר שנגמר דינו.","ומציעים: \u0003לימא מסייעא ליה\u0004 \u0005[האם\u0006 אפשר \u0005לומר\u0006 שאפשר \u0005לסייע לו],\u0006 לרב יוסף, ממה ששנינו: \u0003כל מקום שיעמדו שנים ויאמרו \"מעידים אנו את איש פלוני שנגמר דינו בבית דינו של פלוני, ופלוני ופלוני\u0004 היו \u0003עדיו\"\u0004 — \u0003הרי זה יהרג\u0004 ואין אנו חוששים שמא ראו לו זכות אחרי כן ופטרוהו! ודוחים: משם אין ראיה, \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003בורח שאני\u0004 \u0005[שונה],\u0006 שוודאי לא היה מקום ללמד עליו זכות.","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ראיה נוספת ממה ששנינו: \u0003שמע מבית דין של ישראל שהיו אומרים \"איש פלוני מת\",\u0004 או \u0003\"איש פלוני נהרג\"\u0004 — \u0003ישיאו,\u0004 כלומר, מתירים בית דין \u0003את\u0004 נישואי \u0003אשתו\u0004 לאחר. שמע \u0003מקומנטריסים\u0004 (סופרי בית משפט) \u0003של גוים \"איש פלוני מת\",\u0004 או \u0003\"איש פלוני נהרג\"\u0004 — \u0003אל ישיאו את אשתו.\u0004","ונברר: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מת\" ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"נהרג\"? אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003\"מת\"\u0004 כוונתו מת \u0003ממש, ו\"נהרג\"\u0004 כוונתו נהרג \u0003ממש,\u0004 אם כן \u0003דכוותיה\u0004 \u0005[שכיוצא בו]\u0006 \u0003גבי גוים אמאי\u0004 \u0005[מדוע]\u0006 \u0003אל ישיאו את אשתו? הא קיימא לן\u0004 \u0005[הרי מוחזק בידינו],\u0006 הכלל ש\u0003כל\u0004 גוי ה\u0003מסיח לפי תומו הימוני מהימני ליה\u0004 \u0005[מאמינים\u0006 אנו \u0005לו],\u0006","\u0003אלא לאו\u0004 \u0005[האם לא]\u0006 הכוונה \u0003\"מת\"\u0004 — שהוא \u0003יוצא למות,\u0004 \u0003ו\"נהרג\"\u0004 כוונתו — \u0003יוצא ליהרג, וקתני\u0004 \u0005[ושנה]:\u0006 \u0003בבית דין של ישראל ישיאו את אשתו.\u0004 משמע שבבית דין של ישראל אכן אין חוזרים בהם במקרה שכזה.","ודוחים: \u0003לעולם\u0004 תפרש \u0003\"מת\"\u0004 כוונתו \u0003ממש, ו\"נהרג\"\u0004 — \u0003ממש,\u0004 ומה ששאלת \u0003דכוותיה\u0004 \u0005[שכיוצא בו]\u0006 \u0003גבי גוים אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא? והא קיימא לן\u0004 \u0005[והרי מוחזק בידינו]\u0006 ש\u0003כל\u0004 גוי \u0003מסיח לפי תומו הימוני מהימני\u0004 \u0005[מאמינים\u0006 לו\u0005]!\u0006 — \u0003הני מילי במילתא דלא שייכי בה\u0004 \u0005[דברים אלה\u0006 אמורים דווקא \u0005בדבר ש\u0006הם \u0005אינם שייכים בו]\u0006 אלא מספרים מעשה בלבד, \u0003אבל במילתא דשייכי בה, עבדי לאחזוקי שקרייהו\u0004 \u0005[בדבר ש\u0006הם \u0005שייכים בו, עשויים\u0006 הם \u0005לחזק את שיקרם]\u0006 ולומר שאכן נהרג אף על פי שלא כך היה.","\u0003המביא גט בארץ ישראל,\u0004 שאין השליח צריך להעיד עליו, אלא רק מוסר את הגט (וראה במשנה הבאה להלן עמוד ב), \u0003וחלה\u0004 השליח — \u0003הרי זה משלחו ביד אחר, ואם אמר לו\u0004 הבעל: תוך כדי כך שאתה נותן לה את הגט \u0003טול לי הימנה חפץ פלוני\u0004 שיש לי פיקדון בידה — במקרה זה \u0003לא ישלחנו ביד אחר,\u0004 שאנו אומרים \u0003שאין רצונו\u0004 של אדם \u0003שיהא פקדונו ביד אחר\u0004 שלא שלחו הוא עצמו.","\u0003אמר רב כהנא: \"חלה\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005].\u0006 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאיליו\u0005]\u0006 הלא \u0003\"חלה\" קתני\u0004 \u0005[שנה]\u0006 ומה הוסיף רב כהנא בדבריו! ומשיבים \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הוא הדין אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא חלה\u0004 יכול למסור שליחותו לאחר, \u0003והאי דקתני\u0004 \u0005[וזה ששנה\u0006 במשנתנו\u0005]\u0006 \u0003\"חלה\"\u0004 — \u0003אורחא דמילתא קתני\u0004 \u0005[דרכו של דבר שנה],\u0006 שבדרך כלל שליח מקיים את שליחותו ורק מפני מחלה אינו יכול לעשות זאת, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שדווקא כאשר חלה מותר לו לעשות כן.","ומבררים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 רק \u0003\"הולך\u0004 גט זה לאשתי \u0003\", אף על גב\u0004 \u0005[אף על פי]\u0006 ש\u0003לא חלה נמי\u0004 \u0005[גם כן]\u0006 יכול למנות שליח אחר במקומו, שהרי לא הקפיד שדווקא הוא יהא המוסר. \u0003ואי\u0004 \u0005[ואם]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003\"את\u0004 \u0005[אתה]\u0006 \u0003הולך\u0004 את הגט \u0003\"\u0004— \u0003אפילו חלה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא,\u0004 שהרי הדגיש הבעל שרוצה שדווקא שליח זה יוליך את הגט. \u0003ואי\u0004 \u0005[ואם]\u0006 כשיטת \u0003רבן שמעון בן גמליאל, אפילו חלה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא\u0004 ימסרנו לאחר בכל מקרה!","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 האומר לשליח: \u0003\"הולך גט זה לאשתי\"\u0004 — \u0003הרי זה\u0004 השליח \u0003משלחו ביד\u0004 שליח \u0003אחר\u0004 אם ירצה, אבל אם אמר לו המשלח: \u0003\"את\u0004 \u0005[אתה]\u0006 \u0003הולך גט זה לאשתי\"\u0004 — \u0003הרי זה לא ישלחנו ביד אחר. רבן שמעון בן גמליאל אומר: בין כך ובין כך\u0004 — \u0003אין השליח עושה שליח.\u0004 ולפי זה קשים דברי רב כהנא!","ומתרצים: \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 שבאמת במשנתנו מדובר שאמר לו המשלח לשליח \u0003\"הולך\",\u0004 ורצה לומר שאף בברייתא יש להבין: \u0003והוא\u0004 ש\u0003חלה\u0004 השליח. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שמשנתנו עוסקת במקרה שאמר לו \u0003\"את הולך\", ו\u0004אולם \u0003חלה שאני\u0004 \u0005[שונה],\u0006 שאנו מניחים שאף המשלח לא היה מקפיד בכך. \u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 משנתנו אפילו שיטת \u0003רבן שמעון בן גמליאל היא,\u0004 שבדרך כלל אין שליח עושה שליח — \u0003ו\u0004אולם \u0003חלה שאני\u0004 \u0005[שונה],\u0006 שבמקרה זה גם הוא מודה ששליח עושה שליח, בין ב\"הולך\" ובין ב\"את הולך\".","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003המביא גט בארץ ישראל וחלה\u0004 — \u0003הרי זה משלחו ביד אחר, ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה ] ממה ששנינו להלן, \u0003אמר לשנים: \"תנו גט לאשתי\",\u0004 \u0003או\u0004 אמר \u0003לשלשה:\u0004 \u0003\"כתבו גט ותנו לאשתי\"\u0004 — \u0003הרי אלו יכתבו ויתנו.\u0004 ונדייק מכאן: \u0003אינהו אין\u0004 \u0005[הם\u0006 עצמם \u0005כן],\u0006 \u0003אבל שליח לא\u0004 יעשה זאת במקומם!","\u0003אמר אביי: התם טעמא מאי\u0004 \u0005[שם מהו הטעם]\u0006 — \u0003משום בזיון\u0004 של ה\u0003בעל\u0004 שאינו רוצה שיתפרסם הדבר, ולכן אין הם רשאים לעשות שליח אחר. אבל \u0003הכא\u0004 \u0005[כאן]\u0006 לאחר שכבר שלח את הגט \u0003בעל לא קפיד\u0004 \u0005[מקפיד]\u0006 עוד, ולכן שליח יכול לעשות שליח אחר במקומו.","\u0003רבא אמר:\u0004 שם יש טעם אחר לכך שלא יאמרו לשליח אחר לכתוב — \u0003משום דמילי נינהו\u0004 \u0005[שדברים הם],\u0006 כלומר, הבעל לא נתן בידם דבר מוחשי, אלא ציווי, מילים בלבד, \u0003ומילי לא מימסרן\u0004 \u0005[ודברים אינם נמסרים]\u0006 \u0003לשליח,\u0004 ולכן אינם יכולים להעביר את שליחותם לידי אחר, ואילו כאן השליח הראשון מעביר את הגט עצמו לשליח האחר.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 למעשה בין הסברי אביי ורבא אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005]\u0006 לגבי \u0003שליח מתנה,\u0004 ששלחו לכתוב שטר מתנה לאחר, \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003רב ושמואל\u0004 שנחלקו בדבר, \u0003רב אמר: מתנה אינה כגט\u0004 לענין זה ואין נותן המתנה מקפיד בדבר מיהו השליח, כי אין בכך בזיון לנותן שאדם אחר כותב את השטר ולא השליח שמינהו הנותן, \u0003ושמואל אמר: מתנה הרי היא כגט,\u0004 וטעמו: שדברים (הוראה לכתוב שטר) אינם יכולים להימסר לשליח.","שנינו במשנה: \u0003ואם אמר לו\u0004 הבעל לשליח הגט \u0003\"טול לי הימנה חפץ פלוני\"\u0004 — לא ישלחנו ביד אחר, שכן אין רצונו שיהיה פקדונו ביד אחר. \u0003אמר ריש לקיש: כאן\u0004 במשנה זו, כאשר נימק את דין המשנה באופן זה, \u0003שנה רבי\u0004 והשמיע לנו ש\u0003אין השואל רשאי להשאיל\u0004 לאחרים את מה שקיבל בהשאלה, \u0003ואין השוכר רשאי להשכיר\u0004 לאחרים. שהרי קיים שם אותו נימוק: שאין רצונו של הבעלים שיהיה פקדונו ביד אחר.","\u0003אמר לו ר' יוחנן:\u0004 הלכה \u0003זו אפילו תינוקות של בית רבן יודעים אותה,\u0004 וזה אינו עיקר החידוש במשנה, \u0003אלא זימנין דגיטא נמי לא הוי\u0004 \u0005[פעמים שגט גם כן אינו].\u0006 שלא זו בלבד שאין עושים כן לכתחילה שלא לעבור על דעת הבעל באשר לחפץ שביד האשה, אלא שליחות הגט עצמה בטלה אז לגמרי, ומדוע? — ש\u0003נעשה\u0004 דבר זה \u0003כמי שאמר לו\u0004 הבעל לשליח \u0003\"אל תגרשה אלא בבית\" ו\u0004הוא \u0003גירשה,\u0004 נתן לה את הגט, \u0003בעלייה,\u0004 או שאמר לו: \u0003\"אל תגרשה אלא בימין\" וגירשה בשמאל.\u0004 ואף כאן אפשר לומר שאם לא ביצע את כל הוראות שליחותו, הרי זה פגם אף בעצם שליחות הגט.","ומפרטים: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל],\u0006 \u0003היכא דנפקה לאפיה ויהבה ליה\u0004 \u0005[במקום שיצאה\u0006 האישה \u0005לפניו,\u0006 לקראתו, \u0005ונתנה לו]\u0006 אותו \u0003חפץ\u0004 שביקשו הבעל להביא \u0003והדר שקלה מיניה גיטא\u0004 \u0005[וחזרה ולקחה ממנו\u0006 את \u0005הגט]\u0006 — \u0003כולי עלמא לא פליגי דגיטא גיטא מעליא הוי\u0004 \u0005[הכל אינם חולקים שהגט גט מעולה הוא].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 הרי זה \u0003היכא\u0004 \u0005[במקום,\u0006 במקרה\u0005]\u0006 ש\u0003אמר ליה\u0004 \u0005[לו]\u0006 הבעל לשליח:"],["\u0003שקול מינה\u0004 \u0005[קח ממנה]\u0006 \u0003חפץ\u0004 פלוני \u0003והדר הב לה גיטא\u0004 \u0005[וחזור\u0006 ואחר כך \u0005תן לה,\u0006 את \u0005הגט],\u0006 \u0003ואזל איהו ויהיב לה גיטא והדר שקל מינה\u0004 \u0005[והלך הוא ונתן לה גט ואחר\u0006 כך \u0005לקח ממנה]\u0006 את ה\u0003חפץ,\u0004 ש\u0003ר' יוחנן פוסל\u0004 אפילו \u0003בו,\u0004 בשליח הראשון, לפי ששינה מדעת המשלח ובטלה שליחותו, \u0003וכל שכן בשלוחו\u0004 של השליח, \u0003וריש לקיש מכשיר בשלוחו\u0004 של השליח, \u0003וכל שכן בו,\u0004 בשליח עצמו.","\u0003המביא גט ממדינת הים וחלה\u0004 ואינו יכול לסיים את שליחותו — \u0003עושה\u0004 (ממנה) \u0003שליח\u0004 אחר \u0003בבית דין ומשלחו, ואומר\u0004 השליח הראשון \u0003לפניהם,\u0004 לפני בית הדין: \u0003\"בפני נכתב ובפני נחתם\",\u0004 ועל סמך זה מכשירים בית הדין את הגט. \u0003ואין שליח אחרון צריך שיאמר: \"בפני נכתב ובפני נחתם\", אלא\u0004 דיו ש\u0003אומר:\u0004 \u0003שליח בית דין אני.\u0004","\u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לאבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו, בעי מיניה\u0004 \u0005[שאל ממנו],\u0006 \u0003מר' אבהו\u0004 אביך: האם \u0003שליח\u0004 של \u0003שליח משוי\u0004 \u0005[\u0006יכול \u0005למנות]\u0006 אף הוא \u0003שליח\u0004 נוסף, \u0003או לא? אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003לא תיבעי לכו\u0004 \u0005[תישאל לכם],\u0006 \u0003מדקתני\u0004 \u0005[ממה ששנה\u0006 במשנתנו\u0005]\u0006 \u0003\"אין השליח האחרון\", מכלל\u0004 הדברים שלא שנה \"שליח שני\" אלא \"שליח אחרון\" משמע \u0003דמשוי\u0004 \u0005[ש\u0006הוא, השליח השני \u0005ממנה]\u0006 \u0003שליח,\u0004 ולכן יכול להיות שימנו שליחים הרבה זה אחר זה,","\u0003אלא כי תיבעי לכו\u0004 \u0005[כאשר תישאל לכם]\u0006 השאלה, זה הוא הנושא שצריך לברר: \u0003כי משוי\u0004 \u0005[כאשר\u0006 השליח השני \u0005ממנה]\u0006 \u0003שליח\u0004 נוסף, האם צריך למנות אותו דווקא \u0003בבית דין, או אפילו שלא בבית דין? אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הא\u0004 \u0005[זו]\u0006 \u0003לא מבעיא לן\u0004 \u0005[מסופקת לנו],\u0006 \u0003מדקתני\u0004 \u0005[ממה ששנה\u0006 במשנה\u0005]:\u0006 \u0003אלא אומר \"שליח בית דין אני\",\u0004 משמע שכל שליח כזה צריך להתמנות על ידי בית דין. זו היתה גירסה אחת של מהלך הדברים בין אבימי וחכמים.","\u0003רב נחמן בר יצחק מתני הכי\u0004 \u0005[היה שונה כך]\u0006 את כל הענין הזה: \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לאבימי בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' אבהו, בעי מיניה\u0004 \u0005[שאל ממנו],\u0006 \u0003מר' אבהו\u0004 אביך: \u0003שליח\u0004 של \u0003שליח, כי משוי\u0004 \u0005[כאשר\u0006 הוא \u0005ממנה]\u0006 \u0003שליח,\u0004 האם צריך לעשות זאת דווקא \u0003בבית דין, או\u0004 אפילו \u0003שלא בבית דין?\u0004","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003ותיבעי לכו\u0004 \u0005[ותישאל,\u0006 תסתפק, \u0005לכם]\u0006 \u0003אי משוי\u0004 \u0005[אם\u0006 שליחו של שליח \u0005ממנה]\u0006 \u0003שליח בעלמא\u0004 \u0005[בכלל]?\u0006 \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003הא לא קא מיבעיא לן\u0004 \u0005[זו אינה מסופקת לנו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנתנו\u0005]:\u0006 \u0003\"אין השליח האחרון\", מכלל\u0004 הדברים אתה למד ש\u0003שליח משוי\u0004 \u0005[ממנה]\u0006 \u0003שליח. אלא כי קא מיבעיא לן\u0004 \u0005[מה שנשאל לנו]\u0006 האם צריך לעשות דבר זה \u0003בבית דין, או\u0004 אפילו \u0003שלא בבית דין? אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא נמי\u0004 \u0005[זו גם כן]\u0006 \u0003לא תיבעי לכו\u0004 \u0005[תישאל לכם],\u0006 \u0003דקתני\u0004 \u0005[ששנה\u0006 במשנה\u0005]:\u0006 \u0003אלא אומר \"שליח בית דין אני\",\u0004 משמע שכל מינוי כזה הוא דווקא מכוח שליחות בית דין.","\u0003אמר רבה: שליח בארץ ישראל עושה כמה שלוחין,\u0004 כלומר, הוא עושה שליח והלה עושה שליח אחר במקומו, ואינו זקוק לבית דין, שהרי בארץ ישראל אינו צריך להעיד בפניהם שבפניו נכתב ונחתם הגט. \u0003אמר רב אשי: אם מת\u0004 השליח ה\u0003ראשון\u0004 — \u0003בטלו כולן,\u0004 שהרי שליחות כולם אינה אלא מכוח שליחותו של הראשון, ומכיון שמת — בטלה שליחותו עימו.","\u0003אמר מר בר\u0004 \u0005[בנו]\u0006 של \u0003רב אשי: הא דאבא, דקטנותא\u0004 \u0005[זו של אבא מ\u0006זמן \u0005קטנותו]\u0006 \u0003היא\u0004 ולא דקדק בה היטב, שהרי \u0003אילו\u0004 היה \u0003מת בעל, מידי מששא אית בהו\u0004 \u0005[כלום ממש יש בהם]?!\u0006 גם אם כל השליחים חיים, האם היה בשליחותם ממש? — לא, ומדוע — משום ש\u0003כולהו\u0004 \u0005[כולם]\u0006 \u0003מכח מאן קאתו\u0004 \u0005[מי\u0006 הם \u0005באים]\u0006 — \u0003מכח\u0004 של ה\u0003בעל קאתו\u0004 \u0005[באו],\u0006 ולכן אם \u0003איתיה\u0004 \u0005[ישנו]\u0006 \u0003לבעל\u0004 בחיים — \u0003איתנהו לכולהו\u0004 \u0005[ישנם כולם\u0006 בשליחות\u0005],\u0006 \u0003ליתיה\u0004 \u0005[אינו]\u0006 \u0003לבעל\u0004 בחיים — \u0003ליתנהו לכולהו\u0004 \u0005[אינם כולם].\u0006 ודבר זה מוכיח שאף השליח הראשון אינו מעלה ואינו מוריד, שהרי השליחות באה מכוח הבעל, ולא מכוחו של השליח.","מסופר: \u0003ההוא גברא דשדר\u0004 \u0005[איש אחד ששלח]\u0006 \u0003לה גיטא לדביתהו\u0004 \u0005[גט לאשתו]\u0006 ביד שליח, \u0003אמר שליח: לא ידענא לה\u0004 \u0005[איני מכיר אותה],\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 הבעל: \u0003זיל יהביה\u0004 \u0005[לך תן אותו,\u0006 את הגט\u0005]\u0006 \u0003לאבא בר מניומי, דאיהו ידע לה, וליזיל וליתביה ניהלה\u0004 \u0005[שהוא מכיר אותה, ו\u0006הוא \u0005ילך ויתן אותו לה].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 השליח \u0003ולא אשכח\u0004 \u0005[מצא]\u0006 את \u0003אבא בר מניומי,\u0004 ולא ידע מה לעשות. \u0003אשכחיה\u0004 \u0005[מצא]\u0006 את \u0003ר' אבהו ור' חנינא בר פפא ור' יצחק נפחא, ויתיב\u0004 \u0005[והיה יושב]\u0006 \u0003רב ספרא גבייהו\u0004 \u0005[עימם],\u0006 ושאלם השליח מה לעשות. \u0003אמרו ליה\u0004 \u0005[לו]\u0006 שלושת חכמים אלה: \u0003מסור מילך קמי דידן\u0004 \u0005[\u0006את \u0005דבריך\u0006 ואת שליחותך \u0005לפנינו],\u0006 \u0003דכי ייתי\u0004 \u0005[שכאשר יבוא]\u0006 \u0003אבא בר מניומי ניתביניה ליה וליזיל וליתביניה לה\u0004 \u0005[ניתן אותו,\u0006 את הגט, \u0005לו, ו\u0006הוא \u0005ילך ויתן אותו לה].\u0006","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב ספרא: והא\u0004 \u0005[והרי]\u0006 שליח זה \u0003שליח שלא ניתן לגירושין הוא!\u0004 שהרי מעיקרו לא קיבל יפוי כוח לגרש את האישה, ויפוי הכוח שלו היה רק למסור את הגט לאבא בר מניומי, ואינו יכול להעביר את שליחות הגירושין לידי אחר. \u0003איכסופו\u0004 \u0005[התביישו]\u0006 שאמרו דבר שלא כדין.","\u0003אמר רבא: קפחינהו\u0004 \u0005[קיפח,\u0006 היכה \u0005אותם]\u0006 \u0003רב ספרא לתלתא רבנן סמוכי\u0004 \u0005[לשלושה חכמים סמוכים],\u0006 שהוא היה בבלי ולא נסמך והוא ניצח את כולם. \u0003אמר רב אשי: במאי קפחינהו\u0004 \u0005[במה קיפח אותם]?\u0006 בעצם לא היתה זו דחייה גמורה של דבריהם, שכן \u0003מי קאמר ליה\u0004 \u0005[האם אמר לו]\u0006 המשלח: \u0003אבא בר מניומי\u0004 יגרש את אשתי \u0003ולא את\u0004 \u0005[אתה]?\u0006 ויש לומר באמת כי עשה את השליח עצמו שליח לגירושין, ואמר לו שאם אינו מוצא את האשה יש לו גם דרך אחרת, למסור את הגט לאבא בר מניומי.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 את השמועה הזו באופן אחר, \u0003אמר רבא: קפחינהו\u0004 \u0005[קיפח,\u0006 היכה \u0005אותם]\u0006 \u0003רב ספרא לתלתא רבנן סמוכי בטעותא\u0004 \u0005[לשלושה חכמים סמוכים בטעות].\u0006 \u0003אמר רב אשי\u0004 והסביר את דבריו: \u0003מאי טעותא\u0004 \u0005[מה הטעות]\u0006 שיש בדבר? שכן \u0003מאי קא אמר ליה\u0004 \u0005[מה אמר לו]\u0006 הבעל לשליח: \u0003אבא בר מניומי\u0004 יתן את הגט לאשה, וכוונתו: \u0003ולא את\u0004 \u0005[אתה].\u0006","ועוד מסופר בנושא דומה: \u0003ההוא גברא דשדר\u0004 \u0005[איש אחד ששלח]\u0006 \u0003לה גיטא לדביתהו\u0004 \u0005[גט לאשתו]\u0006 על ידי שליח, \u0003אמר ליה\u0004 \u0005[לו],\u0006 \u0003לשליח: לא תיתביה ניהלה\u0004 \u0005[אל תתנו\u0006 את הגט \u0005לה]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום].\u0006 \u0003אתניס\u0004 \u0005[נאנס]\u0006 השליח, קרה לו מקרה \u0003בגו תלתין יומין\u0004 \u0005[בתוך שלושים יום]\u0006 וראה שלא יוכל להתעכב ולמוסרו לה אחרי שלושים יום כפי שאמר לו הבעל.","\u0003אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003רבא\u0004 ושאל מה יעשה. \u0003אמר רבא:\u0004 שליח ש\u0003חלה\u0004 שהתירו לו במשנה שימנה שליח אחר במקומו \u0003טעמא מאי\u0004 \u0005[טעם\u0006 הדבר \u0005מהו]\u0006 — \u0003משום\u0004 ש\u0003אנוס, האי נמי\u0004 \u0005[זה גם כן]\u0006 \u0003אנוס הוא! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מסור מילך קמי דידן\u0004 \u0005[\u0006את \u0005דבריך\u0006 ואת שליחותך \u0005לפנינו]\u0006 בתורת בית דין, \u0003דלבתר תלתין יומין משוינן\u0004 \u0005[שלאחר שלושים יום נמנה אנו]\u0006 \u0003שליח ויהיב ליה ניהלה\u0004 \u0005[ו\u0006הוא \u0005יתן אותו לה].\u0006 \u0003אמרו ליה רבנן\u0004 \u0005[לו חכמים]\u0006 \u0003לרבא: והא\u0004 \u0005[והרי]\u0006 שליח זה \u0003שליח שלא ניתן לגירושין הוא,\u0004 שהרי בתוך שלושים יום מזמן שמסר את שליחותו לרבא לא היה לו יפוי כוח לגרש! \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003כיון דלבתר תלתין יומין מצי מגרש\u0004 \u0005[שלאחר שלושים יום יכול\u0006 הוא \u0005לגרש],\u0006 \u0003כשליח שניתן לגירושין הוא.\u0004","וחזרו והקשו על רבא: בכל מקרה ששהה השליח ולא מסר את שליחותו מייד, יש מקום לפקפק: \u0003וליחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא\u0004 בינתיים \u0003פייס\u0004 הבעל את אשתו, ונמלך שלא לגרשה, ובטל הגט! \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 האומר לאשה שהוא נותן לה גט מעכשיו ויחול הגט \u0003מעכשיו אם לא באתי מכאן ועד שנים עשר חודש, ומת בתוך שנים עשר חודש\u0004 — \u0003הרי זה גט.\u0004","\u0003והוינן\u0004 \u0005[והיינו מקשים]\u0006 \u0003בה,\u0004 בהלכה זו: \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא פייס\u0004 את אשתו וביטל את הגט! \u0003ואמר רבה בר רב הונא: הכי\u0004 \u0005[כך]\u0006 \u0003אמר אבא מרי\u0004 \u0005[אבי מורי],\u0006 רב הונא, \u0003משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב: באומר \"נאמנת עלי\u0004 אשתי \u0003לומר שלא באתי\"!\u0004 וכאן כיון שלא נתן הבעל נאמנות זו — יש לחשוש שמא פייס!","\u0003איכסיף\u0004 \u0005[התבייש]\u0006 רבא שפסק שלא כדין. \u0003לסוף איגלאי מילתא\u0004 \u0005[התגלה הדבר]\u0006 ש\u0003ארוסה הואי\u0004 \u0005[היתה]\u0006 זאת. \u0003אמר רבא: אם אמרו בנשואה\u0004 שיש לחשוש שמא פייס — \u0003יאמרו בארוסה\u0004 שאינו מכיר אותה יפה? ואם כן יפה פסקתי מה שפסקתי.","\u0003אמר רבא: הא\u0004 \u0005[זו]\u0006 \u0003ודאי קא מיבעיא לן\u0004 \u0005[מסופקת לנו]:\u0006"],["\u0003כי משוו\u0004 \u0005[כאשר ממנים]\u0006 \u0003בית דין שליח\u0004 אחר, האם עושים את זה דווקא \u0003בפניו\u0004 של השליח הראשון, \u0003או\u0004 אפילו \u0003שלא בפניו? הדר פשטה\u0004 \u0005[חזר, ופתרה]\u0006 את הבעיה של עצמו: עושים זאת \u0003בין בפניו בין שלא בפניו.\u0004 וכן \u0003שלחו מתם\u0004 \u0005[משם],\u0006 מארץ ישראל: ממנים שליח אחר \u0003בין בפניו\u0004 של שליח ראשון \u0003בין שלא בפניו.\u0004","אגב מעשים אלה מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר: אי\u0004 \u0005[אם]\u0006 \u0003לא אתינא\u0004 \u0005[אבוא]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 — \u0003ליהוי גיטא\u0004 \u0005[יהא,\u0006 יחול, \u0005גט]\u0006 זה שאני נותן לאשתי. \u0003אתא ופסקיה מברא\u0004 \u0005[בא והפסיקתו המעבורת]\u0006 ולא היה יכול לעבור את הנהר. \u0003אמר להו\u0004 \u0005[להם],\u0006 לעומדים בצד השני של הנהר: \u0003\"חזו דאתאי, חזו דאתאי\"\u0004 \u0005[ראו שבאתי, ראו שבאתי]\u0006 ותהיו עדים בדבר. אבל בפועל לא בא, שהרי לא יכול היה לעבור את הנהר. \u0003אמר שמואל: לא שמיה מתיא\u0004 \u0005[שמה ביאה],\u0006 למרות שברור שרצה לעשות זאת, והרי זו מגורשת.","ועוד מעשה מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשים שהפקיד בידם גט: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא פייסנא לה\u0004 \u0005[אפייס אותה,\u0006 את אשתי\u0005]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 — \u0003ליהוי גיטא\u0004 \u0005[יהא\u0006 זה \u0005גט],\u0006 \u0003אזל פייסה\u0004 \u0005[הלך\u0006 ו\u0005פייס אותה],\u0006 \u0003ולא איפייסא\u0004 \u0005[התפייסה].\u0006 \u0003אמר רב יוסף: מי יהיב לה תרקבא דדינרי\u0004 \u0005[האם נתן לה תרקב,\u0006 כלי גדול, מלא \u0005דינרים]\u0006 \u0003ולא איפייסא\u0004 \u0005[התפייסה]?\u0006 ונמצא שלא קיים את תנאו לפייסה כראוי, והרי זה גט!","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, ש\u0003אמר רב יוסף: מידי תרקבא דדינרי בעי למיתב\u0004 \u0005[וכי תרקב דינרים היה צריך לתת]\u0006 \u0003לה\u0004 כדי שתתפייס? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003פייסה ולא איפייסא\u0004 \u0005[התפייסה],\u0006 ואם כן, קיים את תנאו מצד עצמו, ומה שלא התפייסה אינו אשמתו, ואינה מגורשת.","ומסבירים את ההבדל בין הלשונות הללו בדברי רב יוסף: \u0003הא\u0004 \u0005[\u0006לשון \u0005זו]\u0006 לפיה אין הגט חל — \u0003כמאן דאמר\u0004 \u0005[כ\u0006דעת \u0005מי שאומר]:\u0006 \u0003יש אונס בגיטין,\u0004 שאנו מתחשבים בענין זה של אונס אף לגבי תנאי בגיטין ואין הגט חל במקרה כזה, \u0003הא\u0004 \u0005[\u0006לשון \u0005זו]\u0006 לפיה הגט חל — \u0003כמאן דאמר\u0004 \u0005[כמי שאומר]:\u0006 \u0003אין אונס בגיטין.\u0004","בהמשך למשניות קודמות לפיהן כל עוד לא נודע אחרת אנו מניחים שאדם עודנו חי וקיים, אומרים עוד: \u0003המלוה מעות את הכהן\u0004 או \u0003את הלוי\u0004 או \u0003את העני להיות מפריש עליהן מחלקן,\u0004 שכאשר יפריש את התרומה והמעשרות מתבואתו, תיחשב התרומה כנתונה להם וכאילו מסרו לו את המתנות הללו בפרעון חובם, ויוכל הוא לאחר מכן למכור את התרומה לאחר (שהרי אינו רשאי לאוכלה), וכן יוכל להשתמש במעשר ראשון של לוי (חוץ מתרומת המעשר שניתנת לכהן), ובמעשר עני של העני. במקרים כאלה — \u0003מפריש עליהן\u0004 את המעשרות ומוכר \u0003בחזקת שהן קיימין, ואינו חושש שמא מת הכהן או הלוי, או העשיר העני\u0004 ושוב אינו ראוי ליטול מעשר עני.","אם בוודאי \u0003מתו\u0004 אותם אנשים — \u0003צריך ליטול רשות מן היורשים\u0004 כדי למכור. אבל \u0003אם הלוון\u0004 (הילווה להם) \u0003בפני בית דין\u0004 והתנה תנאי זה — \u0003אינו צריך ליטול רשות מן היורשין.\u0004","מתוך דברי המשנה עולה שהכהן (או הלוי, או העני) זוכה בחלק שבעל הבית מפריש, אלא שהוא מקנה מראש חלק זה לבעל הבית כתשלום חובו. ושואלים: \u0003ואף על גב\u0004 \u0005[ואף על פי]\u0006 ש\u0003לא אתו לידיה\u0004 \u0005[באו לידו]?!\u0006 שהרי עדיין לא הגיעה התרומה או המעשרות לידי הכהן או הלוי או העני וכיצד יכולים הם להקנות דבר שלא הגיע כלל לידיהם?","\u0003אמר רב:\u0004 מדובר כאן \u0003במכרי כהונה ולויה.\u0004 כלומר, אנשים שהם מכרים של הנותן והוא רגיל לתת להם את תרומתו בכל פעם שיש בידו תרומות ומעשרות, וחזקה זו יפה כוחה להחשיבם כאילו קיבלו. \u0003ושמואל אמר:\u0004 אפשר לפרש זאת רק \u0003במזכה להם,\u0004 לכהן, ללוי, או לעני מתנותיהם \u0003על ידי אחרים\u0004 שזוכים עבורם במתנות, וחוזר בעל הבית ונוטל אותן. \u0003עולא אמר: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 כשיטת \u0005מי היא]?\u0006 — שיטת \u0003ר' יוסי היא,\u0004 ש\u0003אמר: עשו את שאינו זוכה כזוכה,\u0004 שיש מקרים שאף שלא זכה אדם בדבר, מחשיבים אותו חכמים כאילו זכה בו, מפני התקנה.","ומסבירים מדוע יש בענין זה שלוש שיטות פירוש ולא הסכימו החכמים זה לזה. \u0003כולהו\u0004 \u0005[כולם],\u0006 שמואל ועולא, \u0003כרב לא אמרי\u0004 \u0005[אומרים],\u0006 כי \u0003במכרי\u0004 כהונה ולויה \u0003לא קתני\u0004 \u0005[שנה]\u0006 התנא במשנתנו, וכיון שלא נאמר הדבר הזה במשנה במפורש, אין לתלות בו. רב ועולא \u0003כשמואל לא קאמרי\u0004 \u0005[אומרים]\u0006 כי \u0003במזכה\u0004 לכהן ללוי ולעני על ידי אחר \u0003לא קתני\u0004 \u0005[שנה]\u0006 התנא במשנתנו. רב ושמואל \u0003כעולא נמי\u0004 \u0005[גם כן]\u0006 \u0003לא אמרי\u0004 \u0005[אומרים],\u0006 כי \u0003כיחידאה לא מוקמינן\u0004 \u0005[כ\u0006דעת \u0005יחיד,\u0006 ר' יוסי, \u0005אין אנו מעמידים]\u0006 את המשנה, אלא מנסים להעמיד אותה כדברי הכל.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003המלוה מעות את הכהן\u0004 או \u0003את הלוי,\u0004 או \u0003את העני להיות מפריש עליהן מחלקן\u0004 כפרעון חובם — \u0003מפריש עליהן בחזקת שהן קיימין,\u0004","\u0003ופוסק עמהן כשער הזול,\u0004 שיכול לקבוע את המחיר עבור אותן מתנות שעתיד להפריש לפי השער הזול יותר: או של זמן ההפרשה, או כשער של עכשיו בזמן ההלוואה. \u0003ואין בו משום רבית,\u0004 שאין אומרים שמפני שהקדים לתת להם כסף, והרי זה כמי שלוו ממנו, נמצא שנפרע מהם יותר ממה שנתן להם. \u0003ו\u0004חוב כזה \u0003אין שביעית משמטתו,\u0004 שהסכם זה נמשך גם אחרי שנת השמיטה.","\u0003ואם בא\u0004 נותן הכסף \u0003לחזור\u0004 בו מן ההסכם שביניהם — \u0003אינו חוזר. נתייאשו הבעלים,\u0004 שמשום מה סבר שאין בידו להפריש ונתייאש מן הכסף שנתן, אף על פי שאחר כך התברר לו שהתייאש בטעות — \u0003אין מפריש עליהם,\u0004 אלא הכסף שנתן נחשב כמתנה גמורה, \u0003לפי שאין מפרישין על האבוד.\u0004 שכיון שכבר התייאש, נמצא שהכסף נקנה לחלוטין למקבלים, ואם צריך להפריש, אינו יכול לסמוך על מה ששילם להם קודם.","ומבארים ברייתא זו: \u0003אמר מר\u0004 \u0005[החכם]\u0006 בברייתא: \u0003פוסק עמהם כשער הזול.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט\u0006 הדבר\u0005],\u0006 מדוע לא יעשה כן? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו],\u0006 ש\u0003אף על פי שלא פסק\u0004 ולא אמר במפורש שהוא עושה זאת כשער הזול — \u0003כמי שפסק דמי\u0004 \u0005[\u0006הוא \u0005נחשב]\u0006","ויכול לסמוך על כך. עוד שנינו בברייתא: \u0003ואין בו משום רבית,\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים: \u0003כיון דכי לית ליה\u0004 \u0005[שכאשר אין לו]\u0006 לכהן או ללוי, כגון שלא צמחה תבואה בשדה מחמת הבצורת, \u0003לא יהיב ליה\u0004 \u0005[אינו נותן לו,\u0006 למלווה\u0005]\u0006 דבר בתמורה להלוואה, \u0003כי אית ליה נמי\u0004 \u0005[כאשר יש לו גם כן]\u0006 \u0003אין בו משום רבית,\u0004 משום שאין כאן תנאי שיקבל יותר מסכום ההלוואה, אלא הכל לפי מה שיזדמן כאשר יקרה הדבר בפועל.","עוד שנינו בברייתא: \u0003ואין שביעית משמטתו,\u0004 ומדוע? — ש\u0003לא קרינא ביה\u0004 \u0005[קוראים אנו בו],\u0006 בחוב כזה \u0003\"לא יגש\u0004 את רעהו ואת אחיו כי קרא שמיטה לה'\u0003\"\u0004(דברים טו, ב), שהרי אין המלווה יכול לתבוע את ההלוואה הזו מן הלווה ואינו יכול לנוגשו.","עוד שנינו בברייתא: \u0003ואם בא לחזור\u0004 — \u0003אינו חוזר. אמר רב פפא: לא שנו אלא בעל הבית בכהן,\u0004 שאין בעל הבית יכול לומר: חוזר אני בי, והחזר לי את הכסף ואני לא אשתמש בתרומה שאפריש, \u0003אבל כהן בבעל הבית, אם בא לחזור\u0004 — \u0003חוזר בו,\u0004 ומה טעמו של דבר? — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 בכל מיקח, אם \u0003נתן לו\u0004 הקונה \u0003מעות ולא משך הימנו\u0004 \u0005[ממנו]\u0006 \u0003פירות\u0004 — \u0003יכול\u0004 המוכר \u0003לחזור בו.\u0004 ואף כאן הרי קיבל הכהן רק כסף ועדיין לא היתה הקנייה בפועל של פירות התרומה והמעשרות לבעל הבית, וכסף אינו עושה קנין גמור.","עוד שנינו בברייתא שאם \u0003נתייאשו הבעלים\u0004 — \u0003אין מפריש עליהן, לפי שאין מפרישין על האבוד.\u0004 ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאיליו\u0005]\u0006 שכך הוא! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דאקון\u0004 \u0005[שנעשתה\u0006 התבואה \u0005קנה]\u0006 והתייבשה, \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 \u0003אקנתא מילתא\u0004 \u0005[עשיית קנה דבר]\u0006 \u0003היא,\u0004 שבשלב זה יכולה עוד התבואה לחזור לאיתנה, ואינו מתייאש ממנה לגמרי, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאין התיקון מצוי במצב כזה, ואין אדם סומך על כך.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' אליעזר בן יעקב אומר: המלוה מעות את הכהן,\u0004 או \u0003את הלוי בבית דין, ומתו\u0004 — \u0003מפריש עליהן בחזקת אותו השבט\u0004 ששאר הלוויים זוכים במעשרות ואינו צריך לבדוק אם יש להם יורשים מיידיים, והוא מעכב את המעשרות שבידו בשביל חוב קרובם. \u0003ו\u0004אם מלווה \u0003את העני בבית דין, ומת\u0004 — \u0003מפריש עליו בחזקת עניי ישראל\u0004 האחרים. \u0003ר' אחי אומר: בחזקת עניי עולם.\u0004","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]?\u0006 שהרי ודאי גם ר' אחי אינו מתכוון אלא לעניי ישראל ולא לעניים גויים, שאין נותנים להם מעשר."],["ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל לגבי \u0003עניי כותיים\u0004 (שומרונים), האם הם כלולים בכלל העניים הזכאים לקבל ממעשר עני, או לא. שלדעת ר' אליעזר בן יעקב אינם בכלל ישראל ואין מפריש עבורם. ור' אחי סבור שאף שאינם ישראל לכל דבר, מכל מקום גרים הם, והם אותם \"עניי עולם\" שיכול להפריש ולזכות על פיהם במעשר.","עוד שנינו בברייתא כי אם \u0003העשיר העני\u0004 — \u0003אין מפריש עליו\u0004 עוד, \u0003וזכה הלה,\u0004 העני שלווה, \u0003במה שבידו.\u0004","ושואלים: \u0003ורבנן\u0004 \u0005[וחכמים],\u0006 \u0003מאי שנא\u0004 \u0005[מה,\u0006 מדוע \u0005שונה]\u0006 \u0003למיתה דעבוד תקנתא\u0004 \u0005[שעשו תקנה]\u0006 שיפריש עליו בחזקת עניים אחרים, \u0003ומאי שנא\u0004 \u0005[ומה,\u0006 מדוע \u0005שונה]\u0006 \u0003לעשירות\u0004 ש\u0003לא עבוד תקנתא\u0004 \u0005[עשו תקנה\u0006 כזו\u0005]?\u0006 ומשיבים: \u0003מיתה שכיחא\u0004 \u0005[מצוייה]\u0006 אבל \u0003עשירות לא שכיחא\u0004 \u0005[מצוייה]\u0006 ולא עשו תקנה לדבר שאינו מצוי. \u0003אמר רב פפא, היינו דאמרי אינשי\u0004 \u0005[זהו שאומרים האנשים]\u0006 בפתגם מקובל: אם אומרים לך \u0003חברך מית\u0004 \u0005[מת]\u0006 — \u0003אשר\u0004 \u0005[האמן],\u0006 אומרים לך \u0003איתעשר\u0004 \u0005[התעשר]\u0006 \u0003חברך\u0004 — \u0003לא תאשר\u0004 \u0005[תאמין]\u0006 עד שתיווכח בכך.","שנינו במשנה שאם \u0003מת\u0004 — \u0003צריך\u0004 המלווה \u0003ליטול רשות\u0004 מן היורשים. \u0003תניא\u0004 \u0005[שנויה ברייתא],\u0006 \u0003רבי אומר:\u0004 מדובר ב\u0003יורשין שירשו.\u0004 ותוהים: \u0003ומי איכא\u0004 \u0005[והאם יש]\u0006 \u0003יורשין\u0004 ש\u0003לא ירתי\u0004 \u0005[יורשים]?!\u0006 ולשם מה חזרה זו של \"יורשים שירשו\"? \u0003אלא אמר ר' יוחנן:\u0004 הכוונה היא ליורשים \u0003שירשו קרקע,\u0004 ומן הקרקע אפשר לגבות את חובות מורישם, \u0003ולא שירשו כספים,\u0004 שאם ירשו כספים, אין המלווים גובים אותם בחובות המוריש.","ובענין זה \u0003אמר ר' יונתן:\u0004 אם \u0003הניח\u0004 ליורשיו הלווה שמת קרקע \u0003מלא מחט\u0004 — \u0003גובה מלא מחט.\u0004 הניח \u0003מלא קרדום\u0004 — \u0003גובה מלא קרדום,\u0004 הכל לפי מה שהניח, \u0003ור' יוחנן אמר: אפילו הניח מלא מחט\u0004 — \u0003גובה\u0004 מכוח קרקע זו אפילו \u0003מלא קרדום.\u0004","\u0003וכמעשה דקטינא\u0004 \u0005[של\u0006 החלקה \u0005הקטנה]\u0006 שבא לפני \u0003אביי\u0004 שירשו בנים חלקת שדה קטנה שכיסתה רק חלק מן החוב שהיה חייב אביהם, וטרף אותה המלווה בחובו, ופסק אביי שאף ששילמו היתומים תמורתה, יכול המלווה לחזור ולטרוף אותה, וישלמו לו היתומים תמורתה, עד שיגבה את כל חובו.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003ישראל שאמר ללוי \"מעשר יש לך בידי\"\u0004 שהפרשתי מתבואתי עבורך, \u0003אין חוששין לתרומת מעשר שבו\u0004 (עשירית, אותה מקבל הכהן ואסורה באכילה ללוי ולישראל), אלא כולו בחזקת מעשר ראשון. אבל אם אמר לו: \u0003\"כור מעשר יש לך בידי\"\u0004 — \u0003חוששין לתרומת מעשר שבו.\u0004","על לשון הברייתא תוהים: \u0003מאי קאמר\u0004 \u0005[מה אמר],\u0006 מה פירוש הדבר? \u0003אמר אביי: הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא: \u0003ישראל שאמר ללוי \"מעשר יש לך בידי והילך\u0004 (והרי לך) \u0003דמיו\u0004 של המעשר תמורתו \u0003\"\u0004— \u0003אין חוששין שמא עשאו\u0004 הלוי \u0003תרומת מעשר על מקום אחר\u0004 שיש לו בו מעשרות, שכיון שלא ידע הלוי כמה מעשר יש בידי הישראל — לא סמך עליו. אבל אם אמר לו \u0003\"כור מעשר יש לך בידי והילך דמיו\"\u0004 — \u0003חוששין שמא\u0004 כיון שידע כמה מעשר עומד לרשותו \u0003עשאו תרומת מעשר על מקום אחר.\u0004","ותוהים: \u0003אטו ברשיעי עסקינן\u0004 \u0005[וכי ברשעים אנו עוסקים],\u0006 \u0003דשקלי דמי\u0004 \u0005[ש\u0006הם גם \u0005לוקחים כסף\u0006 עבור המעשר\u0005]\u0006 \u0003ומשוו ליה\u0004 \u0005[ו\u0006גם \u0005עושים אותו]\u0006 אחר כך \u0003תרומת מעשר?\u0004","\u0003אלא אמר רב משרשיא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי, הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא: \u0003ישראל שאמר לבן לוי \"מעשר לאביך בידי,\u0004 שהודעתי לו בחייו על הדבר, \u0003הילך דמיו\u0004 לתמורתו \u0003\"\u0004— \u0003אין חוששין שמא עשאו אביו\u0004 לפני מותו \u0003תרומת מעשר על מקום אחר,\u0004 ויכול בנו ליטול דמי המעשר. אבל אם אמר לו \u0003\"כור מעשר לאביך בידי והילך דמיו\"\u0004 — \u0003חוששין שמא עשאו אביו תרומת מעשר על מקום אחר,\u0004 ואין הבן יכול לקחת דמי המעשר.","ושואלים: ומדוע יש לחשוש שהרים האב תרומה על מקום אחר? \u0003וכי נחשדו חברים לתרום שלא מן המוקף\u0004 (הסמוך)? הלא חכמים אמרו שאין לתרום אלא מן המוקף (= הסמוך)!","\u0003אלא אמר רב אשי: הכי קאמר\u0004 \u0005[כך אמר]\u0006 בברייתא: \u0003בן ישראל שאמר ללוי \"כך אמר לי אבא: מעשר לך\u0004 (ללוי) \u0003בידי\", או\u0004 שאמר לו אביו \u0003\"מעשר\u0004 ששייך \u0003לאביך בידי\"\u0004 — \u0003חוששין לתרומת מעשר ש\u0004מעורבת \u0003בו\u0004 ועדיין לא הופרשה, ומדוע? \u0003כיון דלא קיץ\u0004 \u0005[שאינו קצוץ,\u0006 קצוב\u0005]\u0006 \u0003לא הוה\u0004 \u0005[היה]\u0006 \u0003מתקן ליה\u0004 \u0005[אותו]\u0006 \u0003בעל הבית\u0004 ומפריש ממנו תרומת מעשר. אבל אם אמר לו: \u0003\"כור מעשר לך בידי\", או: \"כור מעשר לאביך בידי\"\u0004 — \u0003אין חוששין לתרומת מעשר שבו,\u0004 ומדוע? — \u0003כיון דקיץ\u0004 \u0005[ש\u0006הוא \u0005קצוץ],\u0006 שיש כמות מסויימת ודאי כבר \u0003תקוני תקניה\u0004 \u0005[תיקן אותו]\u0006 \u0003בעל הבית.\u0004","ושואלים: \u0003וכי יש לו רשות לבעל הבית לתרום תרומת מעשר\u0004 במקום הלוי? הרי דבר זה צריך הלוי לתת לכהן! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 שיטת \u0003אבא אלעזר בן גמלא היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003אבא אלעזר בן גמלא אומר:\u0004 נאמר: \u0003\"ונחשב לכם תרומתכם\u0004 כדגן מן הגורן וכמלאה מן היקב\u0003\"\u0004 (במדבר יח, כז),"],["\u0003בשתי תרומות הכתוב מדבר, אחת תרומה גדולה ואחת תרומת מעשר,\u0004 ומאחר שנאמרו שתיהן יחד, יש היקש והשוואה בין התרומות הללו: \u0003כשם שתרומה גדולה ניטלת באומד\u0004 (הערכה), ואינו חייב למדוד אותה במדוייק, שהרי מן התורה אין לה שיעור מסויים, \u0003ו\u0004כן ניטלת \u0003במחשבה\u0004 שאינו צריך להפריש אותה בפועל, אלא דיו שחושב להפריש אותה, ואחר כך יתננה, \u0003כך תרומת מעשר ניטלת\u0004 גם \u0003באומד ו\u0004גם \u0003במחשבה.\u0004 וההשוואה מלמדת גם לצד שני: \u0003וכשם שיש לו רשות לבעל הבית לתרום תרומה גדולה, כך יש לו רשות לבעל הבית לתרום תרומת מעשר.\u0004","\u0003המניח פירות להיות מפריש עליהן תרומה ומעשרות,\u0004 שהוא סומך על הפירות הללו, וכאשר רוצה לתקן טבל שלפניו אומר שכל תרומה שצריך להפריש כדי לתקן טבל זה תבוא מפירות אלה שהניח לצורך זה. או הניח \u0003מעות להיות מפריש\u0004 ולפדות \u0003עליהן מעשר שני\u0004 — הרי זה הולך ו\u0003מפריש עליהן בחזקת שהן קיימין,\u0004 ואינו צריך לחשוש שמא אבדו בינתיים הפירות או המעות הללו. \u0003אם אבדו\u0004 בכל זאת — \u0003הרי זה חושש\u0004 לאותם טבלים שתיקן \u0003מעת לעת\u0004 (עשרים וארבע שעות) וצריך להפריש מהם בשנית, וכאשר יבואר בגמרא, אלו \u0003דברי ר' אלעזר.\u0004","\u0003ר' יהודה אומר: בשלשה פרקים\u0004 (זמנים) \u0003בודקין את היין\u0004 שהניח להפריש ממנו תרומה ומעשרות, שאם החמיץ אינו יכול להפריש ממנו עוד. וזמנים אלה הם: \u0003בקידום,\u0004 כאשר מנשבת רוח קדים \u0003של מוצאי החג\u0004 (חג הסוכות), \u0003ובהוצאת סמדר,\u0004 כאשר נושרים הפרחים ונראים ענבים קטנים כעין אשכולות, \u0003ובשעת כניסת מים בבוסר\u0004 שבוסר הענבים מתמלא בנוזל (\"מים\"), ובזמנים אלה הקשורים בשינוי מזג האויר יש לבדוק אם לא החמיץ היין.","שנינו שאם אבדו הפירות או המעות חושש להם מעת לעת. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003מעת לעת\u0004 שאמר ר' אלעזר? \u0003ר' יוחנן אמר: מעת לעת של בדיקה,\u0004 משעה שבדק וגילה שאבדו חושש שמא כבר אבדו עשרים וארבע שעות קודם לכן. \u0003ר' אלעזר בן אנטיגנוס אומר משום\u0004 (בשם) \u0003ר' אלעזר בר' ינאי:\u0004"],["\u0003מעת לעת של הנחה,\u0004 שחושש עד לאותו מעת לעת ראשון שחלף מאז הניח את הפירות או את המעות.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אם אבדו\u0004 — \u0003הרי זה חושש מעת לעת.\u0004 ומעתה, \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003מעת לעת של בדיקה\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 הסגנון,","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003מעת לעת של הנחה, האי\u0004 \u0005[\u0006לשון \u0005זו]\u0006 \u0003\"מעת לעת\"\u0004 אינה מדוייקת, שכן \u0003\"עד מעת לעת\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ומעירים: אכן, \u0003קשיא\u0004 \u0005[קשה]\u0006 לשיטה זו.","שנינו במשנה שאלו \u0003דברי ר' אלעזר\u0004 בן שמוע התנא הם, \u0003אמר ר' אלעזר\u0004 בן פדת האמורא: \u0003חלוקין עליו חביריו על ר' אלעזר,\u0004 ולדבריהם כל הפירות שתוקנו בהפרשה על ידי הפירות שאבדו, כולם בחזקת טבל וצריך להפריש עליהם מחדש תרומות ומעשרות. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מקוה שנמדד ונמצא חסר\u0004 משיעור כמות המים הראויה למיקווה, \u0003כל טהרות שנעשו על גביו\u0004 (על סמך הטבילה בו) \u0003למפרע, בין ברשות היחיד\u0004 שספק טומאה שבה טמא, \u0003בין ברשות הרבים\u0004 שספק טומאה שבה טהור — כולן \u0003טמאות.\u0004","ומעירים: \u0003פשיטא דחלוקין\u0004 \u0005[פשוט ש\u0006הם \u0005חלוקים]\u0006 עליו, שהרי ברור ששיטה זו חלוקה על ר' אלעזר התנא שהרי לדעתו יש לטמא רק מעת לעת, ומה בא ר' אלעזר האמורא לחדש בדבר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"למפרע\",\u0004 הכוונה אינה לכל הזמן כולו, אלא רק \u0003מעת לעת\u0004 והרי זו כדעת ר' אלעזר, על כן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שיש כאן מחלוקת בסיסית לגבי חזקות.","שנינו במשנה, \u0003ר' יהודה אומר: בשלשה פרקים\u0004 בודקים את היין: בקידום של מוצאי החג וכו'. \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003בקידום\u0004 (בזמן של רוח קדים) \u0003של מוצאי החג של תקופה.\u0004 שחג הסוכות חל באותה שנה כבר בתוך תקופת תשרי (אחד מארבעת חלקי שנת השמש), אבל אם נמשכה תקופת תמוז (שלא כרגיל) עד החג — לא.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003ר' יהודה אומר בשלשה פרקים מוכרין את התבואה: לפני\u0004 זמן \u0003הזרע,\u0004 לפני זמן הזריעה, \u0003ובשעת הזרע,\u0004 בעונת הזריעה, \u0003ובפרוס הפסח,\u0004 סמוך קצת לפסח. \u0003ובשלשה פרקים מוכרין את היין: בפרוס הפסח, ובפרוס עצרת, ובפרוס החג. ושמן\u0004 מוכרים — \u0003מעצרת ואילך.\u0004 ושואלים: \u0003למאי הלכתא\u0004 \u0005[למה\u0006 לאיזו \u0005הלכה]\u0006 נאמרו הדברים הללו? ימכרו מתי שירצו! \u0003אמר רבא, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב פפא: ל\u0004גבי \u0003שותפין\u0004 נאמרה הלכה זו, ששותף רשאי למכור שלא מדעת חבירו רק בפרקים הללו שהם זמני המכירה הקבועים, אבל אם רוצה למכור בזמן אחר, צריך להימלך בשותפו. \u0003מכאן ואילך,\u0004 לאחר הזמנים האלה, \u0003מאי\u0004 \u0005[מה]\u0006 הדין? \u0003אמר רבא: כל יומא פירקיה\u0004 \u0005[יום זמנו]\u0006 \u0003הוא\u0004 למכור.","כיון שהוזכר כאן ענין של קידום, רוח הקדים. מביאים את הכתוב: \u0003\"ויהי כזרח השמש וימן אלהים רוח קדים חרישית\"\u0004 (יונה ד, ח). ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"חרישית\"? אמר רב יהודה: בשעה שמנשבת, עושה\u0004 רוח זו \u0003תלמים תלמים בים,\u0004 כאילו היא חורשת את הים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: אי הכי\u0004 \u0005[אם כך],\u0006 \u0003היינו דכתיב\u0004 \u0005[\u0006וכי \u0005זהו\u0006 מה \u0005שנאמר]\u0006 שם: \u0003\"ותך\u0004 \u0003השמש על ראש יונה ויתעלף\"\u0004 (יונה, ד,ח)? והרי מכאן נראה שלא היתה זו רוח חזקה, ודווקא משום כך היה חם כל כך! \u0003אלא אמר רבה: בשעה שמנשבת, משתקת\u0004 את \u0003כל הרוחות מפניה,\u0004 ולכן נקראת \"חרישית\" — משום ששאר הרוחות כאילו מחרישות מפניה, וכיון שרק היא לבדה מנשבת נהיה חם מאד. \u0003והיינו דכתיב\u0004 \u0005[וזהו שנאמר]:\u0006 \u0003\"אשר בגדיך חמים בהשקט ארץ מדרום\"\u0004 (איוב לז, יז). \u0003אמר ר' תחליפא בר רב חסדא אמר רב חסדא\u0004 בפירוש הפסוק: \u0003אימתי בגדיך חמים,\u0004 כלומר, מתי גדול החום — \u0003בשעה שהשקיט ארץ מדרום. שבשעה שמנשבת\u0004 רוח דרומית זו הריהי \u0003משתקת כל הרוחות מפניה.\u0004","מסופר: \u0003רב הונא ורב חסדא הוו יתבי\u0004 \u0005[היו יושבים].\u0006 \u0003חליף ואזיל\u0004 \u0005[חלף ועבר]\u0006 החכם \u0003גניבא עלייהו\u0004 \u0005[על פניהם],\u0006 \u0003אמר חד לחבריה\u0004 \u0005[אחד\u0006 מהם \u0005לחבירו]:\u0006 \u0003ניקום מקמיה, דבר אוריין\u0004 \u0005[נעמוד מלפניו, שבן תורה]\u0006 \u0003הוא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אידך\u0004 \u0005[האחר]:\u0006 \u0003מקמי פלגאה ניקום\u0004 \u0005[מלפני בעל מחלוקת\u0006 זה \u0005נעמוד]?\u0006 \u0003אדהכי אתא איהו לגבייהו\u0004 \u0005[בינתיים בא הוא אליהם],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003במאי עסקיתו\u0004 \u0005[במה עסקתם]\u0006 כאשר ישבתם יחד? \u0003אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003ברוחות\u0004 עסקנו.","\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב חנן בר רבא אמר רב: ארבע רוחות מנשבות בכל יום, ורוח צפונית מנשבת עם כולן, שאלמלא כן,\u0004 אם לא היתה מנשבת, \u0003אין העולם מתקיים אפילו שעה אחת. ורוח דרומית\u0004 היא הרוח ה\u0003קשה מכולן, ואלמלא\u0004 המלאך הקרוי \u0003בן נץ\u0004 שהוא \u0003מעמידה\u0004 שלא תנשב ביותר, היתה \u0003מחרבת\u0004 את \u0003כל העולם כולו מפניה, שנאמר: \"המבינתך יאבר נץ יפרש כנפו לתימן\"\u0004 (איוב לט, כו).","ועוד מסופר: \u0003רבא ורב נחמן בר יצחק הוו יתבי\u0004 \u0005[היו יושבים],\u0006 \u0003הוה חליף ואזיל\u0004 \u0005[היה חולף ועובר]\u0006 לידם \u0003רב נחמן בר יעקב דיתיב בגוהרקא דדהבא ופריס עליה סרבלא דכרתי\u0004 \u0005[שהיה יושב באפיריון של זהב והיה פרוס עליו מעיל ירוק],\u0006 \u0003רבא אזל לגביה\u0004 \u0005[הלך אליו],\u0006 \u0003רב נחמן בר יצחק לא אזל לגביה\u0004 \u0005[הלך אליו].\u0006 \u0003אמר:\u0004 מאחר ואיני יודע את זהות היושבים באפיריון, \u0003דלמא מאינשי דבי ריש גלותא נינהו\u0004 \u0005[שמא מאנשי בית ראש הגולה הם\u0006 אלה\u0005],\u0006 \u0003רבא צריך להו\u0004 \u0005[אותם],\u0006 \u0003אנא לא צריכנא להו\u0004 \u0005[אני איני צריך אותם].\u0006","\u0003כדחזא\u0004 \u0005[כאשר ראה]\u0006 ש\u0003רב נחמן בר יעקב הוה\u0004 \u0005[הוא]\u0006 \u0003אזיל לגביה\u0004 \u0005[הלך\u0006 גם הוא \u0005אליו],\u0006 \u0003גלי לדרעיה\u0004 \u0005[גילה\u0006 רב נחמן בר יעקב \u0005את זרועו],\u0006 \u0003אמר:\u0004 הרוח הקרוייה \u0003\"שדיא\" נשיב\u0004 \u0005[נושבת]\u0006 עכשיו! \u0003אמר רבא, הכי\u0004 \u0005[כך]\u0006 \u0003אמר רב: אשה מפלת בו\u0004 (בגללו), \u0003ושמואל אמר: אפילו מרגלית שבים מרקבת בו, ר' יוחנן אמר: אפילו שכבת זרע שבמעי אשה מסרחת בו.\u0004","על כך \u0003אמר רב נחמן בר יצחק\u0004 שהיה שם: \u0003ושלשתן מקרא אחד דרשו,\u0004 שנאמר: \u0003\"כי הוא בין אחים יפריא יבוא קדים רוח ה' ממדבר עלה ויבוש מקורו\u0004 ויחרב מעיינו הוא ישסה אוצר כל כלי חמדה\u0003\"\u0004 (הושע יג, טו). וכך הוא מסביר: \u0003\"יבוש מקורו\"\u0004 — \u0003זו מקורה\u0004 (רחמה) \u0003של אשה,\u0004 והוא הסמך לדברי החכם שאמר שאשה מפלת בו. \u0003\"ויחרב מעינו\"\u0004 — \u0003זה שכבת זרע שבמעי אשה.\u0004 \u0003\"הוא ישסה אוצר כל כלי חמדה\"\u0004 — \u0003זו מרגלית שבים.\u0004","\u0003אמר רבא: עדי סוראה\u0004 \u0005[זה מסורא]\u0006 \u0003הוא, דדייקי קראי\u0004 \u0005[ש\u0006הם \u0005מדייקים בכתובים].\u0006 אגב כך שואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"כי הוא בין אחים יפריא\"? אמר רבא: אפילו\u0004"],["\u0003שופתא בקופינא דמרא רפיא\u0004 \u0005[הקת בחור המעדר מתרופפת]\u0006 שמפרש לשון \"יפריא\", שמפריד בין דברים צמודים (\"אחים\"). \u0003רב יוסף אמר\u0004 כעין זה: \u0003אפילו סיכתא בדפנא רפיא\u0004 \u0005[יתד\u0006 התקועה \u0005בדופן, מתרופפת].\u0006 \u0003רב אחא בר יעקב אמר: אפילו קניא בכופתא רפיא\u0004 \u0005[קנה\u0006 הקלוע \u0005בתוך סל, מתרופף].\u0006","","\u0003השולח גט לאשתו, והגיע\u0004 (השיג) הבעל עצמו את ה\u0003שליח, או ששלח אחריו שליח\u0004 אחר, \u0003ואמר לו: \"גט שנתתי לך בטל הוא\"\u0004 — \u0003הרי זה בטל\u0004 ואין האשה מתגרשת בו. וכיוצא בזה, אם \u0003קידם\u0004 הבעל \u0003אצל אשתו\u0004 לפני שהגיע הגט לידה \u0003או ששלח אצלה שליח, ואמר לה : \"גט ששלחתי לך בטל הוא\"\u0004 — \u0003הרי זה בטל.\u0004 אבל \u0003אם משהגיע\u0004 כבר \u0003גט לידה,\u0004 ושלח אחריו שליח או בא אחר כך בעצמו — \u0003שוב אינו יכול לבטלו,\u0004 שהרי חלו כבר הגירושין.","נמסר ש\u0003בראשונה היה\u0004 בעל המבקש לבטל גט ששלח \u0003עושה בית דין ממקום אחר ומבטלו,\u0004 את הגט בפניהם לפני שהיה מגיע לאשה, \u0003התקין רבן גמליאל הזקן שלא יהו עושין כן, מפני תיקון העולם,\u0004 שהרי השליח יכול בינתיים למסור את הגט לאשה והיא עלולה להינשא מבלי לדעת שהבעל ביטל בינתיים את הגט.","מדייקים בלשון המשנה: שנינו שהשולח גט לאשתו והגיע בשליח וביטלו — הגט בטל. ונדייק: \u0003\"הגיעו\"\u0004 (השיג אותו) \u0003לא קתני\u0004 \u0005[שנה]\u0006 במשנה, שמשמעו שהשתדל כדי להשיגו \u0003אלא \"הגיע\",\u0004 משמע \u0003ואפילו ממילא\u0004 \u0005[מעצמו]\u0006 פגשו, שלא השתדל להשיגו אלא במקרה פגשו, ואמר לו שהגט בטל — הרי זה בטל, \u0003ולא אמרינן לצעורה\u0004 \u0005[ואין אנו אומרים\u0006 שבמקרה כזה \u0005לצער\u0006 את אשתו בלבד\u0005]\u0006 \u0003הוא דקא מיכוין\u0004 \u0005[שמתכוון]\u0006 ואין הוא באמת מבטל את הגט.","ושואלים: מה ששנינו \u0003\"או ששלח אחריו שליח\" למה לי\u0004 לומר? הרי בכל ענין שלוחו של אדם כמותו, וכשם שהוא יכול לבטל את שליחות הראשון כך גם שליחו יכול לבטל! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003לא אלימא שליחותיה דבתרא משליחותיה דקמא דלבטליה\u0004 \u0005[אינה חזקה שליחותו של האחרון\u0006 יותר \u0005משליחותו של הראשון\u0006 שיוכל זה האחרון \u0005לבטלנה],\u0006 וכיון שמינה את הראשון כשליח — רק הוא עצמו יכול לבטל את השליחות, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 ששליחותו של האחרון יכולה לבטל את שליחותו של שליח ראשון.","ועוד שואלים: מה ששנינו \u0003\"קדם הוא אצל אשתו\" למה לי\u0004 לשנות במשנה, והרי מובן הדבר שיכול אדם לבטל את גיטו לפני שניתן לאשתו! ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר],\u0006 \u0003כי לא אמרינן\u0004 \u0005[כאשר אין אנו אומרים]\u0006 שרק \u0003לצעורה קא מיכוין\u0004 \u0005[לצער אותה הוא מתכוון]\u0006 (וכפי שדייקנו לעיל), \u0003הני מילי\u0004 \u0005[דברים אלה\u0006 אמורים\u0005]\u0006 כשאמר זאת ל\u0003שליח, אבל לדידה\u0004 \u0005[\u0006אם אמר \u0005לה]\u0006 \u0003ודאי לצעורה קא מיכוין\u0004 \u0005[לצער אותה\u0006 הוא \u0005מתכוון]\u0006 ובאמת אין רצונו לבטל את הגט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שביטול זה גמור הוא.","ושואלים עוד: \u0003\"או ששלח אצלה שליח\" למה לי\u0004 לומר? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]:\u0006 \u0003איהו\u0004 \u0005[הוא\u0006 עצמו\u0005]\u0006 \u0003הוא\u0004 ש\u0003לא טרח אדעתא לצעורה\u0004 \u0005[טורח\u0006 רק \u0005על דעת לצער אותה]\u0006 ולהודיע לה שהוא בטל, \u0003אבל שליח\u0004 ש\u0003לא איכפת ליה\u0004 \u0005[לו]\u0006 לבעל \u0003כי טרח\u0004 \u0005[שהוא טורח]\u0006 לריק, \u0003ודאי\u0004 רק \u0003לצעורה קא מיכוין\u0004 \u0005[לצער אותה\u0006 הוא \u0005מתכוון]\u0006 כאשר הוא שולח אותו, ובאמת, אין כוונתו לבטל את הגט, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל אלה הגט בטל.","עוד שנינו: \u0003אם משהגיע גט לידה\u0004 — \u0003אינו יכול לבטלו,\u0004 ותוהים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005],\u0006 שהרי כבר נעשה מעשה הגירושין בפועל! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא במקרה \u0003דמהדר עליה מעיקרא לבטולי\u0004 \u0005[שהיה מחזר עליו,\u0006 על הגט הזה \u0005מתחילה לבטלו]\u0006 עוד לפני שהגיע לידה, \u0003מהו\u0004 \u0003דתימא\u0004 \u0005[שתאמר]:\u0006 כאשר מבטל את הגט, אף לאחר שהגיע לידה, \u0003איגלאי מלתא\u0004 \u0005[התגלה הדבר]\u0006 \u0003למפרע דבטולי בטליה\u0004 \u0005[שביטל אותו]\u0006 מתחילה, עוד לפני שהגיע הגט לידי האשה, על כן, \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שכיון שלא ביטלו בפועל קודם לכן — אין זה ביטול. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אמר על הגט ששלח אחת הלשונות הללו: \u0003\"בטל הוא\",\u0004 או \u0003\"אי איפשי\u0004 (אין רצוני) \u0003בו\"\u0004 — \u0003דבריו קיימין\u0004 והגט בטל, שהרי בידו לבטלו. אבל אם אמר בלשון: \u0003\"פסול הוא\",\u0004 או \u0003\"אינו גט\"\u0004 — \u0003לא אמר כלום,\u0004 שהרי גט זה נעשה כהלכתו.","","ושואלים: \u0003למימרא\u0004 \u0005[האם לומר]\u0006 וללמוד מכאן שהלשון \u0003\"בטל\" לישנא דלבטיל\u0004 \u0005[לשון שיתבטל]\u0006 \u0003משמע?\u0004 שהוא לשון עתיד שבא לבטל את הגט, ולא רצה לומר כבר בטל קודם לכן? \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבה בר איבו אמר רב ששת, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רבה בר אבוה: מקבל מתנה שאמר לאחר שבאתה\u0004 (באה) \u0003מתנה לידו: \"מתנה זו מבוטלת\",\u0004 או \u0003\"תיבטל\",\u0004 או \u0003\"אי איפשי בה\"\u0004 — \u0003לא אמר כלום,\u0004 שהרי כבר זכה בה, ואינו יכול לבטל את זכייתו. אבל אם אמר: \u0003\"בטלה היא\",\u0004 או \u0003\"אינה מתנה\",\u0004 שמתחילה לא זכה בה — \u0003דבריו קיימין. אלמא\u0004 \u0005[מכאן]\u0006 נלמד שלשון \u0003\"בטל\" מעיקרא\u0004 \u0005[מתחילה]\u0006 \u0003משמע\u0004 ולא לעתיד, בניגוד למשמעות הברייתא!","\u0003אמר אביי: \"בטל\"\u0004"],["\u0003שתי לשונות משמע,\u0004 ושתיהן כלולות במלה זו, ואכן \u0003משמע\u0004 ש\u0003בטל\u0004 כבר מתחילה, \u0003ומשמע\u0004 גם \u0003דליבטיל\u0004 \u0005[שיתבטל]\u0006 בעתיד. ואולם המשמעות משתנה ביחס לכל אחד מן הדברים; \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003גט לישנא דמהני ביה קאמר\u0004 \u0005[לשון שמועילה בו אמר]\u0006 וכוונתו לפיכך שיתבטל בעתיד, מאותו רגע והלאה, ואף \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003מתנה לישנא דמהני\u0004 \u0005[לשון שמועילה ]\u0006 \u0003בה קאמר\u0004 \u0005[ אמר]\u0006 שאינו יכול לבטל אותה מכאן ולהבא לאחר שכבר זכה בה, ומשום כך כוונתו שבטלה מתחילתה.","ועוד \u0003אמר אביי\u0004 ביחס שבין גט למתנה: \u0003נקיטינן\u0004 \u0005[מחזיקים אנו]\u0006 בכלל הזה: \u0003שליח מתנה הרי הוא כשליח הגט.\u0004 ומסבירים: \u0003נפקא מינה\u0004 \u0005[יוצאת מכאן,\u0006 נלמדת\u0005]\u0006 מסקנה להלכה שאם אדם אומר לשליחו \u0003\"הולך\u0004 מתנה זו לפלוני \u0003\"\u0004— \u0003לאו כ\"זכי\" דמי\u0004 \u0005[אינו נחשב כ\u0006אומר לו \u0005\"זכה\"]\u0006 ולכן כל עוד לא הגיעה המתנה לידי המקבל, יכול השולח לחזור בו, ואין אומרים שזכה המקבל במתנה מרגע שניתנה לשליח.","מסופר: \u0003רבינא אשכחיה\u0004 \u0005[מצא אותו],\u0006 את \u0003רב נחמן בר יצחק דתלי וקאי בעיברא דדשא\u0004 \u0005[שהיה תלוי ועומד,\u0006 נשען, \u0005על בריח הדלת]\u0006 ומהרהר, \u0003וקא מיבעיא ליה\u0004 \u0005[והיה מסופק]\u0006 בשאלה הזו: אם הבעל אמר רק \u0003\"\u0004גט זה \u0003בטל\"\u0004 ולא אמר \"בטל הוא\", \u0003מהו\u0004 הדין? האם כוונתו לבטל את הגט מאותה שעה, ובטל הגט על ידי כך, או שהוא רק כמציין עובדה שגט זה אינו כשר ובטל, ולא בטל הגט בכך? לשאלה זו לא נמצאה תשובה ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 השאלה במקומה.","\u0003אמר רב ששת, ואמרי לה במתניתא תנא\u0004 \u0005[ויש אומרים\u0006 ש\u0005בברייתא\u0006 היא \u0005שנויה],\u0006 אם אמר: \u0003\"גט זה לא יועיל\",\u0004 או \u0003\"לא יתיר\",\u0004 או \u0003\"לא יעזיב\"\u0004 (יגרש), או \u0003\"לא ישלח\",\u0004 או \u0003\"לא יגרש\",\u0004 או \u0003\"יהא חרס\",\u0004 או \u0003\"יהא כחרס\"\u0004 — בכל אלה הלשונות \u0003דבריו קיימין,\u0004 והגט בטל.","אם אמר בלשון: \u0003\"\u0004גט זה \u0003אינו מועיל\",\u0004 או \u0003\"אינו מתיר\",\u0004 או \u0003\"אינו מעזיב\",\u0004 או \u0003\"אינו משלח\",\u0004 או \u0003\"אינו מגרש\",\u0004 או \u0003\"חרס הוא\",\u0004 או \u0003\"כחרס הוא\"\u0004 — \u0003לא אמר כלום,\u0004 שהרי בכוחו רק לבטל את תוקפו של הגט על ידי החלטתו, אבל אם רק אומר דברים על מהותו של הגט — אין להם כל משמעות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים שאלה זו: אם אומר: \u0003\"הרי הוא חרס\", מהו?\u0004 האם כוונתו לקבוע דברים לגבי הגט ולומר שאינו גט כשר, או שמביע את רצונו לבטל אותו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא לרב אשי: מאי שנא\u0004 \u0005[\u0006ב\u0005מה שונה]\u0006 הלשון \u0003מ\"הרי הוא הקדש\",\u0004 או \u0003\"הרי הוא הפקר\",\u0004 שבודאי כוונתו לעשות אותו מכאן ולהלאה הקדש או הפקר? ואף כאן יועילו דבריו לבטל הגט.","שואלים: גט שביטלו, האם הבעל \u0003חוזר ומגרש בו,\u0004 שלא ביטל את הגט לחלוטין, אלא רק את מתן הגט בשעה מסויימת, \u0003או אינו חוזר ומגרש בו,\u0004 שכל הגט הזה בטל? \u0003רב נחמן אמר: חוזר ומגרש בו, ורב ששת אמר:\u0004 \u0003אינו חוזר ומגרש בו.\u0004 ומסכמים: \u0003והלכתא כוותיה\u0004 \u0005[והלכה כשיטתו]\u0006 של \u0003רב נחמן\u0004 שחוזר ומגרש בו.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן\u0006 הוא\u0005]?\u0006 \u0003והא קיימא לן\u0004 \u0005[והרי מוחזק לנו]\u0006 כי \u0003הלכתא כוותיה\u0004 \u0005[הלכה כמו,\u0006 כשיטתו\u0005]\u0006 של \u0003ר' יוחנן,\u0004 ש\u0003אמר: חוזרת.\u0004 שאם נותן אדם לאשה המביעה הסכמה להתקדש לו מעות לשם קידושין ואומר לה שיחולו הקידושין לאחר שלושים יום, בתוך שלושים יום אלו יכולה היא לחזור בה ולומר שאינה רוצה בקידושין. ומכאן שיכול אדם לבטל את דבריו הקודמים על ידי אמירה אחרת כל עוד לא חל הדבר. ואף כאן נאמר, שכיון שהגט לא חל עדיין, כשהוא אומר שהוא בטל — הרי הגט מתבטל מעיקרו!","ודוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]\u0006 בין הדברים?! \u0003התם\u0004 \u0005[שם]\u0006 בענין קידושין, \u0003דיבור ודיבור הוא,\u0004 שקודם אמרה שמסכימה ואחר כך חזרה בה, ואם כן \u0003אתי\u0004 \u0005[בא]\u0006 \u0003דיבור\u0004 אחרון \u0003ומבטל דיבור\u0004 ראשון, \u0003והכא, נהי דבטליה לשליחותא דשליח\u0004 \u0005[וכאן, אם אמנם שביטל את שליחותו של השליח],\u0006 \u0003גיטא גופיה מי קא בטיל\u0004 \u0005[\u0006את \u0005הגט עצמו האם\u0006 גם כן \u0005ביטל]?\u0006 שהרי הגט הוא דבר של ממש, ולכן אי אפשר לומר שמבטלו באמירה בלבד.","שנינו במשנה ש\u0003בראשונה היה עושה\u0004 בית דין במקום אחר ומבטל את הגט. \u0003איתמר\u0004 \u0005[נאמר]:\u0006 \u0003בפני כמה הוא מבטלו,\u0004 בכל מקרה שהוא מבטל גט? \u0003רב נחמן אמר:\u0004 מבטלו \u0003בפני שנים, רב ששת אמר: בפני שלשה.\u0004","ומסבירים את טעמיהם, \u0003רב ששת אמר: בפני שלשה,\u0004 כי \u0003\"בית דין\" קתני\u0004 \u0005[שנה]\u0006 במשנה, ובית דין אינו אלא שלושה. \u0003ורב נחמן אמר: בפני שנים,\u0004 ומדוע? — כי \u0003לבי תרי נמי\u0004 \u0005[לשניים גם כן]\u0006 \u0003\"בית דין\" קרי להו\u0004 \u0005[קוראים להם],\u0006 שבדוחק אפשר לסמוך גם על כך. \u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מניין אני אומר זאת]\u0006 ששניים גם הם קרויים בית דין? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 שבזמן שאדם עושה פרוזבול אומר: \u0003\"מוסרני לפניכם\u0004"],["\u0003פלוני ופלוני הדיינין שבמקום פלוני,\u0004 שכל חוב שיש לי אצל פלוני שאגבנו כל זמן שארצה\u0003\".\u0004 וכיון שהזכיר רק \"פלוני ופלוני הדיינים\" משמע ששניים הם, ובכל זאת הם קרויים דיינים.","\u0003ורב ששת\u0004 טוען כנגד זה: \u0003אטו\u0004 \u0005[וכי]\u0006 ה\u0003תנא כי רוכלא ליחשיב וליזיל\u0004 \u0005[כרוכל ימנה וילך]\u0006 את כל הפרטים? ומה שאמר \"פלוני ופלוני\", משום שרצה להגיד שיש להזכיר את שמות כל הדיינים, אבל לא התכוון להשמיע בכך את מניינם של הדיינים.","\u0003אמר רב נחמן: מנא אמינא לה\u0004 \u0005[מניין אומר אני אותה]\u0006 ששניים אף הם קרויים בית דין? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 לענין פרוזבול: \u0003הדיינים חותמין\u0004 בשטר הפרוזבול \u0003למטה, או העדים. מאי לאו\u0004 \u0005[האם לא]\u0006 נוכל לדייק בלשון המשנה ולומר: \u0003דיינים דומיא\u0004 \u0005[בדומה]\u0006 ל\u0003עדים, מה עדים שנים\u0004 — \u0003אף דיינים נמי\u0004 \u0005[גם כן]\u0006 \u0003שנים? ורב ששת\u0004 טוען לעומת זאת: \u0003מידי איריא\u0004 \u0005[וכי שייכים\u0006 הדברים\u0005]?\u0006 \u0003הא כדאיתא, והא כדאיתא\u0004 \u0005[זה כפי שהוא, וזה כפי שהוא],\u0006 שדיינים הם שלושה דווקא, ועדים שניים.","לגופו של דבר שואלים: \u0003למה ליה למיתנא\u0004 \u0005[לו\u0006 לתנא במשנה \u0005לשנות]\u0006 גם \u0003דיינים,\u0004 ו\u0003למה ליה למיתנא\u0004 \u0005[לו לשנות]\u0006 גם \u0003עדים?\u0004 ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]\u0006 ש\u0003לא שנא\u0004 \u0005[שונה]\u0006 אם \u0003כתוב\u0004 הפרוזבול \u0003בלשון דיינים וחתמי\u0004 \u0005[וחתומים]\u0006 עליו \u0003עדים, ולא שנא\u0004 \u0005[שונה]\u0006 אם \u0003כתוב בלשון עדים וחתמי\u0004 \u0005[וחתומים]\u0006 \u0003דיינים,\u0004 שעיקר הדבר הוא שימסור את הפרוזבול לבית דין, ואין זה משנה באיזה לשון בדיוק נכתב הדבר.","שנינו במשנה שתיקן רבן גמליאל הזקן שלא יבטלו את הגט בבית דין במקום אחר \u0003מפני תיקון העולם.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"מפני תיקון העולם\"? ר' יוחנן אמר: מפני תקנת ממזרים,\u0004 שהרי ייתכן שיבטל הבעל את הגט והאשה לא תדע זאת, ותינשא לאחר (בעודה בעצם נשואה) ותלד ילדים ויהיו אלה ממזרים. \u0003ריש לקיש אמר: מפני תקנת עגונות,\u0004 שמא תחשושנה נשים לאחר שקיבלו גט לידן שאולי ביטל הבעל את הגט, ולא תינשאנה על סמך גט זה, ותישארנה עגונות.","ומסבירים את השיטות: \u0003ר' יוחנן\u0004 ש\u0003אמר\u0004 טעמו \u0003מפני תקנת ממזרים, סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרב נחמן,\u0004 ש\u0003אמר\u0004 שאפשר לבטל אפילו \u0003בפני שנים, ובי תרי לית להו קלא\u0004 \u0005[ושניים אין להם קול],\u0006 כלומר, אין זה מתפרסם ברבים, \u0003ו\u0004כיון שכך, \u0003היא לא שמעה\u0004 \u0005[שומעת]\u0006 \u0003ולא ידעה\u0004 \u0005[יודעת]\u0006 שביטל את הגט, \u0003ואזלה ומינסבא, ואיכא\u0004 \u0005[והולכת ומתחתנת, ויש]\u0006 \u0003ממזרים\u0004 מנישואיה אלה.","\u0003וריש לקיש אמר\u0004 טעמו \u0003מפני תקנת עגונות, סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כרב ששת,\u0004 ש\u0003אמר:\u0004 שמבטלים \u0003בפני שלשה, ובי תלתא אית להו קלא\u0004 \u0005[ושלושה יש להם קול],\u0006 \u0003ושמעה וידעה\u0004 \u0005[ושומעת ויודעת]\u0006 שביטל בעלה את הגט \u0003ולא מינסבא\u0004 \u0005[ואינה מתחתנת]\u0006 ולכן אין מקום לחשש ממזרים, \u0003ו\u0004אולם \u0003תקנת עגונות הוא דאיכא\u0004 \u0005[שיש],\u0006 שלא תישארנה נשים בלי הבעל ובלי גט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אף לאחר שתיקן רבן גמליאל הזקן שלא יבטל אדם את הגט שלא בפני השליח או האשה, אם \u0003בטלו\u0004 בכל זאת — הריהו \u0003מבוטל,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אינו יכול\u0004 \u0003לא לבטלו ו\u0004גם \u0003לא להוסיף על תנאו\u0004 אם היה בגט תנאי כלשהו, \u0003שאם כן, מה כח בית דין יפה\u0004 (מועיל)? והלא בית דין של רבן גמליאל תיקן שלא יבטלו!","ותוהים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003בטל גיטא\u0004 \u0005[הגט],\u0006 \u0003ומשום\u0004 הנימוק של \u0003\"מה כח בית דין יפה\" שרינן\u0004 \u0005[מתירים אנו]\u0006 \u0003אשת איש לעלמא\u0004 \u0005[לכל]?\u0006 שהרי לפי זה למרות שהגט מצד הדין מבוטל, והיא עדיין אשת איש, מכל מקום אין בית דין מכירים בביטול, ומתירים לה להינשא! ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003כל\u0004 ה\u0003מקדש\u0004 אשה — \u0003אדעתא דרבנן\u0004 \u0005[על דעת חכמים]\u0006 הוא \u0003מקדש, ואפקעינהו רבנן לקידושין מיניה\u0004 \u0005[והפקיעו חכמים את הקידושין ממנו]\u0006 במקרה זה שביטל את גיטו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי: תינח דקדיש בכספא\u0004 \u0005[נניח,\u0006 במקרה \u0005שקידש בכסף]\u0006 את אשתו, אפשר לומר שחכמים הפקיעו את הכסף הזה מבעליו, ונמצא שלא היו קידושין מתחילה. אבל אם \u0003קדיש\u0004 \u0005[קידש]\u0006 \u0003בביאה מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 והשיב לו רב אשי: \u0003שויוה רבנן\u0004 \u0005[עשו חכמים]\u0006 את \u0003בעילתו בעילת זנות,\u0004 שהפקיעו מכאן את כוח הקידושין שבדבר, והחשיבו אותה כבעילה של זנות.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אמר\u0004 הבעל \u0003לעשרה\u0004 בני אדם: \u0003\"כתבו גט לאשתי\"\u0004 — \u0003יכול לבטל זה\u0004 (חלק מהם) \u0003שלא בפני זה\u0004 (השאר), שרשאי לומר לחלק מהם אף שלא בפני השאר: \"אל תכתבו\", אלו \u0003דברי רבי.\u0004 \u0003רבן שמעון בן גמליאל אומר: אינו יכול לבטל אלא זה בפני זה,\u0004 כלומר, בפני כולם יחד.","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003ב\u0004הלכה של \u0003עדות שבטלה מקצתה בטלה\u0004 \u0003כולה קמיפלגי\u0004 \u0005[נחלקו],\u0006 \u0003רבי סבר: עדות שבטלה מקצתה\u0004"],["\u0003לא בטלה כולה, ו\u0004משום כך, למרות שביטל הבעל את שליחותם של חלק מהם, \u0003אי אזלי הנך\u0004 \u0005[אם הולכים אלה],\u0006 האחרים שלא ביטל בפניהם, \u0003כתבי ויהבי\u0004 \u0005[\u0006ו\u0005כותבים ונותנים]\u0006 — \u0003ליכתבו וליתבו\u0004 \u0005[שיכתבו ויתנו],\u0006 ואין כל חשש בדבר שהרי שליחותם שלהם לא בטלה. וכיון שהגט שיתנו הם יהיה גט כשר אין צורך בתקנה האומרת שאינו רשאי לבטל אלא בפני כולם.","ואילו \u0003רבן שמעון בן גמליאל סבר: עדות שבטלה מקצתה בטלה כולה, ו\u0004אם יבטל שליחות מקצתם שלא בנוכחות השאר \u0003הנך לא ידעי\u0004 \u0005[אלה,\u0006 האחרים, \u0005אינם יודעים]\u0006 שכבר בטלה שליחותם על ידי שבטלה שליחות מקצתם, \u0003ואזלי וכתבי ויהבי\u0004 \u0005[ו\u0006הם \u0005הולכים וכותבים ונותנים]\u0006 את הגט, \u0003ו\u0004נמצאים \u0003שרו\u0004 \u0005[מתירים]\u0006 \u0003אשת איש לעלמא\u0004 \u0005[לכל]\u0006 שלא כדין.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר את מחלוקתם: \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003עדות שבטלה מקצתה לא בטלה כולה, והכא היינו טעמא\u0004 \u0005[וכאן זהו הטעם]\u0006 של \u0003רבן שמעון בן גמליאל\u0004 שאינו יכול לבטל אלא בפני כולם — \u0003קסבר\u0004 \u0005[סבור הוא]:\u0006 \u0003מלתא דמתעבדא באפי\u0004 \u0005[דבר שנעשה בפני]\u0006 \u0003עשרה\u0004 — \u0003צריכא בי עשרה למישלפה\u0004 \u0005[צריך עשרה\u0006 כדי \u0005לעקור,\u0006 לבטל, \u0005אותו],\u0006 וכיון שציווה על הגט בפני עשרה אינו יכול לבטל בפני מקצתם.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לחכמים השאלה: אמר להם הבעל \u0003\"כולכם\u0004 כתבו גט לאשתי \u0003\",\u0004 שבמקרה זה על כולם להיות חתומים על הגט, \u0003מהו\u0004 הדין לדעת רבן שמעון בן גמליאל? ומסבירים את צדדי השאלה: האם נאמר כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רבן שמעון בן גמליאל\u0004 כשאמר להם הבעל \"כתבו גט\" הוא \u0003משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 \u0003עדות שבטלה מקצתה בטלה כולה\u0004 ויש לחשוש שהשאר לא ידעו על הביטול, \u0003ו\u0004אולם \u0003הני\u0004 \u0005[אלה]\u0006 \u0003כיון\u0004 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 במפורש \u0003\"כולכם\u0004 כתבו לי \u0003\",\u0004 אם כן, האחרים \u0003לא מצו כתבי ויהבי\u0004 \u0005[אינם יכולים לכתוב ולתת]\u0006 בעצמם, ומשום כך יכול הבעל לבטל מקצת העדים שלא בפני השאר, ואין לחשוש למכשול.","\u0003או דלמא טעמא\u0004 \u0005[שמא הטעם]\u0006 של \u0003רבן שמעון בן גמליאל, משום דקסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 \u0003כל מלתא דמתעבדא באפי בי עשרה צריכא בי עשרה למישלפה\u0004 \u0005[כל דבר שנעשה בפני עשרה צריך עשרה\u0006 כדי \u0005לעקור אותו],\u0006 \u0003והילכך\u0004 \u0005[ולכן]\u0006 \u0003אפילו\u0004 אמר \u0003\"כולכם\" נמי\u0004 \u0005[גם כן]\u0006 עליו לבטל את הגט בפני כולם?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בתוספתא, \u0003אמר לשנים: \"תנו גט לאשתי\"\u0004 — \u0003יכול לבטל זה שלא בפני זה,\u0004 אלו \u0003דברי רבי. רבן שמעון בן גמליאל אומר: אינו יכול לבטל אלא זה בפני זה. והא\u0004 \u0005[והרי]\u0006 \u0003שנים דכי\u0004 \u0005[שכמו]\u0006 \u0003\"כולכם\" דמו\u0004 \u0005[נחשבים\u0006 הם\u0005],\u0006 שהרי בפחות משניים אין עדות, ואין חשש שיכתוב ויחתום האחד ללא האחר, \u0003ופליגי\u0004 \u0005[ונחלקו\u0006 בכך\u0005]\u0006 רבי ורבן שמעון בן גמליאל, ומכאן שטעמו של רבן שמעון בן גמליאל משום שאין זה ביטול אם לא נעשה במעמד דומה לזה של המינוי!","\u0003אמר רב אשי: אי\u0004 \u0005[אם]\u0006 היה ברור לנו שמדובר בתוספתא \u0003בעדי כתיבה\u0004 ששניהם צריכים לחתום על הגט — \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 היינו צריכים לפרש ויהיה לנו פתרון לשאלה שנשאלה. ואולם \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003בעדי\u0004 (שליחי) \u0003הולכה,\u0004 ובאלה אין צורך דווקא בשניים, אלא אף באחד, ואם כן יש לומר כי החשש הוא שמא יבטל את שליחותם בפני האחד, והאחר לא ידע מכך וימסור את הגט לאשה.","ומעירים: \u0003הכי נמי מיסתברא\u0004 \u0005[כך גם כן מסתבר]\u0006 לפרש, \u0003דקתני סיפא\u0004 \u0005[ששנה\u0006 ב\u0005סופה]\u0006 של אותה ברייתא: \u0003אמר לזה בפני עצמו ולזה בפני עצמו\u0004 — \u0003יכול לבטל זה שלא בפני זה. אי אמרת בשלמא\u0004 \u0005[נניח אם אתה אומר]\u0006 שמדובר כאן \u0003בעדי הולכה\u0004 — \u0003שפיר\u0004 \u0005[יפה],\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 \u0003בעדי כתיבה, מי מצטרפי\u0004 \u0005[האם\u0006 הם \u0005יכולים להצטרף]\u0006 אם אמר לזה שלא בפני זה? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אמר מר\u0004 \u0005[החכם]:\u0006 \u0003אין עדותן\u0004 של שני עדים \u0003מצטרפת עד שיראו שניהם כאחד!\u0004 את הראיה הזו דוחים: \u0003דלמא\u0004 \u0005[שמא]\u0006 \u0003כר' יהושע בן קרחה סבירא ליה\u0004 \u0005[סבור הוא]\u0006 ולדעתו אפילו אין רואים שניהם כאחד הרי זו עדות.","\u0003אמר רב שמואל בר יהודה: שמעית מיניה\u0004 \u0005[שמעתי ממנו]\u0006 מ\u0003ר' אבא תרתי\u0004 \u0005[שתי\u0006 הלכות\u0005],\u0006 \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כרבי, וחדא\u0004 \u0005[ואחת]\u0006 \u0003כרבן שמעון בן גמליאל, ולא ידענא הי\u0004 \u0005[ואין אני יודע איזו]\u0006 \u0003כרבי והי\u0004 \u0005[ואיזו]\u0006 \u0003כרבן שמעון בן גמליאל.\u0004","\u0003אמר רב יוסף: ניחזי אנן\u0004 \u0005[נראה אנו]\u0006 לפי המקורות שבידינו למה היתה הכוונה. \u0003דכי אתא\u0004 \u0005[שכאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל, \u0003אמר: מעשה ועשה רבי כדברי חכמים, אמר לפניו ר' פרטא בנו של ר' אלעזר בן פרטא בן בנו של ר' פרטא הגדול: אם כן, מה כח בית דין יפה? וחזר רבי ועשה כרבן שמעון בן גמליאל.\u0004","\u0003ומדהא\u0004 \u0005[ומכיון שזו]\u0006 \u0003כרבן שמעון בן גמליאל,\u0004 שהרי רואים שחזר בו רבי, והלכה כרבן שמעון בן גמליאל בענין \"מה כוח בית דין יפה\", ולפיכך אם ביטל גט שלא בפני השליח — אינו מבוטל, אם כן, \u0003הך\u0004 \u0005[זו\u0006 האחרת\u0005]\u0006 בענין האומר לעשרה, מן הסתם נפסקה אף היא \u0003כרבי.\u0004","ומעירים: \u0003ואף ר' יאשיה\u0004 ש\u0003מן\u0004 העיר \u0003אושא סבר\u0004 \u0005[סבור]:\u0006 בהלכה \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כרבי וחדא\u0004 \u0005[ואחת]\u0006 \u0003כרבן שמעון בן גמליאל.\u0004 ש\u0003אמר רבה בר בר חנה: חמשה סבי\u0004 \u0005[זקנים,\u0006 תלמידי חכמים\u0005]\u0006 \u0003הוינן קמיה\u0004 \u0005[היינו,\u0006 ישבנו \u0005לפני]\u0006 \u0003ר' יאשיה\u0004 ש\u0003מן\u0004 העיר \u0003אושא, אתא ההוא גברא קמיה\u0004 \u0005[בא אדם אחד לפניו]\u0006 \u0003ואשקליה גיטא על כורחיה\u0004 \u0005[ונתן לו,\u0006 הכריח אותו לתת \u0005גט בעל כרחו],\u0006 \u0003אמר לן\u0004 \u0005[לנו]\u0006 ר' יאשיה: \u0003זילו אטמורו\u0004 \u0005[לכו התחבאו]\u0006 \u0003וכתבו לה\u0004 גט, כדי שלא יוכל לראות אתכם ולבטל את הגט לאחר שנכתב.","\u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 \u0003כ\u0004שיטת \u0003רבי\u0004 שאם ביטל הבעל את הגט שלא בפני שליח — מבוטל, \u0003כי מיטמרי מאי הוי\u0004 \u0005[כאשר מתחבאים מה קורה]?\u0006 הרי עדיין הוא יכול לבטל בפני אחרים! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003כרבן שמעון בן גמליאל סבירא ליה\u0004 \u0005[סבור הוא].\u0006","ומוסיפים: \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שב\u0003אידך\u0004 \u0005[\u0006ההלכה \u0005האחרת]\u0006 באומר לעשרה \"כתבו\", \u0003נמי\u0004 \u0005[גם כן]\u0006 הוא סבור \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל, למה להו אטמורי\u0004 \u0005[להם להתחבא]?\u0006 \u0003ליבדרו איבדורי\u0004 \u0005[שיתפזרו]\u0006 ולא ימצא הבעל את כולם יחד, וממילא לא יוכל לבטל! \u0003אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שהוא סבור כי \u0003חדא\u0004 \u0005[אחת]\u0006 \u0003כ\u0004דעת \u0003רבי, וחדא\u0004 \u0005[ואחת]\u0006 \u0003כ\u0004דעת \u0003רבן שמעון בן גמליאל.\u0004 זו שיטה אחת.","\u0003ורבא אמר\u0004 בשם \u0003רב נחמן: הלכה כ\u0004שיטת \u0003רבי בשתיהן.\u0004 ושואלים: לפי זה, \u0003ו\u0004כי \u0003לית ליה\u0004 \u0005[אין לו],\u0006 האם אין מקבל \u0003רב נחמן\u0004 את הנימוק של \u0003מה כח בית דין יפה, והאמר\u0004 \u0005[והרי\u0006 \u0005אמר]\u0006 \u0003רב נחמן אמר שמואל:\u0004"],["\u0003יתומין\u0004 קטנים \u0003שבאו לחלוק בנכסי אביהן\u0004 שהוריש להם, \u0003בית דין מעמידין להן,\u0004 לכל אחד, \u0003אפוטרופוס, ובוררים להן\u0004 האפוטרופסים \u0003חלק יפה\u0004 לכל אחד ואחד, וכאשר \u0003הגדילו\u0004 (גדלו ובגרו) היתומים — \u0003יכולין למחות\u0004 ולומר שלא היתה החלוקה כראוי, ולבטלה. \u0003ורב נחמן דידיה\u0004 \u0005[עצמו]\u0006 \u0003אמר\u0004 בניגוד לדברי שמואל: אם \u0003הגדילו\u0004 — \u0003אין יכולין למחות.\u0004 ש\u0003אם כן,\u0004 שאתה אומר שיכולים למחות \u0003מה כח בית דין יפה?\u0004 משמע שהוא מקבל נימוק זה של מה כח בית דין יפה!","ומשיבים: אין זו סתירה, \u0003התם\u0004 \u0005[שם]\u0006 לגבי היתומים הרי זה ענין של \u0003ממונא\u0004 \u0005[ממון],\u0006 שיש מקום לעמוד על כבוד בית דין בענין זה, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 בגיטין הרי זה ענין של \u0003איסורא\u0004 \u0005[איסור]\u0006 ולא יתירו אשת איש רק משום טעם זה.","מסופר: איש אחד ששמו \u0003גידול בר רעילאי שדר\u0004 \u0005[שלח]\u0006 \u0003לה גיטא לדביתהו\u0004 \u0005[גט לאשתו],\u0006 \u0003אזל שליחא אשכחה דהוה יתבה ונוולה\u0004 \u0005[הלך השליח מצא אותה שהיתה יושבת ואורגת],\u0006 \u0003אמר לה: הא\u0004 \u0005[הרי]\u0006 \u0003גיטיך. אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003זיל השתא מיהא ותא\u0004 \u0005[לך עכשיו מכאן ובוא]\u0006 \u0003למחר\u0004 ואז תתן לי את הגט. \u0003אזל לגביה\u0004 \u0005[הלך אליו]\u0006 השליח אל גידול בר רעילאי \u0003ואמר ליה\u0004 \u0005[לו]\u0006 מה שאירע. \u0003פתח\u0004 גידול בר רעילאי \u0003ואמר: \"ברוך הטוב והמטיב\",\u0004 ששמח שגט זה לא ניתן.","ונחלקו בדינו של גט זה, \u0003אביי אמר:\u0004 אמנם אמר \u0003\"ברוך הטוב והמטיב\",\u0004 ששמח שלא ניתן, \u0003ו\u0004אולם \u0003לא בטל\u0004 על ידי כך \u0003גיטא\u0004 \u0005[הגט].\u0006 \u0003רבא אמר:\u0004 אמר \u0003\"ברוך הטוב והמטיב\", ובטל גיטא\u0004 \u0005[הגט].\u0006","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון \u0005נחלקו]?\u0006 ומשיבים: \u0003בגלוי דעתא בגיטא קמיפלגי\u0004 \u0005[בגילוי דעת בגט נחלקו],\u0006 כלומר, כשמגלה הבעל דעתו שאין רצונו בגט, אבל לא אמר במפורש שהוא מבטל אותו, האם הדבר הזה מועיל כדי לבטל את הגט או לא. ש\u0003אביי סבר\u0004 \u0005[סבור]:\u0006 \u0003גלוי דעתא בגיטא לאו מלתא היא\u0004 \u0005[גילוי דעת בגט לא כלום הוא]\u0006 ואינו נחשב, \u0003ורבא סבר\u0004 \u0005[סבור]:\u0006 \u0003גלוי דעתא בגיטא מילתא היא\u0004 \u0005[גילוי דעת בגט דבר הוא]\u0006 וחוששים לו.","\u0003אמר רבא: מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה]\u0006 את הלכה זו? ש\u0003רב ששת אשקליה גיטא לההוא גברא בעל כרחיה\u0004 \u0005[נטל גט מאדם אחד בעל כורחו]\u0006 על מנת לתיתו לאשתו של הלה. \u0003ו\u0004מה עשה אותו אדם — \u0003אמר להו לסהדי\u0004 \u0005[להם לעדים]:\u0006 \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר,\u0004 הורה, \u0003לכו\u0004 \u0005[לכם]\u0006 \u0003רב ששת: לבטל גיטא\u0004 \u0005[שיתבטל הגט],\u0006 \u0003ואצרכיה\u0004 \u0005[והצריכו]\u0006 \u0003רב ששת\u0004 לכתוב \u0003גיטא אחרינא\u0004 \u0005[גט אחר].\u0006 משמע שמכיון שגילה את דעתו שאין רצונו בגט, אף שלא אמר שהוא עצמו מבטל את הגט, אלא שרב ששת הורה כן — הרי הוא בטל.","\u0003ואביי\u0004 משיב על כך: \u0003אטו\u0004 \u0005[וכי]\u0006 \u0003רב ששת מבטל גיטא דאינשי הוה\u0004 \u0005[גיטי אנשים היה]?\u0006 אלא האמת היא ש\u0003איהו בטלה\u0004 \u0005[הוא\u0006 עצמו, הבעל, \u0005ביטלו]\u0006 את הגט, \u0003והאי דקאמר להו הכי\u0004 \u0005[וזה שאמר להם כך]\u0006 בלשון זו \u0003משום דפנוי\u0004 \u0005[מכות]\u0006 ששמשי בית דין של רב ששת היו מכים אותו אם היה עושה שלא כדברי הדיין.","\u0003ואמר אביי: מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה],\u0006 את דעתי, שגילוי דעת בגט אין בו ממש? ש\u0003רב יהודה אשקליה גיטא לחתניה\u0004 \u0005[נטלו,\u0006 הכריחו לתת \u0005גט לחתנו]\u0006 של \u0003ר' ירמיה ביראה\u0004 \u0005[מבירי]\u0006 \u0003ובטליה\u0004 \u0005[וביטל אותו]\u0006 האיש את הגט, \u0003תנא אשקליה ובטליה\u0004 \u0005[חזר,\u0006 רב יהודה \u0005נטל ממנו וביטלו]\u0006 הלה, \u0003הדר תנא ואשקליה על כרחיה\u0004 \u0005[חזר\u0006 רב יהודה, \u0005שנה ונטל ממנו\u0006 גט \u0005בעל כורחו],\u0006 \u0003ואמר להו לסהדי\u0004 \u0005[להם לעדים]\u0006 באותה שעה: \u0003אותיבו קרי באוניכו וכתובו ליה\u0004 \u0005[שימו\u0006 חתיכות \u0005דלעת באוזניכם וכיתבו לו]\u0006 גט, שלא תוכלו לשמוע אם יאמר לכם שהוא מבטל. \u0003ואי סלקא דעתך גלוי דעתא בגיטא מילתא היא\u0004 \u0005[ואם עולה על דעתך\u0006 לומר ש\u0005גילוי דעת בגט דבר הוא],\u0006 \u0003הא חזו ליה דקא רהיט בתרייהו\u0004 \u0005[הרי\u0006 העדים \u0005רואים אותו ש\u0006הוא \u0005רץ אחריהם]\u0006 ואף שאינם שומעים את קולו הם יכולים להבין שרצונו לבטל!","\u0003ורבא\u0004 משיב על כך: כיון שאינם שומעים — אין זה גילוי דעת, כי \u0003האי דקא רהיט בתרייהו\u0004 \u0005[זה ש\u0006הוא \u0005רץ אחריהם]\u0006 אינו ראיה, שהרי יכול להיות \u0003דאמר להו\u0004 \u0005[ש\u0006הוא רוצה \u0005לומר להם]:\u0006 \u0003אשור הבו לה הייא\u0004 \u0005[מהרו התחזקו\u0006 ו\u0005תנו לה\u0006 את הגט \u0005במהרה],\u0006 \u0003כי היכא דמשלם צערא דההוא גברא\u0004 \u0005[כדי שיגמר\u0006 כבר \u0005צערו של אותו אדם],\u0006 כלומר, צערי, בזה שאשתי מתגרשת ממני.","\u0003ואמר אביי\u0004 עוד: \u0003מנא אמינא לה\u0004 \u0005[מניין אני אומר אותה],\u0006 את ההלכה שגילוי דעת בגט אין בו ממש? \u0003דההוא\u0004 \u0005[ש\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לעדים כאשר נתן גט על מנת לתיתו לאחר זמן: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא אתינא\u0004 \u0005[אבוא]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 \u0003ליהוי גיטא\u0004 \u0005[יהא\u0006 זה \u0005גט],\u0006 \u0003אתא ופסקיה מברא\u0004 \u0005[בא והפסיקתו המעבורת]\u0006 ולא יכול היה לעבור את הנהר ולהגיע למקום, \u0003אמר להו\u0004 \u0005[להם],\u0006 לעומדים מעבר הנהר: \u0003\"חזו דאתאי, חזו דאתאי\"\u0004 \u0005[ראו שבאתי, ראו שבאתי],\u0006 \u0003ואמר שמואל: לא שמיה מתיא\u0004 \u0005[אין שמו,\u0006 אינו נחשב \u0005ביאה].\u0006 משמע שאף על פי שהוא מגלה דעתו, מכל מקום הגט נשאר בעינו.","\u0003ורבא\u0004 אמר: מכאן אין ראיה, \u0003אטו התם לבטולי גיטא בעי\u0004 \u0005[וכי שם לבטל את הגט רצה]?\u0006 \u0003התם, לקיומי תנאיה קא בעי\u0004 \u0005[שם, לקיים\u0006 את \u0005תנאו רצה]\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא איקיים תנאיה\u0004 \u0005[התקיים תנאו].\u0006","מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 כאשר נתן גט לארוסתו: \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא נסיבנא\u0004 \u0005[אשא\u0006 אותך לאשה\u0005]\u0006 \u0003עד תלתין יומין\u0004 \u0005[שלושים יום]\u0006 — \u0003ליהוי גיטא\u0004 \u0005[יהא\u0006 זה \u0005גט].\u0006 \u0003כי מטו תלתין יומין\u0004 \u0005[כאשר הגיעו שלושים יום],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הא טרחנא\u0004 \u0005[הרי טרחתי]\u0006 ולא הצלחתי.","ושואלים: \u0003למאי ניחוש לה\u0004 \u0005[למה נחשוש לו]\u0006 לגט זה? \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום אונסא\u0004 \u0005[אונס ]\u0006 שבדבר, שהרי טרח ונאנס ולא עלה בידו — הלא כלל הוא ש\u0003אין\u0004 טענת \u0003אונס בגיטין. אי\u0004 \u0005[אם]\u0006 \u0003משום גלויי דעתא בגיטא\u0004 \u0005[גילוי הדעת בגט]\u0006 שגילה דעתו שאינו רוצה בגט הזה, אם כן \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003אביי ורבא הוא,\u0004 וכמבואר להלן — בזה הלכה כאביי.","וכן מסופר: \u0003ההוא\u0004 \u0005[\u0006אדם \u0005אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא נסיבנא\u0004 \u0005[אשא\u0006 לאשה\u0005]\u0006 את ארוסתי \u0003לריש ירחא דאדר, ליהוי גיטא\u0004 \u0005[עד ראש חודש אדר, שיהא זה גט].,\u0006 \u0003כי מטא ריש ירחא דאדר\u0004 \u0005[כאשר הגיע ראש חודש אדר],\u0006 \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003אנא לריש ירחא דניסן אמרי\u0004 \u0005[אני לראש חודש ניסן אמרתי].\u0006 ומעתה, \u0003למאי ניחוש\u0004 \u0005[למה נחשוש]\u0006 \u0003לה? אי\u0004 \u0005[אם]\u0006 \u0003משום אונס\u0004 שהיה בזה — \u0003אין אונס בגיטין. אי\u0004 \u0005[אם]\u0006 \u0003משום גלויי דעתא\u0004 \u0005[הדעת]\u0006 — \u0003פלוגתא\u0004 \u0005[מחלוקת]\u0006 של \u0003אביי ורבא,\u0004 והלכה כאביי.","ומסכמים את ההלכה: \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004רב \u0003נחמן,\u0004 שאמר שביטול גט יכול להתבצע אפילו בפני שנים. \u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כ\u0004רב \u0003נחמן,\u0004 שאמר שהלכה כרבי בשתיהם."],["\u0003והלכתא\u0004 \u0005[והלכה]\u0006 \u0003כנחמני\u0004 (אביי) שגילוי דעת בגט אינו נחשב.","\u0003בראשונה היה משנה\u0004 את \u0003שמו ושמה, שם עירו ושם עירה\u0004 ולא היו מדקדקים לכתוב בגט את כל השמות של הבעל והאשה, אלא כפי שהיו נוהגים לקרוא להם במקום כתיבת הגט. \u0003התקין רבן גמליאל הזקן שיהא\u0004 הסופר \u0003כותב\u0004 בגט: \u0003\"איש פלוני וכל שום\u0004 (שם) \u0003שיש לו\", \"אשה פלונית וכל שום\u0004 (שם) \u0003שיש לה\", מפני תיקון העולם,\u0004 שמא במקום אחר אין מכירים את השם שנכתב בגט, ויבואו להוציא לעז על הגט שאינו שלה.","\u0003אמר רב יהודה אמר שמואל: שלחו ליה\u0004 \u0005[לו]\u0006 \u0003בני מדינת הים לרבן גמליאל\u0004 שאלה זו: \u0003בני אדם הבאים משם,\u0004 מארץ ישראל \u0003לכאן,\u0004 לארץ ישראל \u0003שמו יוסף\u0004 — \u0003וקוראין לו יוחנן,\u0004 או ששמו \u0003יוחנן\u0004 — \u0003וקוראין לו יוסף, היאך מגרשין נשותיהן? עמד רבן גמליאל והתקין שיהו כותבין: \"איש פלוני וכל שום\u0004 (שם) \u0003שיש לו\", \"אשה פלונית וכל שום\u0004 (שם) \u0003שיש לה\", מפני תיקון העולם. אמר רב אשי: והוא דאתחזק בתרי שמי\u0004 \u0005[שהוחזק בשני שמות],\u0006 כלומר, שידוע לנו שיש לו שם נוסף. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב אשי: ר' מרי ור' אלעזר קיימי כוותך\u0004 \u0005[עומדים בשיטתך].\u0006","ומוסיפים: וכן \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אשי: היו לו שתי נשים\u0004 — \u0003אחת ביהודה ואחת בגליל, ולו שני שמות\u0004 — \u0003אחד ביהודה ואחד בגליל, וגרש את אשתו שביהודה בשמו שביהודה, ואת אשתו שבגליל בשמו שבגליל\u0004 — \u0003אינה מגורשת, עד שיגרש את אשתו שביהודה בשמו שביהודה\u0004 ויוסיף שם של ה\u0003גליל עמו, ואת אשתו שבגליל בשמו שבגליל ושם\u0004 של \u0003יהודה עמו.\u0004 ואם \u0003יצא למקום אחר וגרש באחד מהן\u0004 משני השמות הללו — \u0003מגורשת.\u0004","ויש לשאול: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 שגם ביהודה צריך להוסיף \u0003שם\u0004 של \u0003גליל עמו! אלא שמע מינה\u0004 \u0005[למד מכאן]\u0006 שיש להבדיל; \u0003הא דאתחזק\u0004 \u0005[זה שהוחזק]\u0006 בשני שמות, כגון ביהודה שהיו יודעים שיש לו עוד שם אחד בגליל, \u0003הא\u0004 \u0005[זה]\u0006 ש\u0003לא אתחזק\u0004 \u0005[הוחזק]\u0006 בשני שמות, כגון אם הלך למקום אחר שאין מכירים אותו — אינו צריך לכתוב אלא אחד מן השמות, ובמקום שמכירים אותו בשם אחד — בשם הידוע באותו מקום. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","מסופר: \u0003ההיא דהוו קרו\u0004 \u0005[\u0006אשה \u0005אחת שהיו קוראים]\u0006 \u0003לה מרים, ופורתא\u0004 \u0005[ומקצת]\u0006 היו קוראים לה \u0003שרה, אמרי נהרדעי\u0004 \u0005[אמרו חכמי נהרדעא]:\u0006 צריכים לכתוב לה בגט \u0003מרים וכל שום\u0004 (שם) \u0003שיש לה, ולא\u0004 יכתוב \u0003שרה וכל שום שיש לה,\u0004 שהולכים אחרי השם העיקרי שלה.","\u0003אין אלמנה נפרעת\u0004 כתובתה \u0003מנכסי יתומים אלא בשבועה,\u0004 שצריכה להישבע שלא קיבלה כבר משהו מן הכתובה בחיי בעלה. מסופר: \u0003נמנעו מלהשביעה\u0004 והיתה האשה מפסידה, שלא יכלה לקבל את כתובתה, \u0003התקין רבן גמליאל הזקן שתהא נודרת ליתומים כל מה שירצו,\u0004 שהיו מטילים עליה נדר חמור (כגון שלא תאכל פירות כלל) אם קיבלה דבר מן הכתובה, \u0003וגובה\u0004 לאחר מכן את \u0003כתובתה.\u0004","\u0003העדים חותמין על הגט מפני תיקון העולם,\u0004 אף על פי שאין הדבר הזה מעכב לגבי הגט. \u0003והלל התקין פרוזבול מפני תיקון העולם\u0004 כאשר יבואר בגמרא.","שואלים: \u0003מאי איריא\u0004 \u0005[מה שייך],\u0006 מדוע שנה דין זה דווקא לגבי \u0003אלמנה? אפילו כולי עלמא נמי\u0004 \u0005[כל העולם,\u0006 כל אדם, \u0005גם כן]\u0006 צריך להישבע ליתומים, \u0003דהא קיימא לן\u0004 \u0005[שהרי מוחזק בידינו]\u0006 שכל \u0003הבא ליפרע מנכסי יתומין\u0004 שירשו מאביהם, את חוב אביהם \u0003לא יפרע אלא בשבועה!\u0004 ומשיבים: \u0003אלמנה אצטריכא ליה\u0004 \u0005[הוצרך לו\u0006 לומר\u0005],\u0006 שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006"],["\u0003משום חינא\u0004 \u0005[חן]\u0006 \u0003אקילו רבנן גבה\u0004 \u0005[הקילו חכמים אצלה],\u0006 שתיקנו כמה תקנות לגבי כתובה לטובת הנשים כדי להוסיף בכך חן לנשים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שלא כן בענין זה.","שנינו במשנה ש\u0003נמנעו מלהשביעה,\u0004 את האלמנה. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 נמנעו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 מה שאמר \u0003רב כהנא,\u0004 ש\u0003אמר רב כהנא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב יהודה אמר רב:\u0004 \u0003מעשה באדם אחד בשני\u0004 (בשנות) \u0003בצורת שהפקיד דינר זהב אצל אלמנה, והניחתו\u0004 את הדינר \u0003בכד של קמח, ו\u0004בטעות \u0003אפאתו בפת\u0004 עם הקמח, \u0003ונתנתו,\u0004 את הפת, \u0003לעני\u0004 בצדקה,","\u0003לימים בא בעל הדינר ואמר לה: הבי לי דינרי, אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003יהנה\u0004 (יועיל, יפעל) \u0003סם המות באחד מבניה של אותה אשה\u0004 (כלומר, שלה) \u0003אם נהניתי מדינרך כלום! אמרו: לא היו\u0004 (עברו) \u0003ימים מועטין עד שמת אחד מבניה, וכששמעו חכמים בדבר, אמרו: מה מי שנשבע באמת\u0004 — \u0003כך\u0004 נענש על טעותו, \u0003הנשבע על שקר\u0004 — \u0003על אחת כמה וכמה.\u0004","ושואלים תחילה לגופו של דבר: \u0003מאי טעמא איענשה\u0004 \u0005[מה טעם\u0006 באמת \u0005נענשה]\u0006 הלא נשבעה באמת ולא נהנתה מן הדינר? ומשיבים: \u0003דאישתרשי\u0004 \u0005[שהרוויחה]\u0006 \u0003לה מקום דינר,\u0004 שהרי במקום שתפס הדינר בעיסה לא נתנה קמח, ונמצא שבכל זאת היתה לה הנאה כלשהי מדינר זה.","ושואלים: \u0003ו\u0004אם כך הדבר, שנהנתה מדינר זה, \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"מי שנשבע באמת\"?\u0004 והרי נתברר שדבריה אינם נכונים! ומשיבים: הכוונה היא \u0003כמי שנשבע באמת,\u0004 שהרי כוונתה היתה לומר אמת. ומכל מקום בגלל טעות קלה — נענשה האשה עד כדי כך. ואפשר להבין מתוך מעשה זה שמפני שחששו שמא אף בגלל טעות יכול אדם להיענש כל כך על שבועתו, לכן אמרו במשנה שנמנעו מלהשביע את האלמנה.","ואולם, \u0003אי\u0004 \u0005[אם]\u0006 \u0003משום הא\u0004 \u0005[\u0006סיבה \u0005זו],\u0006 \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 \u0003אלמנה? אפילו גרושה נמי\u0004 \u0005[גם כן]\u0006 לא תישבע, \u0003אלמה\u0004 \u0005[מפני מה]\u0006 \u0003אמר ר' זירא אמר שמואל: לא שנו אלא אלמנה, אבל גרושה משביעין אותה!\u0004 ואם כן, מדוע לא יחששו גם בה?","ומשיבים: \u0003אלמנה שאני\u0004 \u0005[שונה]\u0006 שחוששים אצלה יותר לשבועת שקר, ומדוע? — \u0003דבההיא\u0004 \u0005[שבאותה]\u0006 \u0003הנאה דקא טרחה קמי דיתמי\u0004 \u0005[ש\u0006היא \u0005טורחת לפני היתומים]\u0006 שאין להם אב ומטפל, והיא עושה זאת במקומו, \u0003אתיא לאורויי היתרא\u0004 \u0005[באה להורות היתר\u0006 לעצמה\u0005]\u0006 במה שלקחה ונהנתה קצת מן הדברים, ויש חשש שתישבע לשקר, שתחשוב שמה שלקחה כבר החזירה ליתומים באופן אחר.","\u0003אמר רב יהודה אמר ר' ירמיה בר אבא: רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003לא שנו\u0004 שאין משביעים את האלמנה \u0003אלא בבית דין\u0004 שנשבעים בו שבועה חמורה, ומחזיק הנשבע חפץ של קדושה בידו ונשבע בשם ה', \u0003אבל חוץ לבית דין\u0004 שאין זו דרך השבועה — \u0003משביעין אותה.\u0004 ושואלים: \u0003איני\u0004 \u0005[\u0006האמנם \u0005כך הוא]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב לא מגבי\u0004 \u0005[\u0006היה \u0005מגבה]\u0006 \u0003כתובה לארמלתא\u0004 \u0005[לאלמנה]\u0006 משום שנמנע מלהשביעה, ומשמע שלא השביעוה אף מחוץ לבית דין! ומשיבים: אכן \u0003קשיא\u0004 \u0005[קשה].\u0006","\u0003ב\u0004עיר \u0003סורא מתנו הכי\u0004 \u0005[היו שונים כך]\u0006 שכך היא דעת רב ושמואל. ואולם \u0003ב\u0004עיר \u0003נהרדעא מתנו הכי\u0004 \u0005[היו שונים כך],\u0006 \u0003אמר רב יהודה אמר שמואל: לא שנו אלא בבית דין,\u0004 \u0003אבל חוץ לבית דין\u0004 — \u0003משביעין אותה. ורב אמר: אפילו חוץ לבית דין נמי\u0004 \u0005[גם כן]\u0006 \u0003אין משביעין אותה.\u0004","ומסבירים: \u0003רב\u0004 הולך \u0003לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005],\u0006 שכן \u0003רב לא מגבי\u0004 \u0005[היה מגבה]\u0006 כלל \u0003כתובה לארמלתא\u0004 \u0005[לאלמנה].\u0006 ושואלים: \u0003וליאדרה\u0004 \u0005[ושידיר אותה]\u0006 את האלמנה במקום שבועה \u0003וליגבייה\u0004 \u0005[ושיגבה אותה],\u0006 את הכתובה, כפי שאמרו במשנה שתהיה נודרת ליתומים במקום שבועה! ומשיבים: \u0003בשני\u0004 \u0005[בשנותיו,\u0006 בזמנו\u0005]\u0006 של \u0003רב קילי נדרי\u0004 \u0005[היו קלים הנדרים]\u0006 בעיני הבריות, ורב חשש שמתוך הזלזול בנדרים עלולות הנשים לנדור נדרי שווא, ונמצאות הן עוברות על איסור והיתומים מפסידים את המגיע להם.","מסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת\u0006 אלמנה \u0005שבאה לפני]\u0006 \u0003רב הונא\u0004 וביקשה להיפרע כתובתה מהיתומים, \u0003אמר לה: מה אעביד ליך\u0004 \u0005[אעשה לך],\u0006 שכן \u0003רב לא מגבי\u0004 \u0005[היה מגבה]\u0006 \u0003כתובה לארמלתא\u0004 \u0005[לאלמנה].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]\u0006 האלמנה: \u0003מידי הוא טעמא\u0004 \u0005[מהו הטעם]\u0006 שלא להגבות כתובה — \u0003אלא דלמא נקיטנא מידי\u0004 \u0005[שמא לקחתי משהו]\u0006 \u0003מכתובתי,\u0004 נשבעת אני \u0003חי ה' צבאות אם\u0004 (שלא) \u0003נהניתי מכתובתי כלום! אמר רב הונא: מודה רב בקופצת\u0004 ונשבעת, שאף על פי שאמרו שלא תישבע לכתחילה, מכל מקום אם נשבעה סומכים על כך ותגבה כתובתה.","ועוד מסופר: \u0003ההיא דאתאי לקמיה\u0004 \u0005[\u0006אשה \u0005אחת\u0006 אלמנה \u0005שבאה לפני]\u0006 \u0003רבה בר רב הונא\u0004 לתבוע כתובתה, \u0003אמר לה: מאי אעביד ליך\u0004 \u0005[מה אעשה לך],\u0006 שכן \u0003רב לא מגבי\u0004 \u0005[היה מגבה]\u0006 \u0003כתובה לארמלתא\u0004 \u0005[לאלמנה],\u0006 \u0003ואבא מרי\u0004 \u0005[ואבי מורי]\u0006 \u0003לא מגבי\u0004 \u0005[היה מגבה]\u0006 \u0003כתובה לארמלתא\u0004 \u0005[לאלמנה].\u0006","\u0003אמרה ליה\u0004 \u0005[לו]:\u0006 אם כן \u0003הב\u0004 \u0005[תן]\u0006 \u0003לי מזוני\u0004 \u0005[מזונות]\u0006 שאוכל מנכסי בעלי כל עוד איני נישאת לאחר. \u0003אמר לה: מזוני נמי לית ליך\u0004 \u0005[מזונות גם כן אין לך],\u0006 שכן \u0003אמר רב יהודה אמר שמואל: התובעת כתובתה בבית דין\u0004 — \u0003אין לה מזונות\u0004 מאותה שעה, שלא הבטיח לה הבעל מזונות בזמן אלמנותה אלא כל זמן שהיא נמנעת מלהינשא לאחר. וכיון שתובעת כתובתה — משמע שרוצה עכשיו להינשא.","כעסה האשה ו\u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אפכוה לכורסיה\u0004 \u0005[שיתהפך כסאו]\u0006\u0005,\u0006 כלומר, שירד מגדולתו, \u0003כבי תרי עבדא\u0004 \u0005[כשתי\u0006 דעות חלוקות הוא \u0005עושה]\u0006 \u0003לי!\u0004 ומפני שחשש רבה בר רב הונא מן הקללה, \u0003הפכוה לכורסיה\u0004 \u0005[הפכו\u0006 בפועל \u0005את הכסא]\u0006 על פניו \u0003ותרצוה\u0004 \u0005[והעמידו אותו]\u0006 כדי שתתקיים הקללה בכך באופן מילולי, \u0003ואפילו הכי\u0004 \u0005[כך]\u0006 \u0003לא איפרק מחולשא\u0004 \u0005[ניצל מחולשה,\u0006 מחולי\u0005]\u0006 בגלל קללה זו.","באותו ענין מסופר: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יהודה\u0004 תלמידו של שמואל, \u0003לרב ירמיה ביראה\u0004 \u0005[מבירי]:\u0006 במקרה שבאה אלמנה, \u0003אדרה\u0004 \u0005[הטל עליה נדר]\u0006 \u0003בבית דין, ואשבעה\u0004 \u0005[והשבע אותה]\u0006 \u0003חוץ לבית דין, וליתי קלא וליפול באודני\u0004 \u0005[ושיבוא הקול ושיפול באוזניי]\u0006 שאני רוצה לשמוע שנעשה הדבר, \u0003דבעינא כי היכי דאעביד בה\u0004 \u0005[שאני רוצה שאעשה בזה]\u0006 \u0003מעשה\u0004 להגבות כתובה לאלמנה, ולהוציא מדברי תלמידי רב שאין מגבים כלל כתובה לאלמנה.","\u0003גופא\u0004 \u0005[לגופה]\u0006 של ההלכה ששנינו במשנתנו שאין משביעים בבית דין אלמנה שבאה לגבות כתובתה מיתומים, \u0003אמר ר' זירא אמר שמואל: לא שנו אלא אלמנה, אבל גרושה\u0004 — \u0003משביעין אותה.\u0004","ושואלים: \u0003ו\u0004אם כן יוצא ש\u0003גרושה דאדרה\u0004 \u0005[ש\u0006רק \u0005הדירו אותה\u0006 בנדר\u0005]\u0006 ולא השביעוה \u0003לא\u0004 מועיל הדבר, ואינה גובה כתובה על סמך הנדר? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003שלחו מתם\u0004 \u0005[משם,\u0006 מארץ ישראל\u0005]\u0006 מכתב זה של פסק דין: \u0003\"איך פלוניתא\u0004 \u0005[פלונית]\u0006 \u0003בת פלוני קבילת גיטא מן ידא\u0004 \u0005[קיבלה גט מידו]\u0006 של \u0003אחא בר הידיא דמתקרי\u0004 \u0005[שנקרא]\u0006 \u0003\"איה מרי\", ונדרת ואסרת\u0004 \u0005[ונדרה ואסרה]\u0006 \u0003פירות שבעולם עלה\u0004 \u0005[עליה]\u0006 אם \u0003לא קבילת\u0004 \u0005[קיבלה]\u0006 \u0003מכתובתה אלא גלופקרא\u0004 (מעיל) \u0003אחד, וספר תהלים אחד, וספר איוב, וממשלות\u0004 (ספר משלי) שהיו \u0003בלואים,\u0004"],["\u0003ושמנום\u0004 (והערכנו אותם), את כל הדברים שקיבלה \u0003ב\u0004שווי \u0003חמשה מנה, לכשתבא לידכם\u0004 עם פסק זה \u0003הגבוה את השאר\u0004 שבחוב הכתובה מנכסי בעלה שבבבל \u0003\".\u0004 ומכאן משמע שאף בגרושה די בנדר! \u0003אמר רב אשי: ההוא\u0004 \u0005[אותו\u0006 גט\u0005],\u0006 \u0003גט יבמין הוה\u0004 \u0005[\u0006של \u0005יבם היה]\u0006 שנתן לה היבם לאחר שהתאלמנה מאחיו, בעלה הראשון, ולא היה זה גט רגיל, וכתובה זו שבאה לגבות מנכסי בעלה הראשון היתה, ולכן לא השביעוה והדירוה ככל אלמנה.","שנינו במשנה: \u0003התקין רבן גמליאל הזקן שתהא\u0004 האלמנה \u0003נודרת\u0004 בכל דבר שידרשו היתומים, ותקבל את כתובתה. \u0003אמר רב הונא: לא שנו אלא ב\u0004זמן \u0003ש\u0004עדיין \u0003לא ניסת\u0004 (נישאה) כבר לאדם אחר, \u0003אבל\u0004 אם \u0003ניסת\u0004 כבר — \u0003אין מדירין אותה.\u0004","ומקשים: \u0003ניסת מאי טעמא\u0004 \u0005[מה הטעם]\u0006 שאין מדירים אותה — משום שאנו חוששים שמא היא משקרת, ואינה חוששת לנדור — משום שסומכת על כך ש\u0003מיפר לה בעל\u0004 כל נדר שנודרת. אם כן \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003לא ניסת נמי\u0004 \u0005[גם כן]\u0006 יש לחשוש לכך, שהיא סומכת על כך ש\u0003לכי מנסבא\u0004 \u0005[כאשר תינשא]\u0006 \u0003מיפר\u0004 (יכול להפר) \u0003לה\u0004 ה\u0003בעל!\u0004 ומשיבים: הלכה היא ש\u0003אין הבעל מיפר\u0004 (יכול להפר) \u0003בקודמין,\u0004 נדרים שקדמו לנישואין.","ושואלים: \u0003וניחוש דלמא אזלה לגבי\u0004 \u0005[ו\u0006עדיין \u0005נחשוש שמא תלך אצל]\u0006 \u0003חכם ושרי\u0004 \u0005[ויתיר]\u0006 \u0003לה\u0004 את הנדר ועל כך היא סומכת, ובאמת משקרת היא עתה! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 רב הונא, שהנודר \u0003צריך לפרט את הנדר\u0004 לפני שהחכם מתיר אותו, ובמקרה זה כאשר יוודע לחכם על מה נדרה — לא יתיר לה.","\u0003רב נחמן\u0004 חלק על רב הונא ו\u0003אמר: אפילו ניסת\u0004 מדירים יתומים את האלמנה. ושואלים: אם \u0003ניסת ודאי מיפר\u0004 (יכול להפר) \u0003לה\u0004 ה\u0003בעל!\u0004 ומשיבים: \u0003דמדרינן לה\u0004 \u0005[שמדירים אותה]\u0006 \u0003ברבים,\u0004 ובנדר שכזה בעלה אינו יכול להפר לה.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 לרב הונא ממה ששנינו בברייתא: אם \u0003ניסת\u0004 — \u0003גובה כתובתה אם נדרה. מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה ש\u0003נדרה השתא\u0004 \u0005[עכשיו]\u0006 אחרי שנישאת? ודוחים: \u0003לא,\u0004 אפשר לפרש שמדובר ש\u0003נדרה מעיקרא\u0004 \u0005[מתחילה]\u0006 לפני הנישואין.","ומקשים עוד לרב הונא: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש: \u0003ניסת\u0004 — \u0003נודרת וגובה כתובתה!\u0004 ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דאיכא למאן דאמר\u0004 \u0005[שיש מי שאומר]:\u0006 \u0003נדר שהודר ברבים\u0004 — \u0003יש לו הפרה\u0004 על ידי הבעל, ולכן גם אם הדירוה ברבים לא יועיל הדבר, ולכן תגבה כתובתה רק אם הדירוה קודם שנישאת. \u0003ואיכא למאן דאמר\u0004 \u0005[ויש מי שאומר]:\u0006 \u0003אין לו הפרה,\u0004 ולכן אם הדירוה ברבים אפילו אחרי הנישואין די בכך.","מתוך שהוזכר בדברי רב הונא שלדעתו צריך הנודר לפרט את הנדר כאשר בא להתירו בפני החכם, מביאים: \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 האם הנודר הבא לפני החכם להתיר את נדרו \u0003צריך לפרט\u0004 בפני החכם \u0003את הנדר, או אינו צריך? רב נחמן אמר: אינו צריך, רב פפא אמר: צריך.\u0004","ומסבירים את טעמיהם: \u0003רב נחמן אמר אינו צריך, דאי אמרת\u0004 \u0005[שאם אתה אומר]\u0006 ש\u0003צריך\u0004 לפרט את כל הפרטים, \u0003זימנין דגייז ליה לדיבוריה\u0004 \u0005[פעמים שהנודר גוזז,\u0006 מחסר \u0005בדיבורו]\u0006 ואינו מספר את כל פרטי הנדר, \u0003וחכם מאי דשמע\u0004 \u0005[\u0006רק \u0005מה ש\u0006הוא \u0005שומע]\u0006 \u0003מיפר\u0004 ואינו מתיר את הנדר בשלימותו. והאיש שנדרו הותר ינהג היתר גמור בנדר ואף במה שלא הופר. אלא מוטב שיתיר החכם את כל הנדר בכלל, בלי לשמוע את הפרטים.","\u0003רב פפא אמר: צריך\u0004 שיפרט את הנדר, \u0003משום מילתא דאיסורא\u0004 \u0005[דבר של איסור],\u0006 שמא היה זה נדר על דבר איסור, כגון במשנתנו שמדירים את האשה על מנת שלא תשקר, והחכם לא ידע ויתיר לו.","ומנסים להביא ראיה, \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 כהן \u0003הנושא נשים בעבירה\u0004 — \u0003פסול\u0004 מלעבוד עבודה במקדש \u0003עד שידור הנאה\u0004 מהנשים הללו על מנת לגרשן, \u0003ותני עלה\u0004 \u0005[ושנינו על כך]:\u0006 \u0003נודר, ו\u0004מיד \u0003עובד\u0004 עבודה במקדש, \u0003יורד\u0004 מן העבודה \u0003ומגרש\u0004 את אשתו הפסולה. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003אינו צריך לפרט את הנדר, ליחוש דילמא אזיל לגבי\u0004 \u0005[נחשוש שמא ילך אצל]\u0006 \u0003חכם ושרי ליה\u0004 \u0005[ויתיר לו]\u0006 את הנדר הזה, ויישאר נשוי לאשתו הפסולה, ונמצא שעבד עבודה בעודו פסול!"],["ומשיבים: \u0003דמדרינן ליה\u0004 \u0005[שמדירים אותו]\u0006 \u0003ברבים.\u0004 ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003נדר שהודר ברבים\u0004 — \u0003אין לו הפרה,\u0004 כלומר, התרה על ידי חכם. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003יש לו הפרה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006","ומשיבים: \u0003דמדרינן ליה\u0004 \u0005[שאנו מדירים אותו]\u0006 \u0003על דעת רבים,\u0004 שבלי דעתם אינו יכול להתיר. ש\u0003אמר אמימר, הלכתא\u0004 \u0005[הלכה\u0006 היא\u0005]:\u0006 \u0003אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003נדר שהודר ברבים\u0004 — \u0003יש לו הפרה,\u0004 אבל אם הודר \u0003על דעת רבים\u0004 — \u0003אין לו הפרה.\u0004","ומעירים: \u0003והני מילי\u0004 \u0005[ודברים אלה\u0006 אמורים\u0005]\u0006 דווקא \u0003לדבר הרשות, אבל\u0004 אם היה זה \u0003ל\u0004צורך \u0003דבר מצוה\u0004 — \u0003יש לו הפרה. כי\u0004 \u0005[כמו]\u0006 באותו מעשה ב\u0003ההוא מקרי דרדקי\u0004 \u0005[מלמד תינוקות אחד]\u0006 \u0003דאדריה\u0004 \u0005[שהדיר אותו]\u0006 \u0003רב אחא על דעת רבים\u0004 שלא ילמד יותר, משום \u0003דהוה פשע בינוקי\u0004 \u0005[שהיה פושע בילדים],\u0006 שהיה מכה אותם יותר מדי, \u0003ו\u0004לבסוף \u0003אהדריה\u0004 \u0005[החזיר אותו]\u0006 \u0003רבינא\u0004 למישרתו, משום ש\u0003לא אישתכח\u0004 \u0005[נמצא]\u0006 מלמד אחר \u0003דדייק כוותיה\u0004 \u0005[שהיה מדייק כמותו].\u0006","שנינו במשנה: \u0003והעדים חותמין על הגט מפני תיקון העולם.\u0004 ושואלים: האם הטעם לחתימת עדי הגט הוא \u0003מפני תיקון העולם?\u0004 הלא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא, דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וכתוב בספר וחתום\u0004 והעד עדים\u0003\"\u0004(ירמיה לב, מד)!","\u0003אמר רבה: לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא \u0003ל\u0004שיטת \u0003ר' אלעזר,\u0004 ש\u0003אמר:\u0004 \u0003עדי מסירה כרתי\u0004 \u0005[כורתים],\u0006 כלומר, שעיקר השלמתו של הגט היא דווקא בעדי מסירה, ואינו תלוי בעדי חתימה, מכל מקום \u0003תקינו רבנן\u0004 \u0005[תיקנו חכמים]\u0006 \u0003עדי חתימה מפני תיקון העולם,\u0004 ומדוע? — \u0003דזמנין דמייתי סהדי\u0004 \u0005[שפעמים שמתים העדים],\u0006 \u0003אי נמי זימנין דאזלי\u0004 \u0005[או גם כן פעמים ש\u0006הם \u0005הולכים]\u0006 \u0003למדינת הים\u0004 ויש אחרי כן ערעור על הגט, ואין לפנינו עדים שיוכלו לסלק את הערעור. וכאשר חתימותיהם של העדים מצויות אפשר לקיים את הגט על פי כתב ידם.","\u0003רב יוסף אמר: אפילו תימא\u0004 \u0005[תאמר]\u0006 שהוא \u0003ל\u0004פי שיטת \u0003ר' מאיר\u0004 שעדי חתימה הם הנותנים את התוקף לגט, ניתן להבין את הדבר, וכך צריך לפרש: \u0003התקינו שיהא עדים מפרשין שמותיהן בגיטין\u0004 ואינם מסתפקים בחתימה סתם \u0003מפני תיקון העולם.\u0004","\u0003כדתניא\u0004 \u0005[כפי ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003בראשונה היה כותב\u0004 רק \u0003\"אני פלוני חתמתי עד\", אם כתב ידו יוצא ממקום אחר\u0004 ואפשר להשוותו לחתימתו על הגט — \u0003כשר, ואם לאו\u0004 — \u0003פסול,\u0004 ואף שייתכן שהיה זה עד כשר, ונמצאו נשים מתעגנות.","\u0003אמר רבן גמליאל: תקנה גדולה התקינו, שיהיו מפרשין שמותיהן בגיטין מפני תיקון העולם,\u0004 שיכתוב \"פלוני בן פלוני\" וכל סימנים שיש לו, שאפשר יהיה לברר מי הם העדים, ולקיים על ידי זה את הגט.","ושואלים: \u0003ובסימנא לא\u0004 \u0005[ובסימן אין]\u0006 די, וחייב לחתום את שמו במלואו? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003רב צייר כורא\u0004 \u0005[היה מצייר דג]\u0006 במקום חתימה, \u0003ור' חנינא צייר חרותא\u0004 \u0005[ענף דקל],\u0006 \u0003רב חסדא\u0004 היה מצייר את האות \u0003סמך, ורב הושעיא\u0004 את האות \u0003עין, רבה בר רב הונא צייר מכותא\u0004 \u0005[מפרש]!\u0006 ומשיבים: \u0003שאני רבנן, דבקיאין סימנייהו\u0004 \u0005[שונים חכמים, ש\u0006הכל \u0005מכירים\u0006 את \u0005סימניהם].\u0006","ושואלים: \u0003מעיקרא במאי אפקעינהו\u0004 \u0005[מתחילה במה פירסמו]\u0006 את סימניהם אלה? ומשיבים: \u0003בדיסקי\u0004 \u0005[במכתבים],\u0006 שלא היה צורך משפטי בחתימה בהם, וכיון שנודע שכך הם חותמים, יכלו להסתמך על חתימתם בסימן בלבד גם בשטרות.","שנינו במשנה ש\u0003הלל התקין פרוסבול. תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]:\u0006 \u0003פרוסבול אינו משמט,\u0004 החוב אינו נשמט על ידו בשנת השמיטה. \u0003זה אחד מן הדברים שהתקין הלל הזקן, שראה את העם שנמנעו מלהלוות זה את זה\u0004 סמוך לשנת השמיטה, שחששו שהלווה לא יפרע את חובו, וכסף ההלוואה לא ישוב למלווה, \u0003ועברו על מה שכתוב בתורה \"השמר לך פן יהיה דבר עם לבבך בליעל\u0004 לאמר קרבה שנת השבע שנת השמיטה ורעה עינך באחיך האביון ולא תתן לו\u0003\"\u0004 (דברים טו, ט), \u0003עמד והתקין פרוסבול,\u0004 שאפשר יהיה לגבות את החוב גם בשמיטה, ועל ידי כך המשיכו אנשים להלוות.","\u0003וזה הוא גופו של פרוסבול,\u0004 כלומר, זהו עיקרו של שטר זה: \u0003מוסרני לכם פלוני\u0004 ופלוני \u0003דיינין שבמקום פלוני\u0004 את חובותי, \u0003שכל חוב שיש לי אצל פלוני\u0004 הואיל ונמסר לבית דין, \u0003שאגבנו כל זמן שארצה. והדיינים חותמים למטה, או העדים\u0004 ודי בכך.","ושואלים: לגופו של דבר, \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 \u0003דמדאורייתא משמטא\u0004 \u0005[שמן התורה משמטת]\u0006 \u0003שביעית\u0004 את החוב, \u0003והתקין הלל\u0004 ש\u0003לא משמטא\u0004 \u0005[תשמט]?\u0006 \u0003אמר אביי:\u0004 מדובר \u0003בשביעית בזמן הזה,\u0004 בזמננו, \u0003ו\u0004כשיטת \u0003רבי היא.\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר בפרשת שמיטת כספים: \u0003\"וזה דבר השמטה שמוט\"\u0004 (דברים טו, ב), \u0003בשתי שמיטות הכתוב מדבר: אחת שמיטת קרקע ואחת שמיטת כספים.\u0004 וכיון ששתי השמיטות הוקשו זו לזו, נלמד: \u0003בזמן שאתה משמט קרקע\u0004 כשהיובל נוהג — \u0003אתה משמט כספים, בזמן שאי\u0004 (שאין) \u0003אתה משמט קרקע,\u0004 כגון בזמן הזה שבטל היובל — \u0003אי\u0004 (אין) \u0003אתה משמט\u0004 גם \u0003כספים,\u0004"],["\u0003ותקינו רבנן\u0004 \u0005[ותיקנו חכמים]\u0006 שבכל זאת \u0003תשמט\u0004 שביעית בזמן הזה, \u0003זכר לשביעית\u0004 מן התורה. \u0003ראה הלל שנמנעו העם מלהלוות זה את זה, עמד והתקין פרוסבול.\u0004 ולפי זה לא ביטל דין תורה, אלא עשה תקנה לתקנת חכמים.","ועל הסבר זה, לפיו תיקנו חכמים שמיטת כספים בזמן הזה, למרות שמן התורה אינה משמטת, תוהים: \u0003ומי איכא מידי\u0004 \u0005[והאם יש דבר]\u0006 \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003לא משמטא\u0004 \u0005[משמטת]\u0006 \u0003שביעית, ותקינו רבנן\u0004 \u0005[ותיקנו חכמים]\u0006 ש\u0003תשמט?\u0004 ונמצא שאנשים אינם מחזירים את חובותיהם שחייבים לפורעם, והריהם בכך כגוזלים את המלווים להם!","\u0003אמר אביי:\u0004 אין זה גזל ממש, כי \u0003שב ואל תעשה הוא,\u0004 שכן הלווה אינו עושה מעשה ועוקר על ידו את מצוות התורה, אלא רק נמנע מלהשיב את חובו, ובכגון זה יכולים חכמים לתקן. \u0003רבא אמר:\u0004 יכולים חכמים לתקן תקנה כזו משום ש\u0003הפקר בית דין היה הפקר,\u0004 ש\u0003אמר ר' יצחק: מנין שהפקר בית דין היה הפקר?\u0004 — \u0003שנאמר: \"וכל אשר לא יבוא לשלשת הימים כעצת השרים והזקנים יחרם כל רכושו והוא יבדל מקהל הגולה\"\u0004 (עזרא י, ח).","\u0003ר' אליעזר אמר: מהכא\u0004 \u0005[מכאן]\u0006 יש ראיה שהפקר בית דין הפקר, שנאמר: \u0003\"אלה הנחלת אשר נחלו אלעזר הכהן ויהושע בן נון וראשי האבות\u0004 למטות בני ישראל\u0003\"\u0004 (יהושע יט, נא), ונשאלת השאלה: \u0003וכי מה ענין ראשים אצל אבות?\u0004 אלא \u0003לומר לך: מה אבות מנחילין את בניהם כל מה שירצו, אף ראשים\u0004 (מנהיגים) \u0003מנחילין\u0004 את \u0003העם כל מה שירצו.\u0004 משמע שיש כוח ביד בית דין להפקיע רכוש ולהעבירו מאיש לאיש, ומכוחם זה יכולים חכמים להחליט על שמיטת חובות.","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003התקין הלל\u0004 את תקנת ה\u0003פרוסבול\u0004 — \u0003לדריה\u0004 \u0005[לדורו\u0006 בלבד\u0005]\u0006 \u0003הוא דתקין\u0004 \u0005[שתיקן]\u0006 ואנו ממשיכים בתקנה זו משום מנהג, \u0003או דלמא לדרי עלמא נמי תקין\u0004 \u0005[שמא לדורות עולם גם כן תיקן].\u0006","ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה],\u0006 מה זה משנה אם כך או כך? ומסבירים: יש בכך הבדל אם רוצים \u0003לבטוליה\u0004 \u0005[לבטל אותו],\u0006 את הפרוסבול, שכן \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003לדריה\u0004 \u0005[לדורו]\u0006 בלבד הוא \u0003דתקין\u0004 \u0005[שתיקן]\u0006 — \u0003מבטלינן ליה\u0004 \u0005[מבטלים אנו אותו]\u0006 אם נרצה, \u0003אלא אי אמרת לדרי עלמא נמי תקין\u0004 \u0005[אם אומר אתה\u0006 ש\u0005לדורות עולם גם כן תיקן],\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין בית דין יכול לבטל דברי בית דין חברו אלא אם כן גדול הימנו בחכמה ובמנין,\u0004 ומשום כך אין אנו יכולים לבטל את דברי הלל ובית דינו. ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין בזה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 פתרון לשאלה ממה ש\u0003אמר שמואל: לא כתבינן\u0004 \u0005[אין אנו כותבים]\u0006 \u0003פרוסבול אלא אי בבי דינא\u0004 \u0005[או בבית דין]\u0006 של \u0003סורא\u0004 \u0003אי בבי דינא\u0004 \u0005[או בבית הדין]\u0006 של \u0003נהרדעא\u0004 שהן מקומות התורה הגדולים, אבל לא בכל בית דין אחר. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר כי \u0003לדרי עלמא נמי תקין\u0004 \u0005[לדורות עולם גם כן תיקן],\u0006 אם כן \u0003בשאר בי דינא נמי לכתבו\u0004 \u0005[בתי דין גם כן שיכתבו]!\u0006","ודוחים: מכאן אין ראיה, \u0003דלמא כי תקין\u0004 \u0005[שמא כאשר תיקן]\u0006 \u0003הלל לדרי עלמא\u0004 \u0005[לדורות עולם]\u0006 — תיקן דווקא לבתי דין \u0003כגון בי דינא דידיה\u0004 \u0005[בית הדין שלו]\u0006 שהיה בית דין חשוב בדורו, \u0003ו\u0004כמו בית הדין החשוב של \u0003רב אמי ורב אסי, דאלימי לאפקועי ממונא\u0004 \u0005[שכוח להם,\u0006 שבסמכותם \u0005להפקיע ממון],\u0006 \u0003אבל לכולי עלמא\u0004 \u0005[לכל העולם]\u0006 לשאר בתי דין שאינם חשובים — \u0003לא\u0004 תיקן, ואין מכאן ראיה לעצם התקנה.","ומציעים עוד: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ש\u0003אמר שמואל: הא פרוסבלא\u0004 \u0005[פרוסבול זה]\u0006 — \u0003עולבנא דדייני\u0004 \u0005[עלבון הדיינים]\u0006 \u0003הוא, אי איישר חיל אבטליניה\u0004 \u0005[אם,\u0006 אילו \u0005יישר,\u0006 יגדל \u0005כוחי אבטל אותו].\u0006 ומקשים: כיצד יכול שמואל לומר \u0003אבטליניה\u0004 \u0005[אבטל אותו]?\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אין בית דין יכול לבטל דברי בית דין חברו, אלא אם כן גדול הימנו בחכמה ובמנין!\u0004 ואם כן לכאורה משמע מכאן ששמואל סבור שהתקנה הזו לא היתה לדורות. ודוחים: \u0003הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך אפשר לפרש את דבריו: \u0003אם איישר חיל\u0004 \u0005[יישר,\u0006 יגדל \u0005כוח]\u0006 בי \u0003יותר מהלל,\u0004 שאהיה אדם גדול ממנו — \u0003אבטליניה\u0004 \u0005[אבטל אותו]\u0006 את הפרוסבול.","\u0003ו\u0004אילו \u0003רב נחמן אמר\u0004 להיפך משמואל: אם יישר כוחי \u0003אקיימנה\u0004 לתקנה זו של הפרוסבול. ותוהים: \u0003אקיימנה? הא מיקיים וקאי\u0004 \u0005[הרי מקויים ועומד]\u0006 הוא ונוהגים בפרוסבול בכל זמן, ומה צורך עוד לקיימו?! ומסבירים, \u0003הכי קאמר\u0004 \u0005[כך אמר]:\u0006 אם יגדל כוחי \u0003אימא ביה מילתא\u0004 \u0005[אומר בו דבר],\u0006 ואתקן ש\u0003אף על גב\u0004 ש\u0003לא כתוב\u0004 הפרוסבול \u0003כ\u0004אילו הוא \u0003כתוב דמי\u0004 \u0005[ייחשב]\u0006 ולא יצטרכו לכתוב כלל פרוסבול, אלא נניח בכל מקרה כאילו נכתב פרוסבול.","ומביאים: \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 שאלה זו אגב דבריו של שמואל: \u0003האי עולבנא\u0004 \u0005[\"עלבון\u0006 דיינים\" \u0005זה],\u0006 \u0003לישנא דחוצפא\u0004 \u0005[לשון של חוצפה]\u0006 \u0003הוא, או לישנא דניחותא\u0004 \u0005[לשון של עליבות]\u0006 \u0003הוא?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע],\u0006 ממה ש\u0003אמר עולא\u0004 בענין אחר: \u0003עלובה כלה שזינתה בקרב חופתה.\u0004 ודברים אלה אמר על ישראל שחטאו בעגל בזמן מתן תורה, ומשמעות \"עלובה\" כאן היא: חצופה.","\u0003אמר רב מרי ברה\u0004 \u0005[בנה]\u0006 של \u0003בת שמואל: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המרמז על חוצפה זו — \u0003\"עד שהמלך במסבו נרדי נתן ריחו\"\u0004 (שיר השירים א, יב). שהוא מפרש שבעוד שהיה המלך במסיבו, בחגיגתו (ולענין המשל — כשחגג ה' את מתן תורה לישראל), הנרד, הבושם שעל ישראל, נתן ריחו — שלא היה נעים באותה שעה, שחטאו ישראל באותו זמן. \u0003אמר רבא: עדיין חביבותא הוא גבן\u0004 \u0005[חביבות היא אצלנו],\u0006 שאף על פי שהזכיר את החטא, לא הזכיר אותו בלשון מגונה, \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"נתן\u0004 ריחו \u0003\" ולא כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"הסריח\".\u0004","ועוד במובן זה של \"עולבנא\", \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003הנעלבין ואינן עולבים\u0004 את האחרים, \u0003שומעין חרפתן ואין משיבין, עושין\u0004 דברים \u0003מאהבה ושמחין ביסורין\u0004 שבאים עליהם, \u0003עליהן הכתוב אומר: \"ואוהביו כצאת השמש בגברתו\"\u0004 (שופטים ה, לא).","שואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 לשון \u0003\"פרוסבול\"? אמר רב חסדא: פרוס\u0004 \u0005[תקנה]\u0006 של \u0003בולי ובוטי.\u0004 והוא מפרש מה עניינם:"],["\u0003בולי\u0004 — \u0003אלו עשירים,\u0004 וראיה לדבר — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"ושברתי את גאון עזכם\"\u0004 (ויקרא כו, יט), \u0003ותני\u0004 \u0005[ושנה]\u0006 \u0003רב יוסף\u0004 על פסוק זה: \u0003אלו בולאות שביהודה,\u0004 משמע שבולאות הם עשירים. \u0003בוטי\u0004 — \u0003אלו העניים,\u0004 וראיה לדבר שלשון זו קשורה בעני הזקוק להלוואה — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"\u0004ולא תקפוץ את ידך מאחיך האביון... \u0003העבט תעביטנו\"\u0004 (דברים טו, ז—ח), כלומר, הלוה לו. ופרוזבול הריהו לצורך תקנת העשירים — שלא יישמט מילווה שהלוו לעני, ולצורך תקנת העניים — שלא יימנעו מלהלוות להם. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא ללעוזא\u0004 \u0005[ללועז,\u0006 דובר יוונית\u0005]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"פרוסבול\"? אמר ליה\u0004 \u0005[לו]\u0006 \u0003פורסא דמילתא\u0004 \u0005[תקנת הדבר].\u0006","\u0003אמר רב יהודה אמר שמואל: יתומין אין צריכין פרוסבול\u0004 על מנת לגבות חובותיהם. \u0003וכן תני\u0004 \u0005[שנה\u0006 בברייתא\u0005]\u0006 \u0003רמי בר חמא: יתומין אין צריכין פרוסבול,\u0004 כיון ש\u0003רבן גמליאל ובית דינו\u0004 הריהם כמו \u0003אביהן של יתומין,\u0004 ומשום כך אפשר לומר שכל ענייני היתומים, ובכלל זה שטרותיהם, כבר מצויים ומנוהלים בידי בית דין.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שביעית: \u0003אין כותבין פרוסבול אלא על הקרקע,\u0004 אם יש ללווה קרקע. ו\u0003אם אין לו\u0004 ללווה קרקע — \u0003מזכהו\u0004 המלווה \u0003בתוך שדהו\u0004 קרקע \u0003כל שהו\u0004 כדי שיוכל לכתוב את הפרוזבול. ושואלים: \u0003וכמה\u0004 הוא שיעור זה של \u0003כל שהו? אמר רב חייא בר אשי אמר רב: אפילו\u0004 מקום לגדל בו \u0003קלח של כרוב. אמר רב יהודה: אפילו השאילו מקום לתנור ולכירים\u0004 — \u0003כותבין עליו פרוסבול.\u0004","ומקשים: \u0003איני\u0004 \u0005[\u0006האמנם \u0005כן הוא]\u0006 \u0003והתני\u0004 \u0005[והרי שנה]\u0006 \u0003הלל: אין כותבין פרוסבול אלא על\u0004 סמך \u0003עציץ נקוב בלבד.\u0004 ונדייק: \u0003נקוב\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 שעל ידי הנקב הריהו כחלק מן הקרקע, \u0003שאינו נקוב\u0004 — \u0003לא,\u0004 ואולם לדברי רב יהודה","\u0003אמאי\u0004 \u0005[מדוע]\u0006 לא? \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 \u0003מקומו\u0004 של העציץ, ולדברי רב יהודה אף שימוש במקום להניח בו חפץ נחשב לקרקע לענין זה! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דמנח אסיכי\u0004 \u0005[שמונח\u0006 העציץ \u0005על\u0006 גבי \u0005יתדות]\u0006 ואם כן, לא השאיל לו מקום בקרקע כלל.","ובאותו ענין מסופר: \u0003רב אשי\u0004 כשהיה מלווה כסף ומבקש לכתוב פרוזבול \u0003מקני ליה\u0004 \u0005[היה מקנה לו]\u0006 ללווה \u0003גידמא דדיקלא\u0004 \u0005[גדם של דקל]\u0006 שנותר מחובר לקרקע \u0003וכתב עליה\u0004 \u0005[והיה כותב עליו]\u0006 \u0003פרוסבול. רבנן דבי\u0004 \u0005[החכמים שבבית\u0006 מדרשו\u0005]\u0006 של \u0003רב אשי מסרי מילייהו להדדי\u0004 \u0005[היו מוסרים דבריהם זה לזה]\u0006 בלי לכתוב פרוסבול, אלא רק בעל פה היו אומרים: הרי אתם בית דין, והחוב מסור לכם. \u0003ר' יונתן מסר מילי\u0004 \u0005[דברים]\u0006 באותו אופן \u0003לר' חייא בר אבא, אמר ליה\u0004 \u0005[לו]\u0006 ר' חייא בר אבין: \u0003צריכנא מידי אחרינא\u0004 \u0005[\u0006האם \u0005צריך אני דבר אחר]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צריכת\u0004 \u0005[אינך צריך]\u0006 ודי באמירה בלבד.","ובענין של כתיבת פרוזבול דווקא אם יש קרקע ללווה, מביאים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין לו\u0004 ללווה \u0003קרקע, ו\u0004אולם \u0003לערב יש לו קרקע\u0004 — \u0003כותבין עליו פרוסבול.\u0004 אם גם \u0003לו ו\u0004גם \u0003לערב אין להן קרקע, ולחייב לו,\u0004 שיש אדם אחר החייב ללווה כספים \u0003יש לו קרקע\u0004 — \u0003כותבין עליו פרוסבול, מ\u0004שום דברי \u0003ר' נתן,\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' נתן אומר: מנין ל\u0004מי שהיה \u0003נושה בחברו מנה\u0004 שהוא חייב לו, \u0003וחברו\u0004 זה היה גם כן נושה \u0003בחברו\u0004 שלו גם כן מנה, \u0003מנין ש\u0004בית דין \u0003מוציאין מזה,\u0004 מן הלווה האחרון, \u0003ונותנין לזה,\u0004 למלווה הראשון, ואין צורך שכל אחד יתן לנושה הישיר שלו? — \u0003תלמוד לומר\u0004 בקשר להשבת גזילה: \u0003\"ונתן לאשר אשם לו\"\u0004 (במדבר ה, ז), ומדייקים מן הלשון \"אשם\" (חייב), שיש שהכסף ניתן למי שבסופו של דבר חייבים לו, כגון בעל חוב של הנגזל.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת שביעית: \u0003השביעית משמטת את המלוה, בין\u0004 שהיה זה חוב \u0003בשטר בין שלא בשטר.\u0004 ונחלקו אמוראים בפירוש המשנה, \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בשטר\u0004 — הכוונה היא \u0003שטר שיש בו אחריות,\u0004 שעבוד \u0003נכסים, שלא בשטר\u0004 — כוונתו שטר \u0003שאין בו אחריות נכסים; כל שכן מלוה על פה\u0004 שבוודאי השביעית משמטת.","ואילו \u0003ר' יוחנן ור' שמעון בן לקיש דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003בשטר\u0004 — הכוונה היא \u0003שטר שאין בו אחריות נכסים, שלא בשטר\u0004 — כוונתו \u0003מלוה על פה. אבל שטר שיש בו אחריות נכסים\u0004 — \u0003אינו משמט,\u0004 שהרי זה כאילו כבר יש בידו קרקע של הלווה.","\u0003תניא כותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתם]\u0006 של \u0003ר' יוחנן ור' שמעון בן לקיש: שטר חוב\u0004 — \u0003משמט, ואם יש בו אחריות נכסים\u0004 — \u0003אינו משמט. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת\u0006\u0005]:\u0006 \u0003סיים\u0004 (הגדיר) \u0003לו\u0004 הלווה למלווה לצורך פרעון החוב \u0003שדה אחת בהלוואתו,\u0004 שעשה שדה זו כמיועדת לפרעון החוב — \u0003אינו משמט. ולא עוד אלא, אפילו כתב \"כל נכסיי אחראין וערבאין לך\"\u0004 אף שלא ייחד לכך שדה מסויימת — \u0003אינו משמט.\u0004","מסופר: \u0003קריביה\u0004 \u0005[קרובו]\u0006 של \u0003ר' אסי הוה ליה ההוא שטרא דהוה כתיב ביה\u0004 \u0005[היה לו שטר אחד שהיה כתוב בו]\u0006 \u0003אחריות נכסים, אתא לקמיה\u0004 \u0005[בא לפני]\u0006 \u0003ר' אסי, אמר ליה\u0004 \u0005[לו]\u0006 בשאלה: שטר זה \u0003משמט או אינו משמט? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אינו משמט. שבקיה ואתא לקמיה\u0004 \u0005[הניח אותו ובא לפני]\u0006 \u0003ר' יוחנן\u0004 ושאלו אותה שאלה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003משמט.\u0004","\u0003אתא\u0004 \u0005[בא]\u0006 \u0003ר' אסי לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן, אמר ליה\u0004 \u0005[לו]:\u0006 שטר כזה \u0003משמט או אינו משמט? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003משמט,\u0004 והקשה לו: \u0003והא מר\u0004 \u0005[והרי אדוני]\u0006 \u0003הוא\u0004 ש\u0003אמר\u0004 בעצמו ששטר שיש בו אחריות \u0003אינו משמט, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003וכי מפני שאנו מדמין\u0004 וחושבים שכך צריכה להיות ההלכה, \u0003נעשה מעשה? אמר ליה\u0004 \u0005[לו]:\u0006 \u0003והתניא כוותיה דמר\u0004 \u0005[והרי שנויה\u0006 ברייתא \u0005כשיטתו של אדוני]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דלמא ההיא\u0004 \u0005[שמא אותה\u0006 ברייתא\u0005]\u0006 כשיטת \u0003בית שמאי היא, דאמרי\u0004 \u0005[ש\u0006הם \u0005אומרים]\u0006 בכלל: \u0003שטר העומד לגבות כגבוי דמי\u0004 \u0005[נחשב],\u0006 ומשום כך אינו משמט, שהרי אותו שטר שוב אין נדון כחוב, שהרי נחשב הוא כבר כפרוע.","\u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במשנה במסכת שביעית: \u0003המלוה את חבירו מעות על המשכון, והמוסר שטרותיו לבית דין\u0004 — \u0003אין משמטין.\u0004 ושואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 במקרה של \u0003מוסר שטרותיו לבית דין,\u0004 אנו אומרים: \u0003דתפסי להו בי דינא\u0004 \u0005[שתופסים אותם,\u0006 את השטרות, \u0005בית הדין]\u0006 ובידם לגבות את החוב. \u0003אלא מלוה על המשכון מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר שאין החוב נשמט?","\u0003אמר רבא: משום דתפס ליה\u0004 \u0005[ש\u0006הוא, המלווה, \u0005תופס לו]\u0006 משהו מסויים, והרי זה כאילו נגבה החוב. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה,\u0004 לפי שיטה זו, אם \u0003הלוהו ודר\u0004 המלווה \u0003בחצרו דתפיס ליה\u0004 \u0005[ש\u0006הוא \u0005תופס לו\u0006 משהו\u0005],\u0006 \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 תאמר ש\u0003לא משמט?\u0004 והרי אין הלכה כך!","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003משכון, דקני ליה\u0004 \u0005[שקונה אותו]\u0006 המלווה לעצמו \u0003מ\u0004דברי \u0003ר' יצחק,\u0004 ש\u0003אמר ר' יצחק: מנין לבעל חוב שקונה משכון?\u0004 — \u0003שנאמר\u0004 בדברי התורה למלווה המשיב את המשכון בלילה: \u0003\"ולך תהיה צדקה\"\u0004 (דברים כד, יג), ומכאן נלמד שכך הוא, שהרי \u0003אם\u0004 המלווה \u0003אינו קונה\u0004 את המשכון — \u0003צדקה מנין?\u0004 והרי הוא מחזיר לבעליו את השייך לו, אלא \u0003מכאן לבעל חוב שקונה משכון,\u0004 ומה שנותן ללווה הריהו כנותן צדקה משל עצמו.","עוד \u0003תנן התם\u0004 \u0005[שנינו שם]\u0006 במסכת שביעית:"],["\u0003המחזיר חוב לחבירו בשביעית\u0004 — \u0003צריך\u0004 המלווה \u0003שיאמר לו \"משמט אני\", ואם אמר לו\u0004 הלווה \u0003\"אף על פי כן\u0004 רוצה אני שתקבל ממני את חובי \u0003\"\u0004— \u0003יקבל הימנו, שנאמר: \"וזה דבר השמטה\"\u0004 (דברים טו, ב), ללמדנו שדי בכך שהמלווה מצהיר ואומר שהוא משמט, ואינו חייב לוותר על החוב אם הלווה רוצה להחזיר.","\u0003אמר רבה: ותלי ליה\u0004 \u0005[ו\u0006יכול המלווה \u0005לתלות\u0006 עיניו \u0005בו]\u0006 ולהראות לו שרצונו לקבל את החוב \u0003עד דאמר הכי\u0004 \u0005[שיאמר\u0006 הלווה \u0005כך]\u0006 שבכל זאת הוא מחזיר. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003אביי\u0004 ממה ששנינו: \u0003כשהוא,\u0004 הלווה, \u0003נותן לו\u0004 למלווה, כשמחזיר לו חוב בשנת השמיטה, \u0003אל יאמר לו \"בחובי אני נותן לך\", אלא יאמר לו \"שלי הן ובמתנה אני נותן לך\",\u0004 ומכאן משמע שהדבר נעשה מיוזמתו וברצונו החופשי של הלווה! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003תלי ליה נמי\u0004 \u0005[\u0006יכול המלווה \u0005לתלות לו\u0006 עיניו \u0005גם כן]\u0006 \u0003עד דאמר הכי\u0004 \u0005[שיאמר\u0006 הלווה \u0005כך]\u0006 ואין צורך בנתינה מתוך רצון גמור.","מסופר: \u0003אבא בר מרתא,\u0004 ש\u0003הוא\u0004 הנקרא גם \u0003אבא בר מניומי, הוה מסיק ביה\u0004 \u0005[היה נושה בו]\u0006 \u0003רבה זוזי\u0004 \u0005[מעות]\u0006 בחובו, \u0003אייתינהו ניהליה\u0004 \u0005[הביאן לו]\u0006 \u0003בשביעית, אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003משמט אני. שקלינהו ואזל\u0004 \u0005[לקחן\u0006 אבא בר מרתא את המעות \u0005והלך].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אביי\u0004 לרבה \u0003אשכחיה דהוה עציב\u0004 \u0005[מצא אותו שהוא עצוב],\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמאי עציב מר\u0004 \u0005[מדוע עצוב אדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הכי הוה\u0004 \u0005[כך היה]\u0006 \u0003מעשה,\u0004 שאבא בר מרתא הבין את הדברים כמשמעם ולא השיב את החוב.","\u0003אזל לגביה\u0004 \u0005[הלך\u0006 אביי \u0005אליו],\u0006 אל אבא בר מרתא, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אמטת ליה זוזי למר\u0004 \u0005[הבאת לו\u0006 את \u0005המעות לאדוני]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 \u0003אמר לך? אמר ליה\u0004 \u0005[לו]:\u0006 אמר לי \u0003\"משמט אני\".\u0004 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003ו\u0004האם \u0003אמרת ליה\u0004 \u0005[לו]\u0006 \u0003\"אף על פי כן\"? אמר ליה\u0004 \u0005[לו]\u0006 אבא בר מרתא: \u0003לא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ואי אמרת ליה\u0004 \u0005[ואם היית אומר לו]\u0006 \u0003\"אף על פי כן\" הוה שקלינהו מינך\u0004 \u0005[היה לוקחן ממך],\u0006 \u0003השתא מיהת אמטינהו ניהליה\u0004 \u0005[עכשיו על כל פנים הבא אותן אליו]\u0006 \u0003ואימא ליה\u0004 \u0005[ואמור לו]\u0006 \u0003\"אף על פי כן\". אזל אמטינהו ניהליה\u0004 \u0005[הלך הביאן אליו]\u0006 \u0003ואמר ליה\u0004 \u0005[לו]\u0006 \u0003\"אף על פי כן\". שקלינהו מיניה\u0004 \u0005[לקחן ממנו],\u0006 בסוף \u0003אמר\u0004 רבה: \u0003לא הוה ביה דעתא\u0004 \u0005[היתה בו דעת]\u0006 \u0003בהאי צורבא מרבנן מעיקרא\u0004 \u0005[בתלמיד חכם זה מתחילה]\u0006 שהיה צריך ללמד אותו מה יאמר.","\u0003אמר רב יהודה אמר רב נחמן: נאמן אדם לומר \"פרוסבול היה בידי ואבד ממני\"\u0004 ויגבה חובו. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003כיון דתקינו רבנן\u0004 \u0005[שתיקנו חכמים]\u0006 תקנה זו של \u0003פרוסבול\u0004 באופן שקל לעשותה, בוודאי שבמקרה שכזה אדם \u0003לא שביק היתירא ואכיל איסורא\u0004 \u0005[אינו מניח היתר ואוכל איסור],\u0006 ולכן מאמינים אנו לדבריו שבוודאי היה בידו פרוסבול.","\u0003כי אתו לקמיה\u0004 \u0005[כשהיו באים לפני]\u0006 \u0003רב\u0004 עם מקרה כזה, של תביעה של חוב לאחר שנת השמיטה ובידי המלווה לא היה פרוסבול \u0003אמר ליה\u0004 \u0005[היה אומר לו]\u0006 למלווה: \u0003מידי\u0004 \u0005[וכי]\u0006 \u0003פרוסבול היה לך ואבד?\u0004 ומסבירים שבדבר \u0003כגון זה \"פתח פיך לאלם\"\u0004 (משלי לא, ח) \u0003הוא,\u0004 ואין אומרים שהוא מתערב בכך לטובת אחד הצדדים, אלא רק מסייע לאדם שלא עלה בדעתו לומר את מה שצריך לטעון.","ומקשים, והרי \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003וכן בעל חוב שמוציא שטר חוב ואין עמו פרוסבול\u0004 — \u0003הרי אלו לא יפרעו.\u0004 הרי שבלא פרוסבול, אפילו כאשר יש טענת אבידה בפי המלווה, נשמט החוב!","ומשיבים: \u0003תנאי\u0004 \u0005[\u0006מחלוקת \u0005תנאים]\u0006 \u0003היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003המוציא שטר חוב\u0004 בשביעית — \u0003צריך שיהא עמו פרוסבול\u0004 כדי שלא יישמט. \u0003וחכמים אומרים: אינו צריך\u0004 שיהא עימו פרוסבול, אלא סומכים על המלווה שמן הסתם עשה פרוסבול.","\u0003עבד\u0004 כנעני \u0003שנשבה ופדאוהו, אם\u0004 פדאוהו \u0003לשום\u0004 (לשם) \u0003עבד\u0004 — \u0003ישתעבד\u0004 לאלו שפדאוהו, \u0003אם\u0004 פדאוהו \u0003לשום\u0004 (לשם) \u0003בן חורין\u0004 — \u0003לא ישתעבד. רבן שמעון בן גמליאל אומר: בין כך ובין כך ישתעבד.\u0004","ומבררים: \u0003במאי עסקינן\u0004 \u0005[במה אנו עוסקים]\u0006 במשנה זו? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה זה \u0003לפני יאוש,\u0004 שהבעלים הראשונים עדיין לא התייאשו מן העבד, אפילו פדאוהו אם כן \u0003לשום בן חורין אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא ישתעבד?\u0004 הלא הוא עדיין ברשות בעליו! \u0003אלא\u0004 אומר אתה שהיה זה \u0003לאחר יאוש,\u0004 אולם אז גם אם פדאוהו \u0003לשום עבד, אמאי\u0004 \u0005[מדוע]\u0006 \u0003ישתעבד?\u0004 הרי מחמת היאוש נעשה כהפקר, וקנה את עצמו לחירות!","\u0003אמר אביי,\u0004 כך צריכים לפרש את המשנה: \u0003לעולם\u0004 מדובר כאן \u0003לפני יאוש, ו\u0004לפיכך, לדעת סתם משנה, אם פדאוהו \u0003לשום עבד\u0004 — \u0003ישתעבד לרבו ראשון,\u0004 ואם פדאוהו \u0003לשום בן חורין\u0004 — \u0003לא ישתעבד לא לרבו ראשון ולא לרבו שני\u0004 (כלומר, לזה שפדאו), ומדוע? \u0003לרבו שני לא\u0004 ישתעבד, \u0003דהא לשום\u0004 \u0005[שהרי לשם]\u0006 \u0003בן חורין פרקיה\u0004 \u0005[פדה אותו],\u0006 ואם כן אינו יכול עכשיו לתבוע לעשות אותו עבד. \u0003לרבו ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003לא, דילמא ממנעי\u0004 \u0005[שמא ימנעו]\u0006 אנשים \u0003ולא פרקי\u0004 \u0005[יפדו]\u0006 עבדים שנשבו אם ידעו שהפדוי חוזר להיות עבד של רבו הראשון.","\u0003רבן שמעון בן גמליאל אומר: בין כך ובין כך ישתעבד\u0004 לרבו ראשון. ומסבירים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כשם שמצוה לפדות את בני חורין, כך מצוה לפדות את העבדים,\u0004 ומשום כך אין חוששים שלא יבואו לפדות עבדים שנשבו.","\u0003רבא אמר:\u0004 צריך להבין את המשנה אחרת, \u0003לעולם\u0004 מדובר פה \u0003לאחר יאוש, ו\u0004לפיכך, לדעת סתם משנה, אם פדאוהו \u0003לשום עבד\u0004 — \u0003ישתעבד לרבו שני,\u0004 שהרי הראשון נתייאש ממנו. אם פדאוהו \u0003לשום בן חורין\u0004 — \u0003לא ישתעבד לא לרבו ראשון ולא לרבו שני,\u0004 ומדוע לא ישתעבד? — \u0003לרבו שני לא, דהא לשום\u0004 \u0005[שהרי לשם]\u0006 \u0003בן חורין פרקיה\u0004 \u0005[פדה אותו],\u0006 \u0003לרבו ראשון נמי\u0004 \u0005[גם כן]\u0006 \u0003לא, דהא\u0004 \u0005[שהרי]\u0006 \u0003לאחר יאוש הוה\u0004 \u0005[היה]\u0006 הדבר.","ומה ש\u0003רבן שמעון בן גמליאל אומר: בין כך ובין כך ישתעבד\u0004 — דבר זה יש להבין \u0003כ\u0004דברי \u0003חזקיה,\u0004 ש\u0003אמר חזקיה: מפני מה אמרו בין כך ובין כך ישתעבד? שלא יהא כל אחד ואחד\u0004 מן העבדים \u0003הולך ומפיל\u0004 (מסגיר) את \u0003עצמו לגייסות\u0004 של גויים \u0003ומפקיע עצמו\u0004 באופן כזה \u0003מיד רבו.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים\u0006 על כך\u0005]\u0006 ממה ששנינו בברייתא, \u0003אמר להן רבן שמעון בן גמליאל: כשם שמצוה לפדות את בני חורין, כך מצוה לפדות את העבדים. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003אביי,\u0004 ש\u0003אמר\u0004 שמדובר כאן \u0003לפני יאוש,\u0004 וטעמה של סתם משנה שלא ישתעבד לרבו הראשון — משום חשש שיימנעו אנשים מלפדות עבדים, \u0003היינו דקאמר\u0004 \u0005[זהו\u0006 הטעם \u0005שהוא אומר]\u0006 \u0003\"כשם\",\u0004 שזהו הטעם לדבריו, שאין חשש בדבר.","\u0003אלא לרבא,\u0004 ש\u0003אמר\u0004 שמדובר כאן \u0003לאחר יאוש,\u0004 ואין סתם משנה חוששת שיימנעו מלפדות עבדים, האם \u0003האי\u0004 \u0005[\u0006דבר \u0005זה]\u0006 הוא משום מה שאמר רבן שמעון בן גמליאל \u0003\"כשם\u0004 שמצוה לפדות \u0003\"?\u0004 הלא \u0003משום\u0004 הטעם של \u0003חזקיה הוא!\u0004","ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך רבא: רבן שמעון בן גמליאל לא הוי ידע מאי קאמרי רבנן\u0004 \u0005[לא ידע מה אומרים חכמים]\u0006 בדיוק, \u0003והכי קאמר להו\u0004 \u0005[וכך אמר להם]:\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003לפני יאוש קאמריתו\u0004 \u0005[אומרים אתם],\u0006 \u0003היינו,\u0004 אני אומר לכם את הנימוק \u0003\"כשם\", אי\u0004 \u0005[אם]\u0006 \u0003לאחר יאוש קאמריתו\u0004 \u0005[אתם אומרים]\u0006 הרי הטעם הוא \u0003כ\u0004דברי \u0003חזקיה.\u0004","ושואלים: \u0003ול\u0004שיטת \u0003רבא,\u0004 ש\u0003אמר\u0004 שמדובר פה \u0003לאחר יאוש, ו\u0004הכוונה היא שמשתעבד \u0003לרבו שני,\u0004 יש לשאול: והרי \u0003רבו שני ממאן קני ליה\u0004 \u0005[ממי קנה אותו],\u0006 ממי זכה בו — \u0003משבאי,\u0004 ממי שלקח אותו בשבי, ואולם \u0003שבאי גופיה\u0004 \u0005[עצמו]\u0006 שהוא גוי, \u0003מי קני ליה\u0004 \u0005[האם קונה אותו]\u0006 האם יש לו קנין בעבד, שמשום כך אפשר לקנות אותו ממנו כעבד?","ומשיבים: \u0003אין\u0004 \u0005[כן],\u0006 \u0003קני ליה\u0004 \u0005[קונה אותו]\u0006 \u0003למעשה ידיו\u0004 שבזה יש לו זכות, ש\u0003אמר ריש לקיש: מנין לגוי שקנה את הגוי\u0004 האחר כעבד \u0003למעשה ידיו? — שנאמר: \"וגם מבני התושבים הגרים עמכם מהם תקנו\"\u0004 (ויקרא כה, מה), לומר: \u0003אתם קונים מהם,\u0004 לכם יש קנין בהם,"]]};
